window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gineco-gin-6"]={"block":"medcurso:medcurso-gineco-gin-6","label":"Medcurso · GIN 6","count":429,"questions":[{"id":"medcurso-gineco-gin-6-343758","number":"343758","sourceNumber":"343758","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 36 anos, G3N2, 24 semanas de gestação, comparece à UBS para iniciar o\npré-natal. Ao realizar o teste rápido de HIV, o primeiro exame deu positivo. Foi realizado um\nsegundo teste rápido diferente, validado pelo Departamento de DST/AIDS, que também veio\nreagente. Em relação ao caso clínico, responda a alternativa correta.","options":{"A":"A paciente deverá realizar um terceiro exame sorológico, coletado através de punção venosa\npara confirmar o diagnóstico, e, caso confirmado,\ndeverá iniciar o esquema terapêutico.","B":"A paciente apresenta o diagnóstico de infecção pelo HIV e deverá iniciar o esquema\nantirretroviral no momento do diagnóstico,\nassim como fazer a coleta dos exames de genotipagem\nviral, carga viral e CD4.","C":"A paciente apresenta o diagnóstico de HIV, porém deve primeiro aguardar o resultado dos\nexames de genotipagem viral, CD4 e carga viral\npara melhor escolha do antirretroviral.","D":"A paciente deverá confirmar o diagnóstico através de sorologia, fazer a coleta do CD4 e carga\nviral, e dependendo do seu estado imunológico, avaliar a necessidade de tratamento com\nantirretroviral."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343762","number":"343762","sourceNumber":"343762","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 38 anos, comparece ao consultório referindo dor pélvica há aproximadamente 1\nano, com piora no período menstrual ou no coito. Nega alteração do fluxo menstrual e leucorreia.\n\nNega outras queixas e antecedentes pessoais patológicos. G3/3PN, em uso de anticoncepcional\nhormonal oral cíclico. Exame físico geral\nnormal. Especular: colo grande, hiperemiado, orifício\ncervical em fenda, secreção endocervical acinzentada, viscosa, sem odor. TV: Útero em AVF,\nmóvel, doloroso a mobilização, volume normal. Anexos impalpáveis. Ciclo menstrual de 4 dias, com\nfluxo normal; Diante da história clínica, qual o provável diagnóstico e tratamento preconizado?","options":{"A":"Adenomiose - histerectomia.","B":"Endometriose - Análogos de GnRh.","C":"DIP - doxiciclina + ceftriaxona + metronidazol.","D":"Cervicite - azitromicina."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343770","number":"343770","sourceNumber":"343770","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Tanto para o tratamento ambulatorial como para o tratamento clínico hospitalar da DIP\nobserva-se a seguinte recomendação:","options":{"A":"Usar monoquimioterapia.","B":"Usar sempre tiafenicol.","C":"Usar sempre penicilina cristalina.","D":"Usar poliquimioterapia."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343774","number":"343774","sourceNumber":"343774","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São considerados subtipos de HPV de alto risco para neoplasia cervical:","options":{"A":"16 e 18.","B":"16 e 6.","C":"6 e 11.","D":"11 e 42."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-345483","number":"345483","sourceNumber":"345483","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente 70 anos com queixa de prurido vaginal, secreção vaginal esbranquiçada e\ngrumosa, sem odor. Ao exame ginecológicos, observa-se vulva hiperemiada. Especular: placas\nbrancas e grumosa em parede vaginal. Com base neste quadro clínico, assinale a alternativa que\napresenta o diagnóstico e tratamento:","options":{"A":"Líquen escleroso - mometasona tópica.","B":"Vaginose - metronidazol via oral.","C":"Líquen atrófico - promestrieno via vaginal.","D":"Candidíase - miconazol via vaginal."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-281132","number":"281132","sourceNumber":"281132","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 25 anos apresenta febre e dor intensa no baixo-ventre. Ao toque bimanual,\nrefere dor à mobilização do colo uterino.\nPalpa-se massa anexial. Os exames mostram leucocitose\ncom desvio para a esquerda, VHS e proteína C reativa elevados. A ultrassonografia transvaginal\nrevela imagem cística anexial de conteúdo espesso medindo 4cm de diâmetro. A conduta imediata\né:","options":{"A":"Laparotomia exploradora","B":"Antibiótico aerobicida e anaerobicida parenteral","C":"Aspiração guiada por ultrassonografia","D":"Drenagem por culdotomia","E":"Laparoscopia cirúrgica"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-283331","number":"283331","sourceNumber":"283331","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O tratamento indicado para o cancro mole durante a gestação é:","options":{"A":"Doxiciclina.","B":"Eritromicina.","C":"Tetraciclina.","D":"Sulfas."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-283341","number":"283341","sourceNumber":"283341","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 61 anos de idade, diabética insulino dependente mal controlada. Apresenta\ndor e irritação da vulva e raiz das coxas\ncom intensa hiperemia. O diagnóstico é:","options":{"A":"Neoplasia intra-epitelial da vulva.","B":"Infecção por HPV.","C":"Candidíase.","D":"Pênfigo."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-283343","number":"283343","sourceNumber":"283343","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Nulípara de 18 anos de idade sofreu estupro que resultou em gravidez. Traz boletim de\nocorrência policial e solicitação de interrupção da gestação de 7 semanas. A idade gestacional pela\necografia é compatível com a data do estupro. A conduta recomendada para a interrupção é:","options":{"A":"Dilatação e curetagem sob anestesia geral.","B":"Aspiração intra-uterina sob bloqueio regional.","C":"Aspiração intra-uterina sob sedação e anestesia local.","D":"Dilatação e curetagem sob sedação."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-251868","number":"251868","sourceNumber":"251868","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O paciente com sífilis e que possui história de reação alérgica evidente à penicilina\ndeverá ser:","options":{"A":"Tratado com eritromicina.","B":"Tratado com doxiciclina.","C":"Tratado com cefalexina.","D":"Tratado com penicilina procaína."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-251885","number":"251885","sourceNumber":"251885","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher com 19 anos de idade, primigesta, com gestação de 22 semanas, procura\nAtendimento obstétrico por apresentar lesões\nulceradas, rasas e dolorosas em vulva, iniciadas há\num dia, acompanhada de febre não aferida e mal-estar geral. Relata que o quadro se iniciou há três\ndias, precedido por sensação de queimação no local. Nega qualquer lesão semelhante anterior.\n\nNão se observam alterações em gânglios inguinais. A hipótese diagnóstica e a conduta corretas\npara a paciente são, respectivamente:","options":{"A":"Cancro mole; iniciar doxicilina.","B":"Herpes genital; iniciar aciclovir oral.","C":"Donovanose; iniciar penicilina benzatina.","D":"Sífilis primária; iniciar penicilina benzatina."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-251896","number":"251896","sourceNumber":"251896","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A presença de petéquias no colo uterino sugere o diagnóstico de:","options":{"A":"Monilíase.","B":"Congestão pélvica.","C":"Tricomoniase vaginal.","D":"Púrpura trombocitopênica."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-217721","number":"217721","sourceNumber":"217721","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao teste para HIV na gestação é CORRETO afirmar:","options":{"A":"Não deve ser sugerido para pacientes incluídas nas populações de baixo risco.","B":"A lei requer um rastreamento universal.","C":"Aconselha-se a realização de um rastreamento universal com notificação à paciente.","D":"É realizado de rotina sem consentimento da paciente, nas populações de alto risco."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-217699","number":"217699","sourceNumber":"217699","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"J.J., 2 anos, sexo feminino, é levada pela mãe ao médico de família, apresentando\nlesões verrucosas em região perineal e corrimento\npurulento. A criança vive com os pais. Durante\nas manhãs fica sob os cuidados da avó materna. A conduta neste caso é:","options":{"A":"Realizar a notificação de caso suspeito de violência.","B":"Aguardar resultado de exame pericial confirmatório para realizar a notificação.","C":"Realizar coleta de biópsia para confirmação diagnóstica e, posteriormente realizar a\nnotificação.","D":"Encaminhar a criança para atenção secundária para nesse nível ser realizada a notificação."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182656","number":"182656","sourceNumber":"182656","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Criança, 4 anos, apresentando corrimento amarelado com odor fétido e prurido vulvar.\nQual a principal causa desse quadro nesta faixa etária?","options":{"A":"Candidíase vaginal.","B":"Corpo estranho.","C":"Má higiene.","D":"Trichuris trichiura."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182670","number":"182670","sourceNumber":"182670","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A sífilis é causada pelo Treponema pallidum, transmitida predominantemente pelo\ncontato sexual. O contágio é maior nos\nestágios iniciais da infecção, sendo reduzido\ngradativamente à medida que ocorre progressão da doença (OMS, 2015; BRASIL, 2015). Quanto\nao diagnóstico e manejo da sífilis, assinale a alternativa CORRETA:","options":{"A":"O primeiro teste imunológico a tornar-se reagente, em torno de 10 dias da evolução do cancro\nduro, é o FTA-Abs. Este é seguido pelos\noutros testes, treponêmicos e não treponêmicos.","B":"Quanto mais tardio for o tratamento, maior será a possibilidade do resultado do teste\npermanecer reagente para sempre. Porém, os\ntítulos encontrados nos testes não treponêmicos\nserão baixos (entre 1:2 a 1:4), e os testes treponêmicos serão reagentes. Esses resultados podem\npermanecer estabilizados pelo resto da vida, sem que isso indique a necessidade de retratamento.","C":"A possibilidade de reinfecção deve ser considerada quando um paciente previamente tratado\napresentar o aumento do título em duas ou mais diluições no teste não treponêmico quantitativo,\nquando comparado com os resultados dos testes anteriores.","D":"Todas as alternativas estão corretas."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182720","number":"182720","sourceNumber":"182720","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A presença de petéquias no colo uterino sugere o diagnóstico de:","options":{"A":"Monilíase.","B":"Congestão pélvica.","C":"Tricomoniase vaginal.","D":"Púrpura trombocitopênica."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-159102","number":"159102","sourceNumber":"159102","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O tratamento de tricomoníase deve ser sistêmico, já que o tratamento tópico não atinge\nníveis terapêuticos na uretra e glândulas vaginais. Assinale a alternativa abaixo o esquema\nterapêutico preconizado pelo CDC:","options":{"A":"Fluconazol, 150 mg, dose única.","B":"Doxacicilina, 100 mg, 2 x dia 14 dias.","C":"Metronidazol, 2 g, dose única.","D":"Azitromicina, 1 g, dose única."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-159043","number":"159043","sourceNumber":"159043","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Dentre os fatores abaixo, qual NÃO é considerado um fator de risco para vaginose\nbacteriana?","options":{"A":"Tabagismo.","B":"Múltiplos ou novos parceiros.","C":"Uso de anticoncepcional oral hormonal.","D":"Raça negra."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-159114","number":"159114","sourceNumber":"159114","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em caso de doença inflamatória pélvica aguda, a melhor terapêutica na Unidade Básica\nde Saúde deve basear-se em:","options":{"A":"Ceftriaxone 250 mg IM em dose única + Doxiciclina 100 mg via oral, por 14 dias.","B":"Cefoxitina 2g IM em dose única + Metronidazol 500 mg via oral, por 10 dias.","C":"Creme vaginal à base de sulfa, duas vezes ao dia, por 14 dias.","D":"Metronidazol 500 mg via oral de 12/12h, por 14 dias."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-108778","number":"108778","sourceNumber":"108778","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Candidíase vulvovaginal recorrente é definida como quatro ou mais episódios de\ndoença sintomática no período de um ano. Após a\nmenarca, a incidência de candidíase aumenta e\npicos acontecem ao longo da faixa etária entre os 30 e 40 anos. Assinale a alternativa que\ncorresponda aos fatores predisponentes a candidíase vulvovaginal.","options":{"A":"Diabetes Mellitus e uso de DIU.","B":"Imunossupressão, gravidez e tricomoníase;","C":"Desequilibrio dos hormônios reprodutivos (menopausa) e uso de contraceptivos hormonais orais;","D":"Uso de antibióticos, hipersensibilidade a agentes coloridos e perfumados, papel higiênico e\naditivos para água de banho."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-108796","number":"108796","sourceNumber":"108796","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 25 anos, com vida sexual ativa, usuária de contraceptivos combinados em\nunião estável, queixa-se de ferida vulvar há cerca de seis semanas. Ao exame, foi constatado\núlcera vulvar. Qual a conduta recomendada pelo Ministério da Saúde do Brasil, seguindo uma\nabordagem sindrômica?","options":{"A":"Tratar sífilis e cancro mole;","B":"Tratar como abscesso de ducto de glândula de Bartholin;","C":"Solicitar VDRL e tratar como sífilis;","D":"Tratar sífillis, cancro mole, biopsiar e tratar donovanose."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-84479","number":"84479","sourceNumber":"84479","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Na investigação clínica de Doenças Inflamatórias Pélvicas, na presença de leucorréia,\no odor de \"peixe podre\", no Teste das Aminas,\ndecorre da liberação de:","options":{"A":"Ácido sulfídrico das bactérias aeróbicas lisadas pelo KOH (hidróxido de potássio).","B":"Amônia presente nas membranas das bactérias anaeróbicas.","C":"Gás metano liberado pela lise das membranas das bactérias anaeróbicas.","D":"Aminas, provenientes do metabolismo anaeróbio, em contacto com o KOH.","E":"Aminas e ácido sulfrídico, provenientes do metabolismo anaeróbio."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-66952","number":"66952","sourceNumber":"66952","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 20a, G3P2A1, queixa-se de dor em baixo-ventre, corrimento com mau cheiro,\nsem prurido associado e febre não aferida há 2\ndias. Nega uso de método anticoncepcional e relata\nmais de 5 parceiros nos últimos 12 meses. Exame especular: descarga vaginal fluida, fétida,\nbranca, com pequenas bolhas. Toque vaginal: dor à mobilização de órgãos pélvicos. A (s) hipótese\n\n(s) diagnosticada (s) é (são):","options":{"A":"Infecção do trato urinário e doença inflamatória pélvica.","B":"Tricomoníase vaginal.","C":"Vulvovaginite fúngica e infecção do trato urinário.","D":"Doença inflamatória pélvica e vaginose bacteriana."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-66965","number":"66965","sourceNumber":"66965","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"É ATITUDE CORRETA para o parceiro sexual, não presente à consulta, de paciente\ndiagnosticada com candidíase vaginal recidivante:","options":{"A":"Prescrever fluconazol oral em dose única;","B":"Dispensar nistatina creme para uso local por 10 dias;","C":"Solicitar uma cultura para fungos do raspado de glande;","D":"Orientar para que ele procure um médico."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-66984","number":"66984","sourceNumber":"66984","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em caso de suspeita de herpes genital, qual dos seguintes exames deveria ser\nrealizado em primeiro lugar?","options":{"A":"Exame de campo escuro;","B":"Teste de Frei;","C":"Coloração de Gram;","D":"Esfregaço de Tzanck."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-341068","number":"341068","sourceNumber":"341068","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 20 anos de idade, em uso de adesivo como método contraceptivo refere prurido\nvaginal intenso, há três dias, associado a corrimento grumoso e esverdeado, sem odor fétido. Nega\nfebre. Ao exame: colpite difusa. Identifique o provável agente etiológico, nesse caso:","options":{"A":"Gardnerella vaginalis.","B":"Trichomonas vaginalis.","C":"Candida albicans.","D":"Clamídia Trachomatis."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-341069","number":"341069","sourceNumber":"341069","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 20 anos de idade, em uso de adesivo como método contraceptivo refere prurido\nvaginal intenso, há três dias, associado a corrimento grumoso e esverdeado, sem odor fétido. Nega\nfebre. Ao exame: colpite difusa. Identifique o exame que pode ser realizado, no momento da\nconsulta, para confirmação diagnóstica:","options":{"A":"Exame a fresco com hidróxido de potássio a 10%.","B":"PCR.","C":"Captura híbrida.","D":"Cultura de secreção vaginal."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-341070","number":"341070","sourceNumber":"341070","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 20 anos de idade, em uso de adesivo como método contraceptivo refere prurido\nvaginal intenso, há três dias, associado a corrimento grumoso e esverdeado, sem odor fétido. Nega\nfebre. Ao exame: colpite difusa. Identifique o tratamento indicado para sua principal suspeita\ndiagnóstica:","options":{"A":"Metronidazol 2gramas, via oral, dose única.","B":"Fluconazol, 150mg, via oral, dose única.","C":"Azitromicina 1grama, via oral, dose única.","D":"Doxiciclina, 100mg, via oral, de 12 em 12 horas por 7 dias."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343211","number":"343211","sourceNumber":"343211","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação à Doença Inflamatória Pélvica Aguda, assinale a alternativa incorreta.","options":{"A":"O uso de preservativo pode prevenir a transmissão.","B":"O espermatozoide pode funcionar como carreador do patógeno.","C":"Atualmente se sabe que o agente etiológico mais comum é o micoplasma.","D":"As duchas vaginais podem facilitar a ascensão de microrganismos causadores de DIPA."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-307051","number":"307051","sourceNumber":"307051","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 32 anos de idade, vem à Urgência com dor em baixo ventre há 4 dias. Há 6\nhoras aferiu a temperatura e estava 38,2ºC.\nPrimigesta com parto normal há 3 anos. Namorado fixo\nhá um mês. Nega cirurgias prévias ou comorbidades. Nega disúria, vômitos ou diarreia. Como\nmétodo contraceptivo faz uso de pílula. Nega uso de condom. Ao exame físico: corada, hidratada,\nanictérica e acianótica. PA: 100x60mmHg. FC: 108bpm. FR:16ipm. Ausculta torárica e abdominal\nsem alterações. Dor à palpação em hipogástrio, porém sem piora à descompressão brusca. Exame\nespecular: secreção vaginal de odor fétido, amarelada. Toque vaginal: dor à mobilização do colo e\npalpação de anexos. Diante desse caso clínico, indique: O estágio da doença e a proposição de\ntratamento, de acordo com a Classificação de Monif:","options":{"A":"Estágio 1, tratamento ambulatorial.","B":"Estágio 2, tratamento ambulatorial.","C":"Estágio 3, tratamento hospitalar.","D":"Estágio 4, tratamento hospitalar."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-307052","number":"307052","sourceNumber":"307052","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 32 anos de idade, vem à Urgência com dor em baixo ventre há 4 dias. Há 6\nhoras aferiu a temperatura e estava 38,2ºC.\nPrimigesta com parto normal há 3 anos. Namorado fixo\nhá um mês. Nega cirurgias prévias ou comorbidades. Nega disúria, vômitos ou diarreia. Como\nmétodo contraceptivo faz uso de pílula. Nega uso de condom. Ao exame físico: corada, hidratada,\nanictérica e acianótica. PA: 100x60mmHg. FC: 108bpm. FR:16ipm. Ausculta torárica e abdominal\nsem alterações. Dor à palpação em hipogástrio, porém sem piora à descompressão brusca. Exame\nespecular: secreção vaginal de odor fétido, amarelada. Toque vaginal: dor à mobilização do colo e\npalpação de anexos. Diante desse caso clínico, indique: Os critérios maiores da Doença\nInflamatória Pélvica, presentes no caso:","options":{"A":"Taquicardia, febre e secreção vaginal.","B":"Febre, secreção vaginal e dor à mobilização do colo.","C":"Dor à mobilização do colo e anexos, além de dor à palpação de abdome.","D":"Dor à mobilização do colo e anexos, além de febre."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-307053","number":"307053","sourceNumber":"307053","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 32 anos de idade, vem à Urgência com dor em baixo ventre há 4 dias. Há 6\nhoras aferiu a temperatura e estava 38,2ºC.\nPrimigesta com parto normal há 3 anos. Namorado fixo\nhá um mês. Nega cirurgias prévias ou comorbidades. Nega disúria, vômitos ou diarreia. Como\nmétodo contraceptivo faz uso de pílula. Nega uso de condom. Ao exame físico: corada, hidratada,\nanictérica e acianótica. PA: 100x60mmHg. FC: 108bpm. FR:16ipm. Ausculta torárica e abdominal\nsem alterações. Dor à palpação em hipogástrio, porém sem piora à descompressão brusca. Exame\nespecular: secreção vaginal de odor fétido, amarelada. Toque vaginal: dor à mobilização do colo e\npalpação de anexos. Diante desse caso clínico, indique: Os critérios menores da Doença\nInflamatória Pélvica, observados no caso clínico:","options":{"A":"Febre e secreção vaginal.","B":"Febre e dor à mobilização do colo.","C":"Dor à mobilização do colo e anexos.","D":"Secreção vaginal e dor à palpação abdominal."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-313456","number":"313456","sourceNumber":"313456","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente da unidade de saúde retorna com resultado de exame citopatológico que\nevidenciou coilocitose. Esse laudo sugere:","options":{"A":"Infecção por HPV.","B":"Displasia severa.","C":"Reação decidual do colo.","D":"Hiperplasia do epitélio glandular do colo."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-315193","number":"315193","sourceNumber":"315193","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Sobre a tricomoníase, assinale a alternativa CORRETA.","options":{"A":"Trata-se de uma IST (infecção sexualmente transmissível) viral associada como fonte de\nmorbidade reprodutiva e facilitadora da aquisição do HIV.","B":"A sintomatologia pode envolver quadro de ardência vaginal, presença de secreção amarela ou\nesverdeada de odor fétido.","C":"Colo com aspecto em framboesa ou pele de tigre não está associada a esta patologia.","D":"Diante do diagnóstico e tratamento da mulher com tricomoníase, não se faz necessário o\ntratamento do parceiro sexual.","E":"O tratamento pode ser feito com metronidazol, não sendo o secnidazol uma segunda opção."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-307060","number":"307060","sourceNumber":"307060","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Jovem, primípara, acaba de evoluir com parto normal e recebe notícia, durante\ninternação, que está com sorologia positiva\npara HIV, motivo pelo qual não poderá amamentar. A\npaciente ainda não começou a produzir colostro. Diante desse caso, indique a conduta inicial a ser\nadotada:","options":{"A":"Realizar a supressão da lactação com medicamento.","B":"Realizar a inibição da lactação com medicamento.","C":"Afastar o recém-nascido da mãe para que não ocorra a amamentação, e realizar conduta\nexpectante.","D":"Realizar enfaixamento mamário e conduta expectante."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-307078","number":"307078","sourceNumber":"307078","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Bebê, sexo masculino, é levado, duas semanas após o parto, na maternidade de\nnascimento, com febre e eritema\nmaculopapular em tronco, palmas e plantas de pés, com secreção\nnasal serosanguinolenta e hipocromia de mucosas. A mãe não fez pré-natal completo. Um exame\nda mãe revela VDRL positivo com título de 1:32. Segundo as normas do Ministério da Saúde,\nespecifique em que consultas seria o melhor momento para a mãe dessa criança ter realizado o\nteste para o diagnóstico de sífilis:","options":{"A":"Na primeira consulta e, se negativo, três meses após.","B":"Na primeira consulta e, se negativo, no início do terceiro trimestre.","C":"No fim do primeiro trimestre e, se negativo, após três meses.","D":"No início do terceiro trimestre e no período periparto."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-307079","number":"307079","sourceNumber":"307079","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Bebê, sexo masculino, é levado, duas semanas após o parto, na maternidade de\nnascimento, com febre e eritema\nmaculopapular em tronco, palmas e plantas de pés, com secreção\nnasal serosanguinolenta e hipocromia de mucosas. A mãe não fez pré-natal completo. Um exame\nda mãe revela VDRL positivo com título de 1:32. O principal motivo para o tratamento de uma\ngestante, com sorologia para sífilis, com penicilina benzatina, é que","options":{"A":"sendo uma penicilina de depósito, pode ser feita com intervalo maior de tempo.","B":"se associa a menor risco de reação pós-tratamento por liberação de antígeno.","C":"atravessa bem a barreira placentária e a barreira hematocefálica do feto.","D":"impede a sífilis congênita, mesmo usada no terceiro trimestre da gestação."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-279027","number":"279027","sourceNumber":"279027","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uretrite não gonocócica é a uretrite sintomática cuja bacterioscopia pela coloração de\nGram, cultura e detecção de gonococo por biologia molecular são negativas para o gonococo.\n\nIndique o item errado.","options":{"A":"A infecção por clamídia no homem é responsável por aproximadamente 50% dos casos de\nuretrite não gonocócica.","B":"A transmissão ocorre pelo contato sexual (risco de 20% por ato), sendo o período de incubação,\nno homem, de 14 a 21 dias.","C":"Estima-se que dois terços das parceiras estáveis de homens com uretrite não gonocócica\nhospedem a C. trachomatis na endocérvice.","D":"Não podem reinfectar seu parceiro sexual e desenvolver quadro de DIP mesmo se\npermanecerem sem tratamento."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-276002","number":"276002","sourceNumber":"276002","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Assinale a resposta INCORRETA sobre as infecções citadas.","options":{"A":"Clamídia, micoplasma e ureaplasma são patógenos ligados à ocorrência de doença inflamatória\npélvica.","B":"Tricomoníase é responsável pela ocorrência de corrimento amarelo-esverdeado, irritação e\nprurido e exige tratamento do parceiro.","C":"Casos de candidíase recorrente demandam tratamento prolongado e investigação da imunidade\nda paciente, tal como quadro de diabetes.","D":"Vaginose bacteriana possui piora do odor com a menstruação devido à alcalinização do meio\nvaginal neste período.","E":"Na vaginite por cândida encontramos clue cells na citologia ao ser corada por Gram."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-278122","number":"278122","sourceNumber":"278122","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em uma cirurgia videolaparoscópica, o encontro de lesões hepáticas tipo ?corda de\nviolino? leva a pensar na síndrome de","options":{"A":"Budd-Chiari.","B":"Fitz-Hugh-Curtis.","C":"Ashermann.","D":"Sthein-Leventha.l"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-278656","number":"278656","sourceNumber":"278656","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Após relação sexual desprotegida com uma mulher, o homem passa a apresentar\nsecreção uretral e disúria. A causa mais\nprovável é","options":{"A":"Candidíase.","B":"Tricomoníase.","C":"Clamídia.","D":"Sífilis Primária."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-279078","number":"279078","sourceNumber":"279078","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O tratamento mais adequado para uretrite por Clamídia fora da gestação é","options":{"A":"Ampicilina via oral.","B":"Ceftriaxona via endovenosa.","C":"Metronidazol via oral.","D":"Azitromicina via oral."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-252915","number":"252915","sourceNumber":"252915","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 40 anos de idade, foi atendida na Emergência por apresentar dor pélvica há um\ndia. Primípara com parto normal há 4 anos. Refere ciclos menstruais regulares, última menstruação\nhá oito dias. Método contraceptivo: coito interrompido. Também refere aparecimento de secreção\namarelada por via vaginal, há três dias. Sobre os elementos para diagnóstico do caso, é correto o\nque se afirma em:","options":{"A":"Pode ser um caso de gestação ectópica e a conduta inicial para investigação será culdocentese.","B":"Caso evolua com sinais de peritonite deve ser prescrito antibioticoterapia oral com reavaliação\nem, no máximo, 48 horas.","C":"Se houver dor à palpação abdominal e à mobilização do colo uterino e dos anexos, está\nestabelecido o diagnóstico de Doença Inflamatória Pélvica (DIP) por 3 critérios maiores.","D":"A secreção amarelada por via vaginal é um critério maior de Doença Inflamatória Pélvica."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-252916","number":"252916","sourceNumber":"252916","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 40 anos de idade, foi atendida na Emergência por apresentar dor pélvica há um\ndia. Primípara com parto normal há 4 anos. Refere ciclos menstruais regulares, última menstruação\nhá oito dias. Método contraceptivo: coito interrompido. Também refere aparecimento de secreção\namarelada por via vaginal, há três dias. Ao exame físico, essa paciente apresenta bom estado\ngeral, T: 37,3ºC, dor à palpação abdominal, descompressão brusca abdominal negativa. Ao exame\nespecular: Secreção amarelada e de odor fétido, extravasando pelo orifício externo do colo. Ao\ntoque: dor à mobilização do colo uterino e dor à palpação de anexos. Realizou ultrassonografia\ntransvaginal sem alterações. No momento, a conduta terapêutica mais adequada é:","options":{"A":"Proceder a internação e fazer uso de antibioticoterapia venosa, considerando que a paciente\npossui o diagnóstico de Doença Inflamatória Pélvica.","B":"Adotar como tratamento de escolha ceftriaxone 500mg, intramuscular, dose única + doxicilina\n100mg, via oral, a cada 12 horas por 14\ndias + metronidazol, 500mg, via oral, a cada 12 horas por\n14 dias, considerando que a paciente possui o diagnóstico de Doença Inflamatória Pélvica.","C":"Fazer uso de metronidazol 2g, via oral, dose única, pois trata-se, provavelmente, de uma\nvaginite por trichomonas vaginalis.","D":"Usar azitromicina 1g, via oral, dose única + metronidazol 2g, via oral, dose única, considerando\nque a paciente possui o diagnóstico de\ncervicite por clamídia."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-252917","number":"252917","sourceNumber":"252917","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 40 anos de idade, foi atendida na Emergência por apresentar dor pélvica há um\ndia. Primípara com parto normal há 4 anos. Refere ciclos menstruais regulares, última menstruação\nhá oito dias. Método contraceptivo: coito interrompido. Também refere aparecimento de secreção\namarelada por via vaginal, há três dias. O quadro clínico apresentado pela paciente pode evoluir\ncom as seguintes sequelas:","options":{"A":"Câncer de endométrio, hidrossalpinge, infertilidade.","B":"Dor pélvica crônica, infertilidade, obstrução tubária.","C":"Hidrossalpinge, hiperplasia endometrial, cisto ovariano.","D":"Obstrução tubária, dismenorreia, insuficiência ovariana precoce."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-249275","number":"249275","sourceNumber":"249275","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Os aspectos clínicos das úlceras genitais são bastante variados e têm baixa relação de\nsensibilidade e especificidade com o agente etiológico, mesmo nos casos considerados clássicos.\nSendo inadequado que:","options":{"A":"o diagnóstico com base na impressão clínica apresentou valores preditivos positivos muito\nbaixos ? 30,9% para sífilis e 32,7% para cancroide ? por ocasião do estudo de validação da\nabordagem sindrômica no Brasil.","B":"a úlcera genital está frequentemente associada às IST na população sexualmente ativa.","C":"ocorre associação em particular nos adolescentes e adultos jovens, a queixa de úlcera genital\nnão é exclusividade das ISTs.","D":"em pelo menos 45% dos pacientes com úlcera genital não há confirmação laboratorial do agente\netiológico."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-201768","number":"201768","sourceNumber":"201768","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 27 anos queixa-se de um odor de peixe e de secreção vaginal. O exame de\nespéculo revela uma vagina eritematosa e bolhas na cérvice. Qual o diagnóstico mais provável?","options":{"A":"Vaginite por cândida.","B":"Vaginite por trichomonas.","C":"Vaginose bacteriana.","D":"Papiloma vírus humano.","E":"Herpes vírus simples."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-219855","number":"219855","sourceNumber":"219855","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 28 anos, G0P0, relações sexuais com o mesmo parceiro há seis meses e\nusando DIU T de cobre há dois anos, procura\nUnidade Básica de Saúde referindo aparecimento de\nverrugas na genitália externa há 20 dias. Ao exame ginecológico foram evidenciadas verrugas\nsugestivas de infecção por HPV entre a fúrcula vaginal e região perianal. Qual a PRINCIPAL\nCONDUTA nesse caso?","options":{"A":"Encaminhar o parceiro para exame da região genital.","B":"Esclarecer a paciente que essas verrugas são poucas contagiosas.","C":"Indicar a remoção das verrugas genitais.","D":"Prescrever a vacina de HPV bivalente."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-219859","number":"219859","sourceNumber":"219859","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 31 anos foi vítima de violência sexual há cerca de 96 horas e houve\ncontato da vagina com esperma do agressor e presença de lesão no ombro decorrente de\n\"mordida\" também causada pelo agressor. Deve ser feita a profilaxia de quais doenças?","options":{"A":"Clamídia, tricomoníase, tétano, HIV, hepatite C.","B":"Gonorreia, clamídia, tricomoníase, HIV, hepatite B.","C":"Gonorreia, clamídia, tricomoníase, HIV, hepatite B.","D":"Gonorreia, tricomoníase, tétano, clamídia, hepatite B"},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-219867","number":"219867","sourceNumber":"219867","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante de 32 anos, G2P1A0, procura o pronto atendimento da maternidade com\nhistória de há duas semana apresentar\nurgência miccional, disúria, dor suprapúbica e urina com\nodor desagradável. Apresenta prescrição da Unidade Básica de Saúde de nitrofurantoína 100 mg,\nde 6/6 horas por 7 dias quando do início dos sintomas. Refere ter feito uso regular da medicação\nprescrita sem alívio dos sintomas. Sem dados relevantes ao exame clínico. Realizou exame de\nurina rotina e urocultura há 2 dias com os seguintes achados: - Sedimento urinário com 15\nleucócitos por campo, raras células epiteliais e 6 hemácias por campo, nitrito e proteínas\nnegativos;\n\n- Urocultura: ausência de crescimento bacteriano. Diante do quadro clínico apresentado assinale a\nalternativa com o diagnóstico MAIS PROVÁVEL:","options":{"A":"Cistite aguda.","B":"Nefrolitíase.","C":"Pielonefrite.","D":"Uretrite por gonococo ou clamídia."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-219884","number":"219884","sourceNumber":"219884","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A sífilis é um grave problema de saúde pública em nosso país. Quando ocorre na\ngestação pode, na ausência de tratamento e\nseguimento adequado, determinar a ocorrência da\nsífilis congênita. Você está atendendo uma primigesta com 12 semanas de gravidez, sem história\nde doenças prévias na primeira consulta com 11 semanas de gravidez, apresentou um teste rápido\npara sífilis positivo, recebeu 2,4 milhões de penicilina benzatina no mesmo dia e foi solicitado o\nexame de VDRL. O resultado do VDRL foi positivo 1:16. Com base nesses dados, assinale a\nalternativa CORRETA para o tratamento e seguimento da gestante:","options":{"A":"Administrar mais uma dose de 2,4 milhões de penicilina benzatina hoje e prescrever mais uma\ndose de 2,4 milhões de penicilina benzatina\nem sete dias e acompanhar com VDRL mensal.","B":"Administrar mais uma dose de 2,4 milhões de penicilina benzatina hoje e prescrever mais uma\ndose de 2,4 milhões de penicilina benzatina\nem sete dias e acompanhar com VDRL trimestral.","C":"Administrar mais uma dose de 2,4 milhões de penicilina benzatina hoje e acompanhar com\nVDRL mensal.","D":"Administrar mais uma dose de 2,4 milhões de penicilina benzatina e acompanhar com VDRL\ntrimestral."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-216293","number":"216293","sourceNumber":"216293","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com queixa de corrimento vaginal é diagnosticada como sendo candidíase.\nEm relação ao agente etiológico, assinale a\nalternativa VERDADEIRA.","options":{"A":"É considerada uma DST.","B":"O tratamento com metronidazol local é eficaz.","C":"Fluconazol via oral é uma opção de tratamento.","D":"Sempre deve ser tratado o parceiro sexual."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-212154","number":"212154","sourceNumber":"212154","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A vaginose bacteriana é uma entidade polimicrobiana causada: I. pela diminuição\nacentuada dos Lactobacillus sp e aumento nas\nconcentrações das bactérias anaeróbias,\nprincipalmente Gardnerella vaginalis, Mobilluncus sp e micoplasmas; II. pelo aumento acentuado\ndos Lactobacillus sp e aumento nas concentrações das bactérias anaeróbias, principalmente\nGardnerella vaginalis, Mobilluncus sp e micoplasmas; III. pelo aumento acentuado dos Lactobacillus\nsp e diminuição nas concentrações das bactérias anaeróbias, principalmente Gardnerella vaginalis,\nMobilluncus sp e micoplasmas; IV. pela diminuição acentuada dos Lactobacillus sp e aumento nas\nconcentrações das bactérias aeróbias, principalmente Gardnerella vaginalis, Mobilluncus sp e\nmicoplasmas. Dos itens, verifica-se que está(ão) correto(s) apenas","options":{"A":"II, III e IV.","B":"III e IV.","C":"I e IV.","D":"I e II.","E":"I."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215238","number":"215238","sourceNumber":"215238","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 18 anos, múltiplos parceiros sexuais, com queixa de corrimento vaginal\namarelado há 2 meses. Iniciou há 7 dias quadro de poliartrite e tenossinovite. O patógeno mais\nprovavelmente envolvido é:","options":{"A":"Neisseria gonorrhoeae.","B":"E. coli.","C":"Chlamydia trachomatis.","D":"Haemophilus ducreyi."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-216264","number":"216264","sourceNumber":"216264","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com queixa de corrimento vaginal, colhida a secreção vaginal que, colocada\nem lâmina e adicionado hidróxido de potássio a\n10%, evidencia odor bastante desagradável. O\nmais provável diagnóstico é","options":{"A":"vaginose bacteriana.","B":"candidíase.","C":"tricomoníase.","D":"pseudomonas."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-216292","number":"216292","sourceNumber":"216292","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher é encaminhada da Unidade Básica para atendimento ginecológico com\ndiagnóstico de Sífilis latente. A lesão encontrada nesse caso é","options":{"A":"condiloma acuminado.","B":"condiloma plano.","C":"nenhuma lesão.","D":"cancro genital duro."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-212226","number":"212226","sourceNumber":"212226","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, procura atendimento médico devido estar\napresentando corrimento vaginal há cerca de 1\nsemana, além de prurido intenso na vagina.\nDurante o exame físico, percebe-se um corrimento amarelado e bolhoso de odor desagradável.\nDiante do exposto, dados os itens que menciona o diagnóstico mais provável e o principal teste\npara confirmação dessa hipótese diagnóstica, I. Tricomoníase / Exame microscópico a fresco do\nconteúdo vaginal. II. Gonorreia / Sorologia. III. Vaginose bacteriana / PCR. IV. Candidíase vaginal\n/\nCultura de secreção vaginal. verifica-se que está(ão) correto(s) apenas","options":{"A":"I.","B":"I e III.","C":"I e IV.","D":"II e III.","E":"II e IV."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-212216","number":"212216","sourceNumber":"212216","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Relacione a 1ª coluna de acordo com a 2ª; Assinale a alternativa que apresenta as\ncorretas correlações.","options":{"A":"1-A / 2-D / 3-C / 4-B","B":"1-B / 2-C / 3-A / 4-D","C":"1-B / 2-C / 3-D / 4-A","D":"1-C / 2-B / 3-D / 4-A","E":"1-C / 2-D / 3-B / 4-A"},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/212216.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215236","number":"215236","sourceNumber":"215236","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em casos de pessoas em situação de violência sexual não imunizadas ou com\nesquema vacinal incompleto para hepatite B, o\nMS recomenda vacinação para HBV e\nimunoglobulina hiperimune para hepatite B (IGHAHB). Não se deverá aplicar a imunoprofilaxia para\nhepatite B em diversas situações listadas abaixo. Demonstre a alternativa com conceito ERRADO:","options":{"A":"Casos de violência sexual em que a vítima apresente exposição crônica e repetida.","B":"Pessoas cujo agressor seja sabidamente vacinado.","C":"Quando ocorrer uso de preservativo, masculino ou feminino, durante o crime sexual.","D":"A imunização para a hepatite B e o uso de IGHAHB também estão indicados na gestação,\nsomente no primeiro bimestre."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215259","number":"215259","sourceNumber":"215259","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"No atendimento à mulher, que corresponde à maioria dos casos de violência sexual,\ndeve-se colher material de conteúdo vaginal para diagnóstico de tricomoníase, gonorreia e\nclamídia. A prevalência de Infecções Sexualmente Transmissíveis IST em situações de violência\nsexual é elevada, e o risco de infecção depende de diversas variáveis, como as listadas abaixo.\nIndique a alternativa com conceito errado:","options":{"A":"Tipo de violência sofrida (vaginal, anal ou oral).","B":"Número de agressores.","C":"Tempo de exposição (única, múltipla ou crônica).","D":"Ocorrência de traumatismos genitais, a idade, a susceptibilidade da mulher e a condição himenal\nnão influenciam na situação."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215267","number":"215267","sourceNumber":"215267","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A maioria das infecções do HPV são assintomáticas ou não aparentes, sendo\nINCORRETO a respeito de sua transmissão que:","options":{"A":"Transmissão do HPV ocorre, raramente por via sexual.","B":"A transmissão vertical do HPV é corroborada pela ocorrência de papilomatose recorrente de\nlaringe juvenil, em crianças com menos de dois anos de idade.","C":"Ocorrem relatos de casos de RN com condiloma genital ao nascimento.","D":"A transmissão por fômites é rara."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215277","number":"215277","sourceNumber":"215277","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em âmbito nacional, destaca-se a Lei no 12.845/2013, que dispõe sobre o atendimento\nobrigatório e integral de pessoas em situação de violência sexual, e ainda as Leis de Notificação\nCompulsória no caso de violência contra mulheres, crianças, adolescentes e pessoas idosas,\natendidas em serviços de saúde públicas ou privadas (Lei n° 10.778/2003, Lei no 8.069/1990, Lei\nn° 10.741/2003), a Lei Maria da Penha (Lei n° 11.340/2006), entre outros. Somente é CORRETO o\ntexto:","options":{"A":"O estupro é definido como o ato de constranger mulheres, mediante violência ou grave ameaça,\na ter conjunção carnal ou a praticar ou\npermitir que com ele se pratique outro ato libidinoso, sendo\ncrime previsto no artigo 213 do Código Penal Brasileiro.","B":"O estupro é definido como o ato de constranger alguém, mediante violência ou grave ameaça, a\nter conjunção carnal ou a praticar ou permitir que com ele se pratique outro ato libidinoso, sendo\ncrime previsto no artigo 213 do Código Penal Brasileiro.","C":"O estupro é definido como o ato de constranger alguém, mediante violência apenas, a ter\nconjunção carnal ou a praticar ou permitir que\ncom ele se pratique outro ato libidinoso, sendo crime\nprevisto no artigo 213 do Código Penal Brasileiro.","D":"O estupro é definido como o ato de constranger alguém, mediante violência ou grave ameaça, a\nter conjunção carnal apenas, sendo crime previsto no artigo 213 do Código Penal Brasileiro."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215281","number":"215281","sourceNumber":"215281","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A violência sexual, independentemente do sexo e da idade, deve ser considerada uma\nprioridade na assistência, devido aos danos psicossociais, à gravidez indesejada e ao risco de\naquisição de HIV, IST e hepatites virais. Não sendo correto o conceito de que:","options":{"A":"A transmissão de determinadas Infecções Sexualmente Transmissíveis IST, como sífilis e HPV,\nnão pode ocorrer mesmo com o uso correto e regular de preservativos.","B":"A atividade sexual sem o uso do preservativo (ou no caso de falhas no uso) pode gerar\nansiedade e risco de transmissão de HIV, IST e hepatites virais.","C":"Receber vacinação e imunização passiva para HBV.","D":"Colher imediatamente material para avaliação do status sorológico de sífilis, HIV, HBV e HCV,\npara seguimento e conduta específica."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215292","number":"215292","sourceNumber":"215292","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O curso clínico da sífilis pode ser alterado pela coinfecção com HIV, com a ocorrência\nde manifestações atípicas ou mais agressivas. No\nentanto, algumas características da coinfecção\nsífilis/HIV devem ser destacadas, como as abaixo, demonstre a alternativa com conceito errado:","options":{"A":"Desenvolvimento de cancros múltiplos e rasos, apresentando resolução mais rápida que em\npessoas não infectadas pelo HIV.","B":"Maior frequência de sobreposição de estágios e concomitância de lesões primárias e\nsecundárias no momento do diagnóstico.","C":"Maior frequência de secundarismo, com lesões cutâneas atípicas e exuberância de sintomas e\nsintomas.","D":"Predisposição para acometimento oftálmico e neurológico, com progressão mais rápida da sífilis\nprecoce à neurossífilis."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215291","number":"215291","sourceNumber":"215291","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Quando estudamos o tratamento da sífilis adquirida e sífilis na gestação, a penicilina é\no medicamento de escolha para o tratamento da\nsífilis. Não está adequado que:","options":{"A":"Níveis de penicilina superiores a 0,018 mg por litro são considerados suficientes.","B":"Níveis de penicilina devem ser mantidos por pelo menos três a cinco dias na sífilis recente.","C":"Níveis de penicilina por duração mais longa na sífilis tardia que na recente.","D":"Na gestação, tratamentos não penicilínicos são inadequados e só devem ser considerados como\nopção nas contraindicações absolutas ao uso\nda penicilina."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215295","number":"215295","sourceNumber":"215295","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Para gestantes com alergia confirmada à penicilina não há garantia de que outros\nmedicamentos consigam tratar a gestante e o feto, está fora de contexto o seguinte item:","options":{"A":"Impõe-se a dessensibilização e o tratamento com penicilina benzatina.","B":"Na impossibilidade de realizar a dessensibilização durante a gestação, a gestante deverá ser\ntratada com ceftriaxona.","C":"Para fins de definição de caso e abordagem terapêutica da sífilis congênita um tratamento\nalternativo, considera-se tratamento adequado da mãe, e o RN deverá ser avaliado clínica e\nlaboratorialmente.","D":"As situações de tratamento inadequado da gestante com sífilis, para fins de notificação da\nsífilis\ncongênita, encontram-se descritas em protocolo."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-180128","number":"180128","sourceNumber":"180128","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Assinale a afirmativa correta sobre a Sífilis","options":{"A":"O cancro duro caracteriza-se por ser uma lesão\ngeralmente única e dolorosa.","B":"Erupção cutânea maculosa ou papulosa ocorre na Sífilis primária.","C":"Lesões palmoplantares com descamação em\ncolarinho são comuns na Sífilis secundária.","D":"Na Sifilis primária ocorre adenopatia regional\nfistulizada.","E":"As lesões cutâneas da Sífilis secundária caracterizase por serem pruriginosas."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-187747","number":"187747","sourceNumber":"187747","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com 18 anos de idade, foi submetida a videolaparoscopia devido a um quadro\nde dor abdominal aguda, febre e corrimento\nvaginal purulento. Foi detectado um quadro típico de\nDoença inflamatória Pélvica. A cultura da secreção purulenta colhida no procedimento MAIS\nPROVAVELMENTE revelará:","options":{"A":"Chlamydia trachomatis","B":"Múltiplos microrganismos","C":"Neisseria gonorrhoeae","D":"Treponema pallidum"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-180146","number":"180146","sourceNumber":"180146","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. A etiologia e o\ntratamento recomendado para cancro mole são...","options":{"A":"Neisseria gonorrhoeae. Ceftriaxona 500 mg intramuscular dose única.","B":"Mycoplasma hominis. Azitromicina 1 g via oral dose única.","C":"Ureaplasma urealyticum. Ceftriaxona 500 mg intramuscular dose única.","D":"Haemophilus ducrey. Azitromicina 1 g via oral dose única.","E":"Chlamydia trachomatis. Tianfenicol 1,5 g via oral por 14 dias."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-180108","number":"180108","sourceNumber":"180108","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"No atendimento de paciente vítima de violência sexual, a melhor opção de\ncontracepção de emergência é o uso de:","options":{"A":"Levonorgestrel 0,75 mg, em 2 doses com intervalo de 12 horas","B":"Contraceptivos contendo etinilestradiol, na dose de 20 mcg/dia, por 21 dias","C":"Contraceptivos contendo etinilestradiol, na dose de 30 mcg associados ao gestodene","D":"Acetato de medroxiprogesterona 10 mg/dia, por 10 dias consecutivos","E":"Todas as opções apresentadas acima"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-180118","number":"180118","sourceNumber":"180118","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Dos microorganismos abaixo, NÃO faz parte da microflora vaginal normal:","options":{"A":"Micoplasma hominis","B":"Chlamydia trachomatis.","C":"Candida albicans.","D":"Gardnerella vaginalis.","E":"Nenhum dos citados."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182739","number":"182739","sourceNumber":"182739","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Na prevenção de recorrências de Candidíase Vulvovaginal medidas suplementares\ndevem ser tomadas. Das alternativas\napresentadas a seguir, assinale aquela que não deve ser\nutilizada:","options":{"A":"Evitar as depilações totais, mantendo uma quantidade satisfatória de pelos pubianos.","B":"Evitar roupas íntimas com tecidos sintéticos tipo lycra.","C":"Realizar periodicamente duchas vaginais com a finalidade de prevenir recidivas.","D":"Restringir o uso de antibióticos que podem destruir a flora vaginal natural."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183572","number":"183572","sourceNumber":"183572","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Adolescente de 16 anos é vítima de estupro. Após 40 dias comparece ao consultório de\nginecologista acompanhada da mãe, referindo gravidez. A adolescente quer prosseguir com a\ngestação, mas a mãe deseja a interrupção da mesma. Nesse caso, a conduta apropriada é","options":{"A":"indicar o aborto terapêutico, pois a mãe tem a palavra final por ser responsável pela\nadolescente, bastando somente a palavra da mãe como prova.","B":"indicar o aborto terapêutico, pois a mãe tem a palavra final por ser responsável pela\nadolescente, desde que haja Boletim de Ocorrência elaborado e solicitação judicial.","C":"indicar o aborto terapêutico, pois a mãe tem a palavra final por ser responsável pela\nadolescente, necessitando, apenas, do Boletim de Ocorrência.","D":"não indicar o aborto terapêutico, pois apesar de ser menor de 18 anos, a adolescente tem que\nter sua opção respeitada."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182777","number":"182777","sourceNumber":"182777","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Na cirurgia de Bartholinectomia a complicação mais frequente é o hematoma, uma vez\nque a glândula tem íntima relação com o:","options":{"A":"Músculo Bulbocavernoso","B":"Músculo Isquiocavernoso","C":"Músculo Transverso Superficial do Períneo","D":"Músculo Elevador do Ânus"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183068","number":"183068","sourceNumber":"183068","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com corrimento vaginal comparece a laboratório de análises clínicas onde é\ncolhida secreção vaginal que, colocada em lamina e adicionado hidróxido de potássio a 10%,\nevidencia presença de hifas. Sobre isso, o provável diagnóstico é:","options":{"A":"Tricomoniase","B":"Vaginose Bacteriana","C":"Candidiase","D":"Clamídia"},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183550","number":"183550","sourceNumber":"183550","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com corrimento com odor desagradável, sem prurido. O teste das aminas\nresultou negativo. Ao exame especular foi observada a ?Cérvice em Morango?. O mais provável\ndiagnóstico e tratamento correspondente são:","options":{"A":"vaginose bacteriana / metronidazol.","B":"tricomoníase / metronidazol.","C":"vaginose bacteriana / miconazol.","D":"tricomoníase / miconazol."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183087","number":"183087","sourceNumber":"183087","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Indique a opção INCORRETA em relação ao gonococo.","options":{"A":"Pode causar Bartholinite.","B":"É patógeno intracelular.","C":"Causa, geralmente, infecção genital baixa.","D":"Não guarda relação com prenhez ectópica."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182775","number":"182775","sourceNumber":"182775","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"As uretrites são Infecções Sexualmente Transmissíveis - IST caracterizadas por\ninflamação da uretra acompanhada de\ncorrimento, não sendo adequado ao seu contexto o seguinte\nitem listado abaixo:","options":{"A":"Os agentes microbianos das uretrites podem ser transmitidos por relação sexual vaginal, anal e\noral.","B":"O corrimento uretral pode ter aspecto que varia de mucoide a purulento, com volume variável,\nestando associado a dor\nuretral(independentemente da micção), disúria, estrangúria (micção lenta\ne dolorosa), prurido uretral e eritema de meato uretral.","C":"Entre os fatores associados às uretrites, foram encontrados: idade jovem, baixo nível\nsocioeconômico, múltiplas parcerias ou nova parceria sexual, histórico de IST e uso regular de\npreservativos.","D":"Os agentes etiológicos mais importantes do corrimento uretral são a N. gonorrhoeae e a C.\ntrachomatis. Outros agentes, como T. vaginalis, U. urealyticum, enterobactérias (nas relações anais\ninsertivas), M. genitalium, vírus do herpes simples (HSV, do inglês Herpes Simplex Virus),\nadenovírus e Candida spp. são menos frequentes."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-182788","number":"182788","sourceNumber":"182788","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Uretrite Gonocócica é um processo infeccioso e inflamatório da mucosa uretral,\ncausado pela N. gonorrhoeae (diplococo\nGram-negativo intracelular). Sobre isso, assinale o item\nque se mostra INCORRETO:","options":{"A":"O risco de transmissão de um parceiro infectado a outro é de 90% por ato sexual.","B":"Os sinais e sintomas são determinados pelos locais primários de infecção (membranas mucosas\nda uretra, endocérvice, reto, faringe e\nconjuntiva).","C":"A gonorreia é frequentemente assintomática em mulheres e também quando ocorre na faringe e\nno reto.","D":"A infecção uretral no homem pode ser assintomática em menos de 10% dos casos. Nos casos\nsintomáticos, há presença de corrimento em mais de 80% e/ou disúria (> 50%)."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-181416","number":"181416","sourceNumber":"181416","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Carla, 11 anos, há cerca de 5 dias começou a apresentar leucorreia inodora, leitosa e\nnão pruriginosa. Realizou-se a coleta do\nmaterial por swab vaginal e, à microscopia, observaram-se\ncélulas epiteliais, bacilos de Dorderlein, sem leucócitos. Qual o diagnóstico mais provável e a\nmelhor conduta a ser tomada?","options":{"A":"Trata-se de vulvovaginite por Candida sp, fazendo-se uso de fluconazol oral.","B":"Trata-se de vulvovaginite por Enterobius vermiculares, tratando-se com vermífugo\n(membendazol).","C":"Trata-se de leucorreia fisiológica, com tratamento expectante e orientação quanto à higiene com\nágua e sabão neutro.","D":"Trata-se de vulvovaginite por Gardnerella vaginalis,\nprescrevendo-se metronidazol, na dose 15mg/kg/dia, por 07 dias.","E":"Trata-se de vulvovaginite inespecífica (vestibulite),\n\norientando-se a realização de banhos de assento com água morna por 10 a 15 minutos, 2 vezes\npor dia, por 7 a 10 dias, bem como usar sabão\nneutro para banho e higiene das roupas íntimas,\ncalcinhas de algodão, roupas arejadas e manter a vulva sempre limpa e seca."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161335","number":"161335","sourceNumber":"161335","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação à Sífilis, assinale a alternativa CORRETA.","options":{"A":"Uma dificuldade para confirmação diagnóstica de certeza de sífilis é o fato das espiroquetas\nserem finas demais para reter a coloração pelo\nGram.","B":"As gestantes comprovadamente alérgicas à penicilina devem ser tratadas preferencialmente\ncom Eritromicina.","C":"Para controle de cura são utilizados os testes seriados de FTA-ABS a cada 3 meses, com queda\nde 4 vezes os títulos confirmando o\nsucesso da terapia.","D":"O VDRL, apesar de excelente método de rastreamento, não tem mais valor prático com o\nadvento dos testes rápidos treponêmicos."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161338","number":"161338","sourceNumber":"161338","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente procura o atendimento ginecológico de emergência à noite com queixa de\ntumoração extremamente dolorosa em região vulvar à direita, de início há 2 dias. Ao exame físico\nvocê diagnostica Bartholinite. Assinale a alternativa INCORRETA.","options":{"A":"Um provável patógeno a ser investigado é a Neisseria gonorrhoeae.","B":"Prática sexual sem preservativos pode ser considerada fator de risco para o caso em questão.","C":"A cirurgia de Marsupialização é uma opção terapêutica nesse caso.","D":"A Bartholinectomia de urgência deve ser a conduta preferencial, pois alivia e trata\ndefinitivamente os sintomas."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161216","number":"161216","sourceNumber":"161216","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação à gonorreia em mulheres, aponte a opção INCORRETA.","options":{"A":"Pode ser causa de Doença Inflamatória Pélvica.","B":"A Neisseria é uma bactéria Gram negativa que coloniza o epitélio cilíndrico.","C":"A maioria das pacientes contaminadas é sintomática, apresentando corrimento esverdeado\nabundante.","D":"O tratamento pode ser feito com Ceftriaxona + Azitromicina em dose única."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161357","number":"161357","sourceNumber":"161357","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Os sintomas mais comuns em infecções genitais altas e baixas são,\nRESPECTIVAMENTE:","options":{"A":"dor e corrimento.","B":"corrimento e dor.","C":"corrimento e corrimento.","D":"corrimento e disúria."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161156","number":"161156","sourceNumber":"161156","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Primigesta de 42 semanas comparece à maternidade apresentando lesão ativa por\nherpes genital (vesículas). Diante de tal situação, aponte a alternativa que apresenta a conduta\nCORRETA.","options":{"A":"Cesárea.","B":"Iniciar indução com misoprostol.","C":"Iniciar indução com ocitocina.","D":"Indução com misoprostol e analgesia precoce."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161224","number":"161224","sourceNumber":"161224","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Aponte a alternativa que NÃO é considerada uma característica da síndrome de\nFitz-Hugh-Curtis.","options":{"A":"Causada pela Neisseria gonorroeae.","B":"É complicação grave de DST.","C":"O tratamento de escolha é metronidazol via oral.","D":"As lesões são classicamente chamadas de ?corda de violino?."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161164","number":"161164","sourceNumber":"161164","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante de 16 semanas com VDRL 1/32 refere alergia à penicilina. Em relação a essa\nsituação, assinale a alternativa que apresenta a conduta CORRETA.","options":{"A":"Não necessita de tratamento devido ao baixo título de VDRL.","B":"Deve ser tratada com Eritromicina via oral por 15 dias.","C":"Deve ser tratada com Penicilina após dessensibilização.","D":"Deve ser tratada com Doxiciclina via oral por 15 dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161228","number":"161228","sourceNumber":"161228","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com leucorreia abundante, com odor fétido, sem prurido. O pH vaginal é 5,0 e\no teste das aminas positivo (odor\ndesagradável). Em relação a essa situação, indique a opção que\napresenta o diagnóstico e tratamento, RESPECTIVAMENTE.","options":{"A":"Candidíase / Nistatina.","B":"Vaginose Bacteriana / Metronidazol.","C":"Vaginose Bacteriana / Fluconazol.","D":"Candidíase / Metronidazol."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-161233","number":"161233","sourceNumber":"161233","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Aponte a alternativa que apresenta a lesão típica da sífilis secundária em vulva.","options":{"A":"Condiloma plano.","B":"Condiloma acuminado.","C":"Cancro duro.","D":"Lesão nodular não ulcerada."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-131385","number":"131385","sourceNumber":"131385","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Assinale a assertiva correta.","options":{"A":"A vaginite por Gardnerella vaginalis tem como característica secreção vaginal de cor cinza, com\nodor de peixe, mais evidente após o coito.","B":"No tratamento da vaginite por Trichomonas vaginalis, metronidazol oral é a droga mais usada\npodendo ser substituída pelo tratamento por\nvia vaginal.","C":"A vulvovaginite por Candida albicans tem como fatores predisponentes gravidez, diabetes e uso\nde\n\nantibióticos, todos associados à redução qualitativa de antibióticos, todos associados à redução\nqualitativa da imunidade celular.","D":"As secreções vaginais normais podem aumentar no meio do ciclo menstrual,\nindependentemente do uso ou não de contraceptivos orais.","E":"Na vaginite atrófica que pode ocorrer nas mulheres na pós-menopausa, as queixas mais comuns\nsão dispareunia e hemorragia pós-coito; não há\nmanifestação de corrimento purulento."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-131333","number":"131333","sourceNumber":"131333","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente no quinto dia pós-parto normal apresentando febre, loquiação purulenta e\ncom mau cheiro, útero amolecido com colo permeável para uma polpa digital. O provável\ndiagnóstico é:","options":{"A":"Endometrite.","B":"Vulvovaginite.","C":"Infecção da episiotomia.","D":"Peritonite.","E":"Tromboflebite pélvica."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-131410","number":"131410","sourceNumber":"131410","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O mais provável diagnóstico de uma paciente HIV positiva que apresenta úlceras\ngenitais dolorosas, com contornos elevados e base recoberta por exsudato purulento, é:","options":{"A":"Cancro mole.","B":"Sífilis.","C":"Herpes.","D":"Linfogranuloma venéreo.","E":"Donovanose."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134840","number":"134840","sourceNumber":"134840","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 30 anos relata corrimento branco sem odor, com prurido vulvar intenso e\nardor vaginal às relações sexuais, refere\nciclos menstruais regulares, refere uso de\nanticoncepcional oral há 8 anos. Fez exame de Papanicolaou há 8 meses que deu normal. Qual é a\nMELHOR conduta para esse caso?","options":{"A":"Colher novo exame de Papanicolaou.","B":"Prescrever antifúngico oral e vaginal.","C":"Prescrever anti-inflamatório e antibiótico.","D":"Prescrever derivado imidazólico oral e vaginal."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134343","number":"134343","sourceNumber":"134343","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 23 anos, vida sexual ativa há 3 anos, parceiro único, usa preservativo nas\nrelações sexuais, nega diabetes ou doenças autoimunes, refere que no período pré-menstrual\nsente prurido vulvar e vaginal intenso, às vezes acompanhado de corrimento branco, grosso tipo\nleite talhado e hiperemia vulvar. Qual é o diagnóstico mais provável?","options":{"A":"Vaginose Bacteriana.","B":"Vulvite Química.","C":"Candidíase Vaginal.","D":"Condilomatose Vulvar."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134861","number":"134861","sourceNumber":"134861","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante de 18 semanas, fez exames de pré-natal com exame de VDRL positivo, com\ntitulação de 1:32. Qual é a MELHOR conduta nesse caso?","options":{"A":"Solicitar novo exame de VDRL para confirmação diagnóstica.","B":"Iniciar tratamento com Penicilina Benzatina.","C":"Realizar amniocentese para avaliar infecção fetal.","D":"Solicitar novo VDRL e exame FTABS para confirmar diagnóstico."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134877","number":"134877","sourceNumber":"134877","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 26 anos vem ao Pronto-socorro com queixa de nodulação na\nvagina há 3 meses, localizada do lado\ndireito (introito vaginal), que vem crescendo\nultimamente, passando de um grão de feijão para o tamanho de um limão, com dor local e piora\napós relações sexuais. Qual é o diagnóstico para esse caso clínico?","options":{"A":"Cancroide / Cancro mole.","B":"Teratoma cístico maduro.","C":"Cancro duro / Sífilis.","D":"Cisto da glândula de Bartholin."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134807","number":"134807","sourceNumber":"134807","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Vaginose bacteriana, uma das principais e mais frequentes infecções vaginais\n(Vulvovaginites), pode ser causada pelos seguintes agentes abaixo, com EXCEÇÃO de","options":{"A":"Mobiluncus sp.","B":"Gardnerella vaginallis.","C":"Neisseria ghonorreae.","D":"Peptoestreptococos."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134836","number":"134836","sourceNumber":"134836","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma gestante com 30 semanas chega à unidade básica para iniciar o seguimento\npré-natal. Dos resultados das provas\nlaboratoriais solicitadas e recebido teste não treponêmico =\nVDRL= 1/16. Com esse resultado, quais são as ações que devem ser realizadas pela equipe?","options":{"A":"Convocação da gestante para coleta de amostra sanguínea para realização de teste\ntreponemo o para a confirmação do diagnóstico.","B":"Convocação da gestante para tratamento com doxiciclina, notificação do caso e convocação do\nparceiro sexual.","C":"Convocação da gestante para tratamento com penicilina benzatina, notificação do caso e\nconvocação do parceiro sexual.","D":"Aguardar a consulta de retorno para o tratamento da gestante e do parceiro sexual com\npenicilina benzatina, notificar o caso."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134335","number":"134335","sourceNumber":"134335","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Para considerar gestante com sífilis adequadamente tratada, leve em conta as\nseguintes afirmativas. I. Tratada com penicilina (esquema próprio para a fase da doença). II.\nTratada antes de quatro semanas do parto. III. Parceiro sexual tratado. IV.\n\nTítulo do VDRL decresceu4 X ou negativou em seis meses. Estão CORRETAS as afirmativas","options":{"A":"I, II e III, apenas.","B":"II e III, apenas.","C":"I, II e IV, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-110578","number":"110578","sourceNumber":"110578","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São contraindicações para o uso do Dispositivo Intrauterino (DIU) de cobre, EXCETO:","options":{"A":"Doença inflamatória pélvica.","B":"Câncer do colo uterino.","C":"Malformações uterinas.","D":"Infecção pelo HPV.","E":"Promiscuidade sexual."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-109776","number":"109776","sourceNumber":"109776","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 30 anos, vida sexual ativa, com uso de contraceptivo oral combinado,\nrefere corrimento amarelado com odor fétido, nega\nprurido, nega disúria, nega dispareunia e\nsinusorragia. Ao especular, apresenta corrimento amarelo com odor forte e teste das aminas\npositivo. Presença de Clue Cels à microscopia. Qual é o patógeno MAIS provável?","options":{"A":"Tricomonas vaginalis.","B":"Candida glabatta.","C":"Gardnerella vaginallis.","D":"Clamídia trachomatis."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-110040","number":"110040","sourceNumber":"110040","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São sequelas importantes da Doença Inflamatória Pélvica, EXCETO:","options":{"A":"infertilidade.","B":"metrorragia.","C":"aderências.","D":"prenhez ectópica."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-109798","number":"109798","sourceNumber":"109798","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Para considerar gestante com sífilis adequadamente tratada, leve em conta as\nseguintes afirmativas. I. Tratada com penicilina (esquema próprio para a fase da doença); II.\nTratada antes de quatro semanas do parto; III. Parceiro sexual tratado; IV. Título do VDRL\ndecresceu 4 X ou negativou em seis meses. Estão CORRETAS as afirmativas contidas em:","options":{"A":"I e II, apenas.","B":"I, II e IV, apenas.","C":"I, II, III e IV.","D":"I, II e III, apenas."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-149292","number":"149292","sourceNumber":"149292","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher com 25 anos de idade, no curso de 20 semanas de gestação, é atendida\nem consulta pré-natal e apresenta resutado de\nVDRL de 1:16. Diz ter realizado tratamento\nadequado para sífilis há dois anos e que, desde então, não apresentou lesões na região genital ou\nerupções cutâneas. Diante dessa situação, a conduta indicada é","options":{"A":"Solicitar VDRL em 1 mês e proceder a novo tratamento se houver elevação dos títulos do VDRL.","B":"Prescrever penicilina benzatina 2,4 milhões UI, por via intramuscular, em dose única, para a\npaciente e seu parceiro.","C":"Prescrever penicilina benzatina 2,4 milhões UI, por via intramuscular, uma dose semanal por 3\nsemanas (total de 7,2 milhões de UI), para a paciente e seu parceiro.","D":"Prescrever penicilina G cristalina aquosa 3 milhões UI por via endovenosa, a cada 4 horas por\n14 dias, para a paciente, e penicilina\nbenzatina 2,4 milhões UI, por via intramuscular, em dose\núnica, para o parceiro."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-86630","number":"86630","sourceNumber":"86630","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando uma grávida primigesta, portadora do vírus HIV. Sua carga viral entre a\n34ª?37ª semana encontra-se em torno de 1.500 cps/ml. Qual a melhor conduta?","options":{"A":"Realizar o parto vaginal espontâneo no termo.","B":"Realizar cesárea na 36ª semana.","C":"Realizar o parto vaginal induzido na 38ª semana.","D":"Realizar o parto vaginal na 40ª semana.","E":"Realizar cesárea na 38ª semana."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-86619","number":"86619","sourceNumber":"86619","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 20 anos manteve contato sexual e apresentou um quadro de cervicite com\ncolo hiperemiado, sangrante, friável, com pequenas ulcerações: queixou-se de disúria,\nincontinência urinária e síndrome uretral. O medicamento de escolha foi a Doxaciclina pois o\ndiagnóstico identificado foi:","options":{"A":"Neisseria gonorrhoeae;","B":"Chlamydia trachomatis;","C":"Donovania granulomatis;","D":"Herpes simplex;","E":"Sífilis."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-86615","number":"86615","sourceNumber":"86615","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A., 18 anos, G1P1A0, apresenta corrimento vaginal amarelado, espesso, em grande\nquantidade, com mau cheiro, acompanhado de\ndor ao coito (penetração), sem dor à mobilização do\ncolo uterino. Qual o diagnóstico MENOS provável:","options":{"A":"Vaginose bacteriana.","B":"Tricomoníase vaginal.","C":"Cervicite clamídia.","D":"Cervicite gonocócica.","E":"Infecção pelo HPV."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-86588","number":"86588","sourceNumber":"86588","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A vaginose bacteriana possui as seguintes características:","options":{"A":"Diminuição dos lactobacilos e intenso processo inflamatório.","B":"Intenso processo inflamatório e diminuição do pH vaginal.","C":"Predomínio de Gardnerella vaginalis e aumento do pH vaginal.","D":"Produção de aminas e pH diminuído.","E":"Predomínio de Trichomonas vaginalis e pH vaginal aumentado."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-362500","number":"362500","sourceNumber":"362500","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Donovanose é causada por qual agente etiológico?","options":{"A":"Chlamydia Trachomatis.","B":"Kebsiela granulomatis.","C":"Haemóphilus ducreyi.","D":"Mycoplasma genitalium."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-362499","number":"362499","sourceNumber":"362499","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Qual das alternativas abaixo é manifestação da sífilis secundária?","options":{"A":"Assintomática.","B":"Linfonodos regionais.","C":"Lesões cutâneo mucosas.","D":"Lesões gomosas e nodulares."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-362498","number":"362498","sourceNumber":"362498","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente 28 anos foi ao ginecologista com queixa de corrimento vaginal. O PH vaginal\nfoi 5 e o teste de KOH positivo. Baseado na\nconduta do Ministério da Saúde, qual a melhor\nconduta?","options":{"A":"Ceftriaxona 500mg, IM, dose única.","B":"Clindamicina 300mg, VO, 2x/dia, por 7 dias.","C":"Itraconazol 100mg, 2 comprimidos, VO, 2x/dia, por 1 dia.","D":"Metronidazol 250mg, 2 comprimidos, VO, 2x/dia, por 7 dias."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-362497","number":"362497","sourceNumber":"362497","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente foi ao ginecologista no interior do Amazonas, referindo úlcera genital que\napareceu há 2 semanas. Ao exame físico,\nobservou-se lesão ulcerada vulvar, cuja causa provável é\numa infecção sexualmente transmissível. Não há laboratório disponível no local. De acordo com o\nMinistério da Saúde, como o médico assistente deve proceder para o melhor cuidado da paciente?","options":{"A":"Tratar sífilis e cancroide.","B":"Tratar sífilis e cancroide e investigar linfogranuloma venereo e Donovanose.","C":"Tratar cancroide, hérpes genital, donovanose e linfogranuloma venéreo.","D":"Referenciar a paciente para um grande centro para diagnóstico e tratamento."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-362460","number":"362460","sourceNumber":"362460","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A., 30 anos, comparece para iniciar seu pré-natal na UBS onde atua como médico de\numa das equipes de Estratégia Saúde da\nFamília. Ela se encontra na 10a. semana de gestação\nconforme a data da última menstruação e realizou naquele momento os testes rápidos para\ninfecções sexualmente transmissíveis com o seguinte resultado: ? Teste Rápido para HIV: não\nreagente; ? Teste Rápido para sífilis: reagente; ? Teste Rápido para Hepatite B e C: não reagente;\nA gestante foi encaminhada para atendimento médico e relatou nunca ter feito tratamentos prévios\ncom Penicilina Benzatina. Contou que nunca percebeu lesões genitais, mas há cerca de um ano e\nmeio teve lesões na pele, inclusive na palma das mãos, não pruriginosas e que sumiram depois de\num tempo. Considerando o caso, a melhor conduta ser tomada seria:","options":{"A":"Tratar com penicilina benzatina 2.400.000UI por três semanas, por se tratar de caso de sífilis\nlatente tardia ou de duração indeterminada.","B":"Tratar com penicilina benzatina 2.400.000UI por três semanas, por se tratar de caso de sífilis\nlatente recente.","C":"Solicitar VDRL para confirmação diagnóstica.","D":"Solicitar um segundo teste treponêmico, uma vez que o teste rápido tem elevada probabilidade\nde falso positivo na gravidez."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-327264","number":"327264","sourceNumber":"327264","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Segundo Manual do Ministério da Saúde 2022, com qual frequência deve ser realizado\no rastreamento de HIV e sífilis na população de\nadolescentes e jovens (idade menor ou igual a 30\nanos)?","options":{"A":"6 semanas após exposição","B":"3 meses após exposição","C":"Anualmente","D":"Semestralmente"},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-327265","number":"327265","sourceNumber":"327265","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Na classificação de síndromes de úlcera anogenital, preconizada pelo ministério da\nsaúde 2022, o agente etiológico responsável\npela Donovanose é:","options":{"A":"Haemophilus ducreyi","B":"Chlamydia trachomatis","C":"Klebsiela granulomatis","D":"Mycoplasma genitalium"},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-327266","number":"327266","sourceNumber":"327266","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São manifestações da sífilis primária:","options":{"A":"Roseólas, placas mucosas","B":"Sifilides, linfonodos regionais","C":"Micropoliadenopatia, Roséolas","D":"Cancro duro, Linfonodos regionais"},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-327268","number":"327268","sourceNumber":"327268","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente 20 anos refere corrimento vaginal claro, com prurido, ardência vulvar, com\npiora no período pré-menstrual. Ao exame ginecológico: corrimento vaginal, branco, fluido.\n\nBacterioscopia evidenciou grande quantidade de polimorfonucleares, lactobacilos ++++/4 e células\nintermediarias integras. O teste de aminas foi negativo e o PH vaginal é 4,0. Qual diagnóstico\nprovável?","options":{"A":"Vaginose bacteriana","B":"Vulvovaginite por cândida","C":"Vaginose citolítica","D":"Mucorréia"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-327303","number":"327303","sourceNumber":"327303","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"M., 36 anos, homem, comparece à consulta de seguimento devido à sífilis; há 6 meses\nrealizou tratamento com 3 doses de penicilina benzatina (2.400.000 UI por semana durante 3\nsemanas) e faz acompanhamento com VDRL trimestral. Os valores de VDRL detectados nos\nexames foram os seguintes: Diagnóstico de sífilis: VDRL 1/128 (realizado tratamento corretamente\ncom 3 doses de Penicilina benzatina); 3º. Mês pós-tratamento: VDRL 1/32; 6º. Mês pós-tratamento:\nVDRL 1/8; O paciente não realizou seu VDRL do 9º. Mês, retornando para consulta apenas no 12º.\nMês após o tratamento inicial, com valor de VDRL de 1/64. Considerado o padrão de VDRL da\nconsulta mais recente, qual a melhor conduta a ser tomada?","options":{"A":"Deve ser mantido o acompanhamento com VDRL trimestral, uma vez que se trata de cicatriz\nsorológica.","B":"O acompanhamento deve ser feito mensalmente, sendo tratado novamente caso haja um valor\nsemelhante.","C":"Houve falha terapêutica, sendo indicado doxiciclina por via oral durante 30 dias.","D":"A elevação de duas ou mais titulações durante o seguimento significa necessidade de\nretratamento com Penicilina Benzatina no mesmo\nesquema de 3 doses, uma por semana, por 3\nsemanas (2.400.000 UI semanal)."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-327316","number":"327316","sourceNumber":"327316","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação ao atendimento de adolescentes vítimas de violência sexual, assinale a\nalternativa CORRETA.","options":{"A":"As unidades de atenção primária não estão preparadas para atendimento de uma adolescente\nvítima de violência sexual.","B":"Adolescentes vítimas de violência sexual devem ser atendidas exclusivamente na presença da\nmãe.","C":"O médico da família e comunidade deve sempre referenciar a adolescente com urgência ao\nginecologista.","D":"As unidades de saúde, em todos os níveis de cuidado, devem estar capacitadas para o\natendimento e o cuidado de uma adolescente vítima de violência sexual."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-298190","number":"298190","sourceNumber":"298190","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A sífilis é uma infecção sexualmente transmissível curável causada pela bactéria\ntreponema pallidum sendo CORRETO afirmar que:","options":{"A":"O diagnóstico da sífilis latente é baseado na história clínica do indivíduo e na combinação de\nresultados dos testes. Pacientes assintomáticos sem história pregressa de sífilis que apresentem\nresultado reagente em qualquer teste imunológico deverão ser tratados.","B":"Na sífilis primária, a manifestação característica é o cancro duro não acompanhado de\nlinfadenomegalia regional, e o diagnóstico laboratorial pode ser realizado pela pesquisa direta do\ntreponema pallidum por microscopia de campo escuro, pelos métodos de coloração ou pela\nimunofluorescência direta, em amostras da lesão e/ou material de biópsia.","C":"Após o tratamento da sífilis secundária, os testes treponêmicos, na grande maioria dos casos,\npermanecem reagentes por toda a vida do usuário, e os testes não treponêmicos podem ter\ncomportamento variável. Em alguns indivíduos tornam-se não reagentes, e em outros permanecem\nindefinidamente reagentes em altos títulos.","D":"Caracteriza-se como sífilis congênita precoce aquela que se manifesta antes dos quatro\nprimeiros anos de vida."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-298234","number":"298234","sourceNumber":"298234","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente foi ao ginecologista com história de pápula eritematosa que evoluiu para\npústula e posterior ulceração dolorosa. Ao exame a ulceração era fétida, irregular com bordos\nendurados e base purulenta localizada na fúrcula vaginal. O esfregaço coletado identificou\nbastonetes gram negativos sem motilidade. Qual o diagnóstico?","options":{"A":"Sífilis","B":"Linfogranuloma Venéreo","C":"Cancro mole","D":"Herpes com vesícula rota"},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-298235","number":"298235","sourceNumber":"298235","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Qual agente etiológico do linfogranuloma venéreo?","options":{"A":"Chlamydia trachomatis","B":"Haemophilus ducreyi","C":"Klebsiela granullomatis","D":"Mycoplasma genitalium"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-286752","number":"286752","sourceNumber":"286752","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com úlcera genital vai à UBS para atendimento. Qual os possíveis agentes\netiológicos dessa síndrome de úlcera anogenital?","options":{"A":"Treponema pallidum; Vírus do Hespes simplex (tipo2); Mycoplasma genitalium","B":"Chlamydia trachomatis; Haemophilus ducreyi; Klebsiela granulomatis","C":"Haemophilus ducreyi; Klebsiela granulomatis; Chlamydia trachomatis (sorovars D ao K)","D":"Treponema pallidum; Chlamydia trachomatis; Mycoplasma genitalium"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-286753","number":"286753","sourceNumber":"286753","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente foi ao ambulatório da UBS com resultado de VDRL, FTAbs e microscopia em\ncampo escuro positivos. Clinicamente\napresentava lesões compatíveis com sifílides papulosas e\nlinfoadenopatia generalizada. Em qual estágio esse paciente deve ser classificado e como deve ser\ntratado respectivamente?","options":{"A":"Sífilis primaria; Benzilpenicilina Benzatina, 2,4 milhões UI intramuscular dose única","B":"Sífilis latente; Benzilpenicilina Benzatina, 2,4 milhões UI intramuscular por 3 semanas","C":"Sífilis terciaria; Benzilpenicilina Benzatina, 2,4 milhões UI intramuscular por 3 semanas","D":"Sífilis secundária; Benzilpenicilina Benzatina, 2,4 milhões UI intramuscular dose única"},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-286754","number":"286754","sourceNumber":"286754","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente foi ao ambulatório de ginecologia com corrimento vaginal de odor fétido. Ao\nexame ginecológico, foi observado corrimento\nhomogêneo, amarelado. Teste de Wiff positivo.\n\nAssinale a alternativa CORRETA:","options":{"A":"O diagnóstico provável é tricomoníase. No entanto, para confirmação, deve-se realizar a\ncoloração por gram e utilizar o escore de Nuget.","B":"O diagnnóstico provável é Chlamidia. No entanto, para confirmação, deve-se realizar o exame a\nfresco com KoH.","C":"O diagnóstico provável é Vaginose bacteriana. No entanto, para confirmação, deve-se realizar a\ncoloração por gram e utilizar o escore de Nuget.","D":"O diagnóstico provável é Gonorréia. No entanto, para confirmação, deve-se realizar o exame à\nfresco."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-286794","number":"286794","sourceNumber":"286794","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paula, 19 anos, está na 21a. semana de gravidez e compareceu à consulta médica na\nUBS. Encontrava-se assintomática e trazia consigo resultados de exames. O VDRL apresentado\ntinha resultado 1:4, sendo encaminhada para realizar teste rápido para sífilis o qual foi reagente.\n\nRelatou que nunca percebeu nenhuma úlcera genital nem sequer realizou tratamento com\nantibiótico. Refere que o marido não tem queixas. Sobre o caso, uma conduta CORRETA é:","options":{"A":"Tratar a gestante com penicilina G benzatina, 2.400.000 U, semanal, por 3 semanas e realizar\nVDRL mensal até o parto.","B":"Tratar a gestante com penicilina G benzatina, 2.400.000 U, em dose única e realizar VDRL\ntrimestral.","C":"Não se faz necessário fazer testes para sífilis no marido de Paula.","D":"Não é necessário tratar porque os níveis de VDRL são baixos e trata-se de cicatriz sorológica."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-256573","number":"256573","sourceNumber":"256573","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Homem, 21 anos, há 4 dias evoluindo com exsudato uretral purulento e disúria. Em\nrelação ao caso clínico, assinalar a assertiva CORRETA:","options":{"A":"Trata-se de infecção do trato urinário inferior; a droga de escolha é amoxicilina","B":"O teste de Tzanck revelará células multinucleadas, confirmando diagnóstico de herpes simples","C":"Clamídia e gonococo são os principais agentes etiológicos","D":"A cultura do exsudato confirmara o diagnóstico de donovanose"},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-252263","number":"252263","sourceNumber":"252263","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente foi ao ginecologista com queixa de corrimento vaginal e sangramento pós\ncoito. Ao exame especular, presença de\nsecreção mucopurulenta saindo do colo uterino. O Gram\nda secreção cervical revelou diplococos Gram negativos com leucócitos polimofonucleares. Foi\nsolicitada a cultura da secreção. Baseado nos achados acima, qual agente etiológico espera-se\nencontrar?","options":{"A":"Mycoplasma hominis","B":"Chamydia Trachomatis","C":"Haemophilus Ducreyi","D":"Neisseria gonorrhoeae"},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-252264","number":"252264","sourceNumber":"252264","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Qual o tratamento de escolha para a tricomoníase?","options":{"A":"Clindamicina 7 dias","B":"Metronidazol 2 g dose única","C":"Cefoxitina 2g dose única","D":"Ampicilina 7 dias"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-208406","number":"208406","sourceNumber":"208406","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Devido ao crescente achado de bactérias resistentes, qual droga deixou de ser\nrecomendada pelo Ministério da Saúde para\ntratamento de uretrite gonocócica nos estados do RJ,\nSP e MG?","options":{"A":"Aminoglicosídeos","B":"Azalídeos","C":"Cefalosporinas","D":"Quinolonas"},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-208396","number":"208396","sourceNumber":"208396","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente foi ao ginecologista com queixa de corrimento vaginal. Ao exame foi\nobservada secreção vaginal homogênea, acinzentada, com odor desagradável. Assinale a\nalternativa correta quanto ao agente etiológico e achados no exame com KOH.","options":{"A":"Candidíase - Hifas","B":"Trichomonas - Cels de Amsel","C":"Chlamydia - Cels Gummy Ster","D":"Vaginose bacteriana - Clue cels"},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-208409","number":"208409","sourceNumber":"208409","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 23 anos, foi ao ginecologista com úlcera genital que teve início há 1 semana.\nAo exame físico, observou-se úlcera sem a\npresença de vesículas. Segundo o manual do Ministério\nda Saúde, a conduta a ser adotada na abordagem sindrômica referente ao tratamento presuntivo é\ntratar:","options":{"A":"Herpes genital.","B":"Donovanose e sífilis.","C":"Clamídia e gonorreia.","D":"Sífilis e cancro mole."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-208439","number":"208439","sourceNumber":"208439","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 18 anos procurou serviço médico em pronto atendimento de sua região\ncom queixa de dor, que fica intensa quando\nurina (contato da urina com as lesões), queimação\nvaginal e coceira. Há 10 dias percebeu umas \"bolinhas\" (vesículas) em suas partes íntimas. Relata\nter ido ao médico da UBS e foi prescrito uma pomada que usou por sete dias sem melhora. Foi\nquestionada se já havia apresentado esse quadro anteriormente e respondeu que essa era a\nprimeira vez que apresentava essa queixa. Menarca aos 11 anos, vida sexual ativa desde os 13\nanos com um total de oito parceiros até o momento. Informou ainda que fez um tratamento para\nverruga genital há 2 anos quando estava grávida. Há dois dias acabou o seu namoro. Marque a\nalternativa incorreta:","options":{"A":"O diagnóstico desse caso é herpes genital primoinfecção. Pode ser tratado com valaciclovir 500\nmg via oral de 12 em 12 horas, por cinco\ndias, 1 g dose única diária, por cinco dias","B":"Nos EUA, país que tem várias pesquisas, a maioria das mulheres com úlceras genitais tem\ninfecção pelo Herpes Simples Viral (HSV) ou\nsífilis e o cancroide é a terceira causa mais comum de\núlceras genitais.","C":"A primoinfecção ocorre entre quatro a sete dias após a exposição, em indivíduos não expostos\npreviamente ao herpes-vírus.","D":"No HSV primoinfecção nem todos os expostos desenvolverão manifestação clínica exuberante,\npodendo haver infecção subclínica com\nevolução para a fase de portador."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-176081","number":"176081","sourceNumber":"176081","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente 32 anos foi ao ginecologista referindo a presença de lesões bilaterais e\nmúltiplas na vulva, com dor intensa, que evoluíram para crostas, linfadenopatia inguinal dolorosa,\ndisúria, febre e mialgia. Qual tratamento adequado?","options":{"A":"Aciclovir 400 mg VO 3x/dia por 7-10 dias.","B":"Tianfenicol 250 mg VO 8/8h.","C":"Doxiciclina 100 mg VO 12/12h.","D":"Minociclina 100 mg VO 12/12h."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-176077","number":"176077","sourceNumber":"176077","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Assinale a resposta CORRETA quanto à transmissão vertical do HIV:","options":{"A":"O sorotipo L da Chlamydia trachomatis aumenta a velocidade de replicação do HIV.","B":"Na vaginose bacteriana, há notável aumento do Lactobacillus crispatus, levando ao aumento da\ntransmissão vertical do HIV.","C":"A despeito de não ser infalível, a carga viral é o\n\nmais importante preditor de risco para a transmissão perinatal do vírus.","D":"Paciente com carga viral abaixo de 100.000 cópias/ml, a transmissão vertical do HIV é evento\npossível, mas extremamente raro."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-151977","number":"151977","sourceNumber":"151977","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"MOP, 35 anos foi levada a maternidade pelo vizinho com fortes dores abdominais.\nPredominantemente em fossa ilíaca direita. Refere que há 1 ano foi internada com dor e foi tratada\nclinicamente com azitromicina. A última menstruação foi há 2 meses. Ao exame físico, observa-se\ndor abdominal difusa e equimose periumbilical. Ao toque vaginal, observa-se sangramento vaginal\ndiscreto e massa palpável à esquerda. Foi solicitado um ßHCG cujo resultado foi 3200 ui. Baseado\nno diagnóstico, assinale os fatores de risco da patologia da paciente.","options":{"A":"Alimentos pequenos como caroço de mamão, uso de drogas ilícitas, o uso de levonorgestrel\ncomo anticoncepção de emergência.","B":"Trichomonas vaginalis, uso de dispositivo intrauterino, antecedente de gravidez ectópica e o uso\nde duchas vaginais de repetição.","C":"Trichomonas vaginais, uso de dispositivo intrauterino, antecedente de gravidez ectópica e o uso\nde estriol como anticoncepção de emergência.","D":"Chlamydia trachomatis, uso de dispositivo intrauterino, antecedente de gravidez ectópica e o uso\nde levonorgestrel como anticoncepção de\nemergência."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152023","number":"152023","sourceNumber":"152023","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Correlacione a coluna dos SINTOMAS com a coluna das VULVOVAGINITES:\nSINTOMAS: A - Prurido, ardência, corrimento\nsem odor, dispareunia de introito vaginal; B -\nCorrimento homogêneo, ph > 4,5, whiff teste positivo; C - Pode ser assintomático. Corrimento\nvaginal amarelado esverdeado, bolhoso, espumoso; pode ser acinzentado com odor fétido. Ao\nexame clínico tem aspecto de morango; D - Ocasionada por exacerbação de lactobacilos. Pode se\navaliar os sintomas alcalinizando o meio vaginal. VULVOVAGINITES: 1 - Vaginose Bacteriana; 2 -\nCandidiase; 3 - Vaginose Citolitica; 4 - Tricomoníase. A sequência CORRETA é:","options":{"A":"A-2, B-1, C-4, D-3.","B":"A-2, B-3, C-1, D-4.","C":"A-3, B-4, C-2, D-1.","D":"A-4, B-2, C-3, D-1."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-129754","number":"129754","sourceNumber":"129754","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente chega ao ambulatório de seu pequeno município no interior com queixa de\núlcera genital há 2 semanas. Ao exame fisíco, observou-se úlceras genitais sem história de lesões\nvesiculosas. Baseado no protocolo do ministério da Saúde visando abordagem sindrômica, qual o\ntratamento de primeira escolha?","options":{"A":"Penicilina G benzatina 2,4 milhoes UI via intramuscular associado a Azitromicina 1g via oral dose\nunica.","B":"Aciclovir 400 mg 12/12h por até 6 anos.","C":"Famciclovir 250 mg via oral de 8/8 h por 7 dias associado a Penicilina G benzatina 2,4 milhões\nUI via intramuscular por 2 semanas.","D":"Azitromicina 1g via oral dose única associado a Valaciclovir 500 mg vo 12/12h por 5 dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-129804","number":"129804","sourceNumber":"129804","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma adolescente de 15 anos apresenta dor abdominal, vômitos e letargia há três dias.\nNo exame físico não há anormalidades no tórax\ne orofaringe, mas ao exame abdominal observa-se\ndor no quadrante inferior direito. O exame retal é duvidoso em relação à presença de dor, mas o\nexame da pelve revela dor à mobilização da cérvice. Os dados laboratoriais incluem contagem de\nleucócitos de 18.000/mm³, glicemia 145 mg/dL e nível de bicarbonato sérico de 21 mEq/dL. O\nexame de urina demostra Leuco 1+, Glicose 1+ e cetonas 1+. Qual das opções a seguir representa\no diagnóstico mais provável?","options":{"A":"Apendicite.","B":"Cetoacidose diabética (CAD).","C":"Doença inflamatória pélvica.","D":"Pneumonia do lobo inferior direito."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-107903","number":"107903","sourceNumber":"107903","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Jaqueline, 17 anos, com vida sexual ativa, foi ao ginecologista pois estava com\nardência vulvar importante há uma semana,\ndores musculares e febrícula. Ao exame ginecológico,\nobservou-se na vulva lesões múltiplas, ulceradas, dolorosas e com fundo purulento. Havia\nlinfadenopatia inguinal a direita em processo de supuração. Qual agente etiológico é o responsável\npor esse quadro clínico?","options":{"A":"Calymatobacterium granulomatis.","B":"Haemophylus ducreyi.","C":"Chlamydia thrachomatis.","D":"Treponema pallidum."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-103878","number":"103878","sourceNumber":"103878","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"As Doenças Sexualmente Transmissíveis (DST) estão entre os problemas de saúde\npública mais comuns em todo o mundo, com uma estimativa de 340 milhões de casos novos por\nano (OMS, 2001). Assinale a alternativa INCORRETA:","options":{"A":"Entre as síndromes em DST, o corrimento vaginal pode caracterizar-se por: corrimento vaginal\ne/ou cervical, prurido, dor à micção, dor à relação sexual, além de edema e hiperemia de vulva.","B":"A abordagem sindrômica em DST também inclui a atenção aos parceiros e a oferta da sorologia\npara sífilis, hepatites e para o HIV. Na\nsíndrome do corrimento uretral, na suspeita de Clamídia e\nGonorreia, uma das opções de tratamento inclui a associação de Penicilina G Benzatina, 2,4\nmilhões UI, via IM, em dose única (1,2 milhão UI em cada nádega), Azitromicina 1 g VO em dose\núnica.","C":"Na suspeita clínica de primeiro episódio de herpes genital, deve-se iniciar o tratamento o mais\nprecocemente possível. Uma das opções é o Aciclovir 200mg, 4/4 horas, 5vezes/dia, por 7 dias ou\n400 mg, 8/8 horas, por 7 dias.","D":"Na síndrome do corrimento uretral, na suspeita de Clamídia e Gonorreia, uma das opções de\ntratamento inclui a associação de Penicilina G Benzatina, 2,4 milhões UI, via IM, em dose única (1,2\nmilhão UI em cada nádega), Azitromicina 1 g VO em dose única."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-103883","number":"103883","sourceNumber":"103883","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A violência sexual é uma das manifestações da violência de gênero mais cruéis e\npersistentes. Diz-se persistente porque a violência sexual atravessa a história e sobrevive. Em\nrelação à assistência às vítimas de violência sexual, está INCORRETO:","options":{"A":"É desejável que a equipe de saúde seja composta por médicos(as), psicólogos(as),\nenfermeiros(as) e assistentes sociais.","B":"Em casos de gravidez, suspeita ou confirmada, deve-se considerar a demanda da mulher ou da\nadolescente, identificando se manifesta desejo ou não de interromper a gravidez.","C":"Está definido pela Lei n° 8.069/1990 - Estatuto da Criança e do Adolescente (ECA), que foi\nregulamentado pelo MS através da Portaria MS n° 968/2001 a notificação compulsória de\nviolências contra crianças e adolescentes. Mas não é necessário o encaminhamento de cópia da\nficha de notificação ao Conselho Tutelar da Criança e do Adolescente.","D":"A anticoncepção de emergência hormonal constitui o método de eleição devido ao baixo custo,\nboa tolerabilidade, eficácia elevada e ausência de\ncontraindicações absolutas. Costuma ser usado\no levonorgestrel, na dose total de 1,5 mg VO em dose única."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-107832","number":"107832","sourceNumber":"107832","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma das queixas mais comuns que o médico de família e comunidade se depara são\nas leucorreias. Assinale a opção que demonstra a\nassociação CORRETA entre a infecção do trato\nreprodutor feminino e o tratamento proposto:","options":{"A":"Vaginose bacteriana - tratamento com fluconazol 150 mg, VO, dose única.","B":"Clamídia - tratamento com azitromicina 1 g, VO, em dose única.","C":"Tricomoníase - tratamento com ceftriaxona, 250 mg, IM, dose única.","D":"Candidíase - tratamento com eritromicina (estearato), 500 mg, VO, de 6/6h, 7 dias."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-80978","number":"80978","sourceNumber":"80978","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Numere a coluna da direita de acordo com sua correspondência com a coluna da\nesquerda, correlacionando as doenças sexualmente\ntransmissíveis as suas técnicas diagnósticas 1.\nClamídia; 2. Cancro mole; 3. Donovanose; 4. Gonorreia; 5. HPV ( ) O diagnóstico das lesões\nvegetantes e clínico. A biópsia de lesão ou de área suspeita pode ser realizada para auxiliar\ndecisões mais difíceis. O diagnóstico definitivo das infecção é feito pela identificação da presença\ndo DNA viral por meio de testes de hibridização molecular (hibridização in situ, PCR, captura\nhíbrida). ( ) A bacterioscopia da secreção uretal é um bom método pela técnica do Gram: evidencia\na presença de diplococos Gram-negativos no interior de polimorfonucleares e aumento no número\nde leucócitos polimorfanucleares. Para cultura, utiliza-se o meio seletivo de Thayer-Martim. ( ) O\ndiagnóstico é baseado na biopsia da lesão e deve sempre ser afastada a hipótese de neoplasia. ( )\nA bacterioscopia da secreção uterial e colocação por Gram não tem boa sensibilidade, mas podem\nafastar a hipótese da doença quando da ausência de diplococos em secreção uretral. ( ) A\nbacterioscopia com pesquisa do Haemophilus ducreyi é pilar diagnóstico. Assinale a alternativa que\napresenta a numeração correta da coluna da direita, de cima para baixo.","options":{"A":"2 - 4 - 5 - 1 - 3","B":"3 - 5 - 2 -1 - 4","C":"4 - 5 - 3 - 2 - 1","D":"5 - 3 - 4 - 2 - 1","E":"5 - 4 - 3 - 1 - 2"},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-87410","number":"87410","sourceNumber":"87410","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Ursula foi ao ginecologista referindo corrimento vaginal. Pedro após o exame físico,\ncoletou a secreção vaginal com a espátula de\nAyre espalhando-a sobre a lâmina preparada com\nKOH e outra com soro fisiológico. Ao cheirar a lâmina detectou odor amínico. De qual vulvovaginite\nPedro deve suspeitar?","options":{"A":"Ureaplasma urealyticum.","B":"Mycoplasma hominis.","C":"Candidíase vaginal.","D":"Trichomoníase.","E":"Vaginose bacteriana."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-87478","number":"87478","sourceNumber":"87478","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma das queixas mais comuns que o Médico de Família e Comunidade se depara são\nas leucorreias. Assinale a opção que demonstra a\nassociação correta entre a infecção do trato\nreprodutor feminino e o tratamento proposto:","options":{"A":"Vaginose bacteriana - tratamento com Fluconazol 150 mg, VO, dose única.","B":"Gonorreia - tratamento com Secnidazol 2 g, VO, dose única.","C":"Tricomoníase - tratamento com Ceftriaxona, 250 mg, IM, dose única.","D":"Candidíase - tratamento com Eritromicina (estearato), 500 mg, VO de 6/6h, 7 dias.","E":"Clamídia - tratamento com Azitromicina 1 g, VO em dose única."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-80986","number":"80986","sourceNumber":"80986","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente 38 anos refere corrimento vaginal abundante, amarelo esverdeado, bolhoso e\ncom odor fétido. O diagnóstico mais provável e a propedêutica prática para complementar o\ndiagnóstico é:","options":{"A":"Tricomoníase - Exame a fresco;","B":"Vaginose Bacteriana - Colposcopia;","C":"Vaginose Bacteriana - Coloração pelo gram;","D":"Vaginose citolítica - Colprocitologia;","E":"Pseudomoníase - Coloração pelo gram."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-82006","number":"82006","sourceNumber":"82006","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 25 anos apresenta febre e dor intensa no baixo-ventre. A USG revelou\npresença de massa complexa de 4 cm em região anexial esquerda sugestiva de abscesso\ntubo-ovariano. Qual a conduta imediata?","options":{"A":"Culdotomia;","B":"Laparoscopia;","C":"Laparotomia;","D":"Antibioticoterapia;","E":"Punção transvaginal."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-81944","number":"81944","sourceNumber":"81944","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação à vaginose bacteriana das afirmativas abaixo, qual(is) é (são)\nverdadeira(s)? I. Ocorre uma alteração da\nflora bacteriana vaginal normal com perda de\nlactobacilos produtores de peróxido de hidrogênio. II. O pH da secreção vaginal é maior que 4,5.\nIII.\nA microscopia das secreções vaginais mostra aumento das células indicadoras e ausência de\nleucócitos. IV. O tratamento com fenticonazol vaginal tem mostrado menores recidivas.","options":{"A":"I, II e III","B":"I, II, III e IV","C":"I, II e IV","D":"II e III","E":"I e IV"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-60834","number":"60834","sourceNumber":"60834","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A candidíase vaginal é caracterizada por:","options":{"A":"apresentar pH da vagina normal","B":"estar associada à vaginose bacteriana","C":"ser mais prevalente em crianças e idosas","D":"não responder à terapia antifúngica convencional","E":"apresentar Trichomonas vaginalis no esfregaço cérvico vaginal"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-49818","number":"49818","sourceNumber":"49818","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 24 anos, branca, Gesta II Para II (2 cesarianas), queixa-se de corrimento\namarelo-esverdeado e de odor fétido, que piora após as relações sexuais. Qual o provável agente\netiológico?","options":{"A":"Candida albicans;","B":"Trichomonas vaginallis;","C":"Gardnerella;","D":"Streptococcus;","E":"Enterocoçcus."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-46716","number":"46716","sourceNumber":"46716","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"No diagnóstico sindrômico das Doenças Sexualmente Transmissíveis:","options":{"A":"Embora as DST sejam causadas por muitos micro-organismos diferentes, estes apenas\ndeterminam um número limitado de sídrome.","B":"As principais sídromes em DST são: corrimento vaginal, corrimento uretral, úlcera genital e\ndesconforto ou dor pélvica na mulher.","C":"Entre as etiologias mais comuns do corrimento vaginal estão Gonorreia, infecção por Clamídia,\nMicoplasma e Ureaplasma.","D":"Os sinais mais frenquentes na síndrome da úlcera genital são úlcera genital e linfonodos\ngenitais.","E":"Entre as principais características da abordagem sindrômica estão: classificar os principais\nagentes etiológicos, incluir a atenção dos parceiros e incluir a oferta da sorologia para sífilis,\nhepatites e para o HIV."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-354380","number":"354380","sourceNumber":"354380","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Dois jovens, ela 25 anos e ele 26 anos de idade, tiveram uma relação sexual há 2 dias\ne utilizaram preservativo, porém perceberam que\na camisinha havia estourado durante o ato sexual.\nEla, nuligesta, está preocupada, pois isso nunca havia acontecido e estava no período fértil. A\ngestação nesse momento não seria desejada. Ela é hipertensa desde os 22 anos, bem controlada,\nsem outras comorbidades. Visando a redução de risco de infecção por sífilis, indique a conduta\npara o momento:","options":{"A":"Realizar sorologia para sífilis após duas semanas do coito e, se positiva, tratar com Penicilina\nG\nBenzatina, 1,2 milhões UI, intramuscular, dose única.","B":"Tratar imediatamente com Penicilina G Benzatina, 1,2 milhões UI, intramuscular, em cada\nglúteo, dose única.","C":"Realizar sorologia para sífilis após duas semanas do coito e, se positiva, tratar com Penicilina\nG\nBenzatina, 1,2 milhões UI, intramuscular, uma vez por semana por 3 semanas.","D":"Tratar imediatamente com Penicilina G Benzatina, 1,2 milhões UI, intramuscular, em cada glúteo\ne repetir após uma semana."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-324686","number":"324686","sourceNumber":"324686","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Jovem, de 30 anos de idade, esteve em viagem na Índia há 2 meses. Refere\naparecimento de 2 úlceras na região inguinal\ndireita há 4 semanas. Tais úlceras não são\nacompanhadas de dor local. Relata que, antes das úlceras, apresentou no mesmo local\nnodulações. Não apresenta comorbidades nem possui outras queixas. Ao exame físico, visualizada\na presença de 2 ulcerações em espelho, de borda plana, bem delimitadas e com fundo granuloso\nvermelho vivo e sangramento fácil. Diante do quadro, indique a principal hipótese diagnóstica:","options":{"A":"Cancro mole.","B":"Sífilis.","C":"Lesão herpética.","D":"Donovanose."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-324687","number":"324687","sourceNumber":"324687","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Jovem, de 30 anos de idade, esteve em viagem na Índia há 2 meses. Refere\naparecimento de 2 úlceras na região inguinal\ndireita há 4 semanas. Tais úlceras não são\nacompanhadas de dor local. Relata que, antes das úlceras, apresentou no mesmo local\nnodulações. Não apresenta comorbidades nem possui outras queixas. Ao exame físico, visualizada\na presença de 2 ulcerações em espelho, de borda plana, bem delimitadas e com fundo granuloso\nvermelho vivo e sangramento fácil. Indique o tratamento inicial preconizado para o caso:","options":{"A":"Doxiciclina 100mg, a cada 12 horas por pelo menos 21 dias ou até o desaparecimento das\nlesões.","B":"Azitromicina 2g, via oral, dose única.","C":"Penicilina Benzatina, 2,4 milhões de unidades, intramuscular, dose única.","D":"Aciclovir, 200mg, via oral, a cada 4 horas por 5 dias."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-324688","number":"324688","sourceNumber":"324688","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Jovem, de 30 anos de idade, esteve em viagem na Índia há 2 meses. Refere\naparecimento de 2 úlceras na região inguinal\ndireita há 4 semanas. Tais úlceras não são\nacompanhadas de dor local. Relata que, antes das úlceras, apresentou no mesmo local\nnodulações. Não apresenta comorbidades nem possui outras queixas. Ao exame físico, visualizada\na presença de 2 ulcerações em espelho, de borda plana, bem delimitadas e com fundo granuloso\nvermelho vivo e sangramento fácil. Indique os agentes causadores de úlceras indolores, como as\ndo caso:","options":{"A":"Treponema pallidum, Klebsiella granulomatis, Clamydia trachomatis.","B":"Herpes simplex vírus, Haemophilus ducreyi, Clamydia trachomatis.","C":"Klebsiella granulomatis, Clamydia trachomatis, Herpes simplex vírus.","D":"Treponema pallidum, Klebsiella granulomatis, Haemophilus ducreyi."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-294488","number":"294488","sourceNumber":"294488","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Adolescente, 16 anos de idade, é levada à UPA pela mãe, por ter sido agredida\nfisicamente há, aproximadamente, 3 horas. O\nrelato é de que o padrasto a espancou ao chegar,\nalcoolizado, em casa. O médico observa que a menor está tensa e retraída, limitando-se a\nresponder com a cabeça às suas perguntas, enquanto a genitora relata o quadro que encontrou em\ncasa. Indique a conduta mais correta, nesse momento, tendo sido verificado que houve abuso\nsexual, e diante do risco iminente de gravidez:","options":{"A":"Emitir solicitação de exame no IML.","B":"Prescrever contracepção de urgência.","C":"Encaminhar para avaliação por ginecologista.","D":"Aguardar o Conselho Tutelar para definir conduta."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-284595","number":"284595","sourceNumber":"284595","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 34 anos de idade, gestante de 36 semanas e 2 dias, secundigesta e primípara\n(parto vaginal há 10 anos, fruto de outro\nrelacionamento), está realizando pré-natal em maternidade\nde alto risco por ser paciente HIV positiva. Vem em consulta de pré-natal para trazer resultado de\ncarga viral que realizou com 34 semanas e 2 dias: 1.050 cópias/mL. Carga viral com 30 semanas\nera de 2.000 cópias/mL. Está assintomática, referindo boa movimentação fetal. Ao exame físico:\ncorada e hidratada, altura uterina: 35cm, BCF: 144bpm em QIE, tônus uterino preservado, dinâmica\nuterina ausente. Frente ao quadro, é correto afirmar:","options":{"A":"Como houve redução da carga viral a melhor via de parto nesse caso será a via obstétrica.","B":"A via de parto deverá ser vaginal, de forma humanizada, reduzindo o risco de sangramento ou\nde complicações e, portanto, de transmissão\nvertical.","C":"Como a carga viral está alta após 34 semanas, a via de parto deverá ser cesareana.","D":"A via de parto ainda não pode ser decidida, necessitando de nova carga viral com mais de 37\nsemanas."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-284596","number":"284596","sourceNumber":"284596","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 34 anos de idade, gestante de 36 semanas e 2 dias, secundigesta e primípara\n(parto vaginal há 10 anos, fruto de outro\nrelacionamento), está realizando pré-natal em maternidade\nde alto risco por ser paciente HIV positiva. Vem em consulta de pré-natal para trazer resultado de\ncarga viral que realizou com 34 semanas e 2 dias: 1.050 cópias/mL. Carga viral com 30 semanas\nera de 2.000 cópias/mL. Está assintomática, referindo boa movimentação fetal. Ao exame físico:\ncorada e hidratada, altura uterina: 35cm, BCF: 144bpm em QIE, tônus uterino preservado, dinâmica\nuterina ausente. Indique a alternativa mais adequada, considerando o dia do parto dessa paciente.","options":{"A":"A paciente necessitará de profilaxia de transmissão vertical com Lopinavir + Ritonavir,\nintravenoso, dose única","B":"A paciente necessitará de profilaxia de transmissão vertical com Zidovudina, intravenoso,\ndurante o início do trabalho de parto, ou até\ntrês horas antes da cesariana eletiva, até o\nclampeamento do cordão umbilical.","C":"A paciente necessitará de profilaxia de transmissão vertical com Lopinavir + Ritonavir durante o\ninício do trabalho de parto, ou até três horas antes da cesariana eletiva, até o clampeamento do\ncordão umbilical.","D":"Caso a paciente esteja usando adequadamente a terapia antirretroviral (TARV), não terá\nnecessidade de uso de medicação venosa para profilaxia."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-284601","number":"284601","sourceNumber":"284601","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Menina, 12 anos de idade, vem ao pronto atendimento com dor abdominal tipo cólica e\nnáuseas. Questionada sobre ciclo menstrual, informa que menstruou pela primeira vez há 6 meses\ne que nos últimos 4 meses o ciclo estava regular a cada 28 dias, exceto este mês que está\natrasada há 15 dias. Ao ser novamente questionada sobre sua vida sexual, refere sofrer violência\nsexual de seu vizinho de 25 anos de idade, há 2 anos, e que o mesmo a ameaça para que não\nconte para os pais. Ultimo episódio de violência sexual ocorreu há cerca de 4 semanas e o\npenúltimo há 3 meses. Nega que ele utilize condom. Entre os exames solicitados, o beta HCG está\npositivo. A ultrassonografia, de hoje, evidencia gestação tópica única, com embrião presente\ncompatível com gestação de 6 semanas, BCF: 128bpm. Todas as providências legais e médicas\ncabíveis foram tomadas e houve conversa com os pais da paciente que estão chorosos, assim\ncomo a paciente, pois não desejam a gestação. Com base nos dados do caso, sobre o período da\núltima violência sexual, é correto afirmar:","options":{"A":"não está compatível com a idade gestacional, visto que a gestação está com duração provável\nde 6 semanas e a violência ocorreu há 4\nsemanas.","B":"está compatível com a idade gestacional e o abortamento legal, nesse caso, é permitido se for o\ndesejo da paciente e dos seus pais.","C":"está compatível com a idade gestacional, porém o abortamento legal, nesse caso, não é\npermitido já que trata-se de paciente menor que 18 anos.","D":"não está compatível com a idade gestacional, sendo necessária uma avaliação pelo Instituto\nMédico Legal para decidir o que deve ser feito."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-284602","number":"284602","sourceNumber":"284602","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Menina, 12 anos de idade, vem ao pronto atendimento com dor abdominal tipo cólica e\nnáuseas. Questionada sobre ciclo menstrual, informa que menstruou pela primeira vez há 6 meses\ne que nos últimos 4 meses o ciclo estava regular a cada 28 dias, exceto este mês que está\natrasada há 15 dias. Ao ser novamente questionada sobre sua vida sexual, refere sofrer violência\nsexual de seu vizinho de 25 anos de idade, há 2 anos, e que o mesmo a ameaça para que não\nconte para os pais. Ultimo episódio de violência sexual ocorreu há cerca de 4 semanas e o\npenúltimo há 3 meses. Nega que ele utilize condom. Entre os exames solicitados, o beta HCG está\npositivo. A ultrassonografia, de hoje, evidencia gestação tópica única, com embrião presente\ncompatível com gestação de 6 semanas, BCF: 128bpm. Todas as providências legais e médicas\ncabíveis foram tomadas e houve conversa com os pais da paciente que estão chorosos, assim\ncomo a paciente, pois não desejam a gestação. Considerando a violência sexual, nesse caso, é\ncorreto afirmar:","options":{"A":"Não deve ser realizada profilaxia para prevenção de ISTs nesse momento.","B":"É necessário prescrição de profilaxia para prevenção de HIV, sífilis, hepatite B, clamídia e\ngonococo no momento.","C":"A profilaxia para prevenção de HIV já não pode ser mais ser realizada pelo tempo de ocorrência\ndo evento, mas é possível a profilaxia de\nsífilis, hepatite B, clamídia e gonococo.","D":"A profilaxia para prevenção de HIV e Hepatite B já não pode ser mais ser realizada pelo tempo\nde ocorrência do evento, mas é possível a\nprofilaxia de sífilis, clamídia e gonococo."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-284603","number":"284603","sourceNumber":"284603","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Menina, 12 anos de idade, vem ao pronto atendimento com dor abdominal tipo cólica e\nnáuseas. Questionada sobre ciclo menstrual, informa que menstruou pela primeira vez há 6 meses\ne que nos últimos 4 meses o ciclo estava regular a cada 28 dias, exceto este mês que está\natrasada há 15 dias. Ao ser novamente questionada sobre sua vida sexual, refere sofrer violência\nsexual de seu vizinho de 25 anos de idade, há 2 anos, e que o mesmo a ameaça para que não\nconte para os pais. Ultimo episódio de violência sexual ocorreu há cerca de 4 semanas e o\npenúltimo há 3 meses. Nega que ele utilize condom. Entre os exames solicitados, o beta HCG está\npositivo. A ultrassonografia, de hoje, evidencia gestação tópica única, com embrião presente\ncompatível com gestação de 6 semanas, BCF: 128bpm. Todas as providências legais e médicas\ncabíveis foram tomadas e houve conversa com os pais da paciente que estão chorosos, assim\ncomo a paciente, pois não desejam a gestação. Sobre o abortamento no Brasil, em caso de\nconfirmação de gestação ocasionada por violência sexual, é correto afirmar:","options":{"A":"Pode ser realizado em qualquer momento da gestação, visto ser um direito da mulher que sofreu\na violência sexual.","B":"Não é legalizado no Brasil.","C":"Pode ser realizado por profissional médico capacitado, de forma legalizada, desde que seja\napresentado um boletim de ocorrência informando sobre a violência sexual.","D":"Pode ser realizado até 20ª ou 22ª semana, ou quando o feto pese até 500 gramas, e não\nnecessita de boletim de ocorrência."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62867","number":"62867","sourceNumber":"62867","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, sexo feminino, 23 anos de idade, cursa com dor em fossa ilíaca esquerda e\npélvica, há 10 dias, associada a corrimento vaginal amarelado e fétido. Relata menstruação regular\ne vida sexual ativa. Ao exame, a paciente encontra-se afebril e sem sinais de SRIS. O abdome é\ndoloroso à palpação da região hipogástrica e na fossa ilíaca esquerda, com leve dor à\ndescompressão brusca. Solicitadas ultrassonografias abdominal, pélvica e transvaginal,\nevidenciaram pequena quantidade de líquido livre no fundo de saco posterior. A principal suspeita\ndiagnóstica é:","options":{"A":"apendicite aguda.","B":"colecistite aguda.","C":"diverticulite aguda.","D":"doença inflamatória pélvica.","E":"infecção do trato urinário."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62869","number":"62869","sourceNumber":"62869","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, sexo feminino, 23 anos de idade, cursa com dor em fossa ilíaca esquerda e\npélvica, há 10 dias, associada a corrimento vaginal amarelado e fétido. Relata menstruação regular\ne vida sexual ativa. Ao exame, a paciente encontra-se afebril e sem sinais de SRIS. O abdome é\ndoloroso à palpação da região hipogástrica e na fossa ilíaca esquerda, com leve dor à\ndescompressão brusca. Solicitadas ultrassonografias abdominal, pélvica e transvaginal,\nevidenciaram pequena quantidade de líquido livre no fundo de saco posterior. O tratamento requer:","options":{"A":"apendicetomia laparoscópica.","B":"colecistectomia laparoscópica.","C":"antibioticoterapia guiada para Gram-negativos e anaeróbios.","D":"antibioticoterapia com ceftriaxone, doxiciclina e metronidazol.","E":"antibioticoterapia com sulfametoxazol + trimetropim."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62871","number":"62871","sourceNumber":"62871","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, sexo feminino, 23 anos de idade, cursa com dor em fossa ilíaca esquerda e\npélvica, há 10 dias, associada a corrimento vaginal amarelado e fétido. Relata menstruação regular\ne vida sexual ativa. Ao exame, a paciente encontra-se afebril e sem sinais de SRIS. O abdome é\ndoloroso à palpação da região hipogástrica e na fossa ilíaca esquerda, com leve dor à\ndescompressão brusca. Solicitadas ultrassonografias abdominal, pélvica e transvaginal,\nevidenciaram pequena quantidade de líquido livre no fundo de saco posterior. Após 24 horas, a\npaciente evoluiu com dor intensa no hipocôndrio direito. Manteve-se sem sinais de SRIS. À\npalpação abdominal observa dor à palpação do andar superior direito do abdome, com leve\ndesconforto à descompressão brusca. Transaminases eram normais. O diagnóstico mais provável\né:","options":{"A":"hepatite transinfecciosa.","B":"hepatite medicamentosa.","C":"colecistite aguda alitiásica.","D":"peri-hepatite.","E":"pneumonia da base pulmonar direita."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62811","number":"62811","sourceNumber":"62811","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 25 anos de idade, apresenta queixa de fluxo genital acinzentado, com odor\nfétido tipo \"peixe podre\". Esse quadro está associado a:","options":{"A":"câncer de colo uterino.","B":"câncer de endométrio.","C":"doença inflamatória pélvica aguda.","D":"endometriose.","E":"síndrome dos ovários policísticos."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62824","number":"62824","sourceNumber":"62824","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica Aguda (DIPA) apresenta como agentes etiológicos\nprincipais o gonococo e a clamídia. De acordo\ncom o CDC 2010, o tratamento ambulatorial de\nescolha é:","options":{"A":"ceftriaxone 250 mg, dose única + doxiciclina 100 mg, 12/12h, por 14 dias.","B":"ofloxacino 400 mg, 12/12h por 7 dias + azitromicina 1 g, dose única.","C":"ceftriaxone 125 mg, dose única + doxiciclina 100 mg, 12/12h, por 14 dias.","D":"ofloxacino 400 mg, dose única + azitromicina 1 g, dose única.","E":"ceftriaxone 125 mg, dose única + doxiciclina 100 mg, 12/12h, por 7 dias."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62833","number":"62833","sourceNumber":"62833","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 30 anos de idade, assintomática, com histórico de múltiplos parceiros,\napresenta VDRL = 1/256 e FTA-Abs reagente. Ao\nexame clínico, não se observam úlceras genitais\nou outros achados. Refere história de sífilis, há três anos. O tratamento é prescrever:","options":{"A":"cefalexina 500 mg, 6/6h, 7 dias.","B":"penicilina benzatina 2.400.000 UI, 2 doses.","C":"penicilina benzatina 2.400.000 UI, 3 doses.","D":"penicilina benzatina 4.000.000 UI, dose única.","E":"azitromicina 1 g, dose única."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-62828","number":"62828","sourceNumber":"62828","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 40 semanas de gestação, não fez pré-natal, dá entrada na maternidade em\ntrabalho de parto avançado, colo com 8 cm de dilatação e com bolsa rota há seis horas. Realizou\nteste rápido para HIV e o resultado foi positivo. A conduta, em relação à gestante, para diminuir a\ntaxa de transmissão vertical, com base nas recomendações do Ministério da Saúde, é","options":{"A":"indicar AZT injetável e realizar parto vaginal.","B":"indicar cesariana imediatamente, apenas.","C":"indicar AZT injetável e realizar cesariana imediatamente.","D":"indicar AZT oral e realizar parto vaginal.","E":"realizar parto vaginal, apenas."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-49398","number":"49398","sourceNumber":"49398","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 25 anos de idade, apresenta fluxo vaginal verde-amarelado, bolhoso e com\nodor fético. Apresenta colpite focal colposcopia. Diante desse quadro, o tratamento indicado, de\nacordo com o CDC, 2006, é:","options":{"A":"metronidazol gel 0,75%, uso vaginal, por 7 noites, e tratar o parceiro.","B":"clindamicina 300 mg, via oral, a cada 12 horas, por 7 dias, e não tratar o parceiro.","C":"metronidazol 2 g, via oral, dose única, e não tratar o parceiro.","D":"metronidazol gel 0,75%, uso vaginal, por 7 noites, e não tratar o parceiro.","E":"metronidazol 2 g, via oral, dose única, e tratar o parceiro."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-49415","number":"49415","sourceNumber":"49415","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 27 anos de idade, com quadro de dor pélvica aguda e febre, temperatura\naxilar de 38°C. Ao exame físico, dor a\nmobilização do colo uterino e à palpação dos anexos. O\ntratamento para esse quadro, segundo CDC, 2006, é:","options":{"A":"ceftriaxone 250 mg, intramuscular, dose única, + doxiciclina 100 mg via oral, a cada 12 horas,\npor 14 dias, + metronidazol 500 mg via oral,\na cada 12 horas, por 14 dias.","B":"penicilina benzatina 2.400 000 UI, intramuscular, dose única.","C":"cindamicina 900 mg, endovenoso, a cada 8 horas, + gentamicina 240 mg, endovenoso, dose\núnica.","D":"abordagem cirúrgica.","E":"ciprofloxacino 500 mg, via oral, dose única + azitromicina 1 g, via oral, dose única."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-358783","number":"358783","sourceNumber":"358783","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Laura, 29 anos, buscou atendimento na USF devido a quadro de dor pélvica associado\na episódios de febre (38º). Refere corrimento\nvaginal amarelado. Nega prurido vaginal. Refere ter\nmenstruado há 20 dias. Não tem história prévia de alergias. Refere apenas um parceiro sexual fixo\ne não realiza uso de preservativo. Nega comorbidades. Refere ter realizado citopatológico de colo\nuterino há 11 meses e com resultado normal. Ao exame físico, apresenta dor a palpação em\nhipogástrio. No exame ginecológico, apresenta fluxo cervical mucopurulento, colo friável e doloroso\nao toque, útero doloroso à mobilização, anexos com dor. Com essas informações, qual deve ser a\nsua conduta, enquanto MFC?","options":{"A":"Estabelecer diagnóstico provável de doença inflamatória pélvica, propor o tratamento\nconveniado, tratar o parceiro e oferecer testes rápido para ISTs.","B":"Realizar a coleta do material para exame citopatológico e aguardar o resultado para definir o\ndiagnóstico e a terapêutica.","C":"Propor tratamento com ampla cobertura, podendo ser prescrito metronidazol 500 mg, de 12/12h,\nVO, por 7 dias ou Metronidazol gel vaginal\n100 mg/g, 1 aplicação à noite, por 5 dias e oferecer\ntratamento ao parceiro.","D":"Propor tratamento para vaginose bacteriana, não sendo necessário tratar o parceiro já que não\nse trata de uma IST.","E":"Estabelecer diagnóstico provável de doença inflamatória pélvica, solicitar USG transvaginal para\nconfirmar o diagnóstico, e só assim indicar o tratamento."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-332616","number":"332616","sourceNumber":"332616","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"J.J, 2 anos, sexo feminino, é levada pela mãe ao médico de família, apresentando\nlesões verrucosas em região perineal e corrimento\npurulento. A criança vive com os pais. Durante\nas manhãs fica sob os cuidados da avó materna. A conduta neste caso é:","options":{"A":"realizar a notificação de caso suspeito de violência.","B":"aguardar resultado de exame pericial confirmatório para realizar a notificação.","C":"realizar coleta de biópsia para confirmação diagnóstica e, posteriormente, realizar a\nnotificação.","D":"encaminhar a criança para atenção secundária para nesse nível ser realizada a notificação.","E":"acionar o conselho tutelar para que o representante realize a notificação"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343367","number":"343367","sourceNumber":"343367","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação à Doença Inflamatória Pélvica Aguda, assinale a alternativa incorreta.","options":{"A":"O uso de preservativo pode prevenir a transmissão.","B":"O espermatozoide pode funcionar como carreador do patógeno.","C":"Atualmente se sabe que o agente etiológico mais comum é o micoplasma.","D":"As duchas vaginais podem facilitar a ascensão de microrganismos causadores de DIPA."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-283856","number":"283856","sourceNumber":"283856","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Menina de 15 anos, vítima de estupro há 13 horas é atendida por você na unidade de\nsaúde. Foi agredida e refere que ocorreu coito vaginal. Nega comorbidades ou uso de medicações\nno momento. Menarca aos 14 anos e última menstruação há 10 dias. Considerando esse caso\nclínico, é correto afirmar que","options":{"A":"não há necessidade de contracepção de emergência.","B":"no primeiro atendimento deve ser realizada a coleta de material vaginal e anal com swab.","C":"como o estrupo ocorreu há mais de 12 horas, não está mais indicado o uso de profilaxia para\nHIV.","D":"antes do atendimento médico, é importante a realização do boletim de ocorrência e o exame de\ncorpo delito.","E":"inicialmente, a paciente será encaminhada para o Instituto Médico Legal para perícia e,\nposteriormente, para o atendimento médico hospitalar."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-281890","number":"281890","sourceNumber":"281890","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher de 19 anos procura ginecologista com queixa de febre e dor importante em\nregião perineal. Ao exame físico, apresenta temperatura axilar de 38,7°C e lesões vulvares\nvesiculosas. O mais provável diagnóstico é:","options":{"A":"Doenca inflamatória pélvica.","B":"Linfogranuloma venéreo.","C":"Primeira infecção por herpes.","D":"Sífilis."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-281899","number":"281899","sourceNumber":"281899","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Os testes não treponêmicos mais comumente utilizados no Brasil são o VDRL (do\ninglês Venereal Disease Research Laboratory), o\nRPR (do inglês Rapid Plasma Reagin) e o USR\n(do Unheated-Serum Reagin). Sendo correto o item:","options":{"A":"Resultados falso-reagentes, ainda comuns, podem ocorrer.","B":"Resultados falso-reagentes, ainda que raros, não podem ocorrer.","C":"Resultados falso-reagentes, nunca ocorrem.","D":"Resultados falso-reagentes, ainda que raros, podem ocorrer."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-281901","number":"281901","sourceNumber":"281901","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Os testes não treponêmicos são testes que detectam anticorpos de acordo com o item:","options":{"A":"Anticardiolipina não específicos para os antígenos do T. Pallidum, permitem a análise qualitativa\ne quantitativa.","B":"Anticardiolipina específicos para os antígenos do T. Pallidum, permitem a análise qualitativa e\nquantitativa.","C":"Anti cardiolipina não específicos para os antígenos do T. Pallidum, permitem a análise\nqualitativa\ne não quantitativa.","D":"Anticardiolipina não específicos para os antígenos do T. Pallidum, mas não permitem a análise\nqualitativa e quantitativa."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-281903","number":"281903","sourceNumber":"281903","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Testes treponêmicos para a sífilis são em 85% dos casos, reagentes por toda vida,\nsendo adequado o item:","options":{"A":"Mesmo após o tratamento e, por isso, são indicados para o monitoramento da resposta ao\ntratamento.","B":"Mesmo após o tratamento e, por isso, não são indicados para o monitoramento da resposta ao\ntratamento.","C":"Mesmo antes do tratamento e, por isso, não são indicados para o monitoramento da resposta ao\ntratamento.","D":"Mesmo após o tratamento e, por isso, são os mais bem indicados para o monitoramento da\nresposta ao tratamento."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250008","number":"250008","sourceNumber":"250008","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente com queixa de prurido vulvar apresenta exame de papanicolaou cujo\nlaudo demonstra a presença de hifas. A melhor conduta nesse caso deve ser:","options":{"A":"somente orientar a realizar banho de assento com bicarbonato.","B":"tratar como vaginose bacteriana.","C":"tratar como candidíase.","D":"tratar somente com metronidazol via oral."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250013","number":"250013","sourceNumber":"250013","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher procura ginecologista referindo que logo após relação sexual, surgiu forte odor\ndesagradável em região vulvo-vaginal. O agente etiológico provavelmente envolvido é:","options":{"A":"Gonococo.","B":"Tricomonas.","C":"Gardnerela.","D":"Candida."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-218168","number":"218168","sourceNumber":"218168","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"\"Em 26 de agosto de 2014, Jandira Magdalena dos Santos Cruz morreu ao realizar um\naborto numa clínica clandestina no Rio de Janeiro. Seu corpo foi encontrado mutilado e\ncarbonizado no dia seguinte [...]. Segundo a Pesquisa Nacional do Aborto, do Anis - Instituto de\nBioética, estima-se que, só no ano seguinte da morte de Jandira, 416 mil mulheres abortaram na\nilegalidade [...]. Para a antropóloga responsável pela Pesquisa Nacional do Aborto, Débora Diniz,\nessas mortes são sintomas de uma violação de direitos humanos que acontece no Brasil. A\ncriminalização do aborto é uma grave violação de direitos humanos, com consequências para a\nsaúde pública e a saúde da mulher. Ela viola direitos fundamentais, como a dignidade, a liberdade\ne a autonomia. Somente sendo livre para escolher quando e como ter filhos, a mulher pode ter uma\nvida digna, segundo a especialista [...]. Descriminalizar o aborto não desprotege a crença de\nninguém. As pessoas que acham que o aborto não deve ser feito vão poder passar a vida sem\nfazer um?. Disponível em\n\n<https://www.uol/estilo/especiais/vitima-do-aborto-ilegal.htm#vitima-do-aborto-ilegal>. Acesso em:\n08 jan. 2019. Tendo como referência as\nnormas e os manuais técnicos do Ministério da Saúde, e a\nlegislação específica sobre o abortamento, é CORRETO afirmar que:","options":{"A":"As orientações, após interrupção da gravidez, devem começar por informar que a recuperação\nda fertilidade pode demorar cerca de seis semanas\napós o abortamento, e que, por conseguinte, a\nanticoncepção deve iniciar após um mês do procedimento.","B":"O correto a ser feito em relação à Jandira seria, de acordo com o Código Penal, comunicar o fato\nà autoridade policial, judicial e/ou ao\nMinistério Público, pois a quebra de sigilo na prática\nprofissional da assistência à saúde, neste caso, está autorizada por ser crime.","C":"Caso a gravidez de Jandira tenha sido em decorrência de uma relação sexual não consentida\ncom o marido dela, e ela dê entrada no seu\nplantão (no qual você será o único médico nas\npróximas 48h), você pode alegar objeção de consciência e não realizar o abortamento.","D":"Após a interrupção da gravidez, a mulher deve ser orientada quanto aos sinais normais de\nrecuperação e sobre as complicações, além da escolha contraceptiva no momento\n\npós-abortamento, informando, inclusive, sobre a contracepção de emergência.","E":"O Código Penal exige exame de corpo de delito para a prática do abortamento em caso de\nviolência sexual. Assim, a mulher deve ser orientada a tomar as providências policiais e judiciais\ncabíveis, porque, caso ela não o faça, pode ser negado o procedimento de abortamento."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-218181","number":"218181","sourceNumber":"218181","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg,\npesa 78 kg, mede 1,60 m de altura (IMC 30,5). Maria Aparecida retorna para a primeira consulta de\npré-natal acompanhada de Valdomiro. Ela está mais tranquila, aceitando bem a gestação e se\nmostra bastante feliz e participando ativamente, segundo as falas de ambos. Mário, antes da\nconsulta, trouxe para Daiane o resultado do teste rápido de Sífilis: positivo. Considerando o caso\nclínico 01 e a melhor conduta a ser adotada por Daiane, analise as assertivas e identifique com V\nas verdadeiras e com F as falsas. ( ) O tratamento para Maria Aparecida deve ser Penincilina G\nBenzatina (2,4 milhões UI), IM, dose única (1,2 milhão UI em cada glúteo) e, alternativamente,\nDoxiciclina 100 mg, VO, 2xdia, por 15 dias. ( ) Deve-se realizar o teste imunológico em Valdomiro e\nseu tratamento deve ser no esquema da sífilis latente tardia, quando o resultado for positivo e não\nfor possível estabelecer a data da infecção. ( ) A recomendação geral é coletar o sangue para\nrealização do VDRL imediatamente para confirmação do diagnóstico, e agenda o retorno em até\numa semana para, com o resultado, iniciar o tratamento. ( ) A recomendação geral é iniciar o\ntratamento imediatamente com Penincilina Benzatina, fazendo a primeira dose, coletar sangue para\n\na realização do VDRL e agendar retorno com resultado para sete dias. Se positivo, completar o\ntratamento, se for o caso, de acordo com o diagnóstico do tipo de sífilis. ( ) Nos casos específicos\nnos quais se tem qualquer dúvida sobre o contato, vínculo e sequência do seguimento e tratamento\ndo caso, ou não se tenha disponibilidade (realização e resultado) do VDRL, em tempo oportuno, ou\na pessoa estiver em uma condição muito sensível, como é o caso de Maria Aparecida por ser\ngestante, permite-se excluir do fluxograma a necessidade de realização do VDRL e reforça-se a\nrecomendação do tratamento imediato. Isso vale também para as parcerias sexuais. A alternativa\nque contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"V, F, V, F, F.","B":"V, F, F, V, F.","C":"F, V, F, V, V.","D":"F, V, V, F, F.","E":"F, V, V, F, V."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215609","number":"215609","sourceNumber":"215609","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em caso de mãe contaminada com Neisseria, o principal risco para o lactente é\ndesenvolver:","options":{"A":"Meningite e endocardite.","B":"Endocardite e hepatite.","C":"Meningite e hepatite.","D":"Conjuntivite e pneumonia."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-215598","number":"215598","sourceNumber":"215598","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em pacientes com suspeita de sífilis, o exame de VDRL quantitativo deve ser realizado\nem diluição mínima de 1/16 para evitar resultado\nfalso negativo que pode ser ocasionado pelo\nexcesso de anticorpos e formação de imunocomplexos. A esse fenômeno dá-se o nome de:","options":{"A":"Síndrome de Stein.","B":"Pró-zona.","C":"Sífilis decapitada.","D":"Reação de Jarisch-Herxheimer."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-181191","number":"181191","sourceNumber":"181191","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Não faz parte do quadro de Doença inflamatória Pélvica:","options":{"A":"Endometrite.","B":"Salpingite.","C":"Vaginite.","D":"Pelviperitonite."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-162481","number":"162481","sourceNumber":"162481","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Eliana chega à Unidade de Saúde da Família de Nova Aliança e acessa a médica de\nfamília, Dra. Mariana via acolhimento. Vem relatando quadro de secreção vaginal esbranquiçada\ncom prurido vulvar intenso, dispareunia e edema de vulva. A melhor conduta a ser realizada por\nDra. Mariana para manejo desse caso é","options":{"A":"encaminhá-la para um ginecologista para que se possa realizar uma abordagem diagnóstica e\nterapêutica adequada.","B":"por não se tratar de uma Doença Sexualmente Transmissível (DST), é desnecessário realizar\norientações quanto à higiene e questões relacionadas à sexualidade.","C":"realizar anamnese, exame físico e exame macroscópico do fluxo vaginal para realizar\ndiagnóstico presuntivo de um agente etiológico.","D":"pelo relato do acolhimento, presume-se se tratar de candidíase vaginal devendo-se orientá-la\nque não se trata de uma Doença Sexualmente\nTransmissível (DST).","E":"na escolha do tratamento, Dra. Mariana deve preferir a prescrição de medicação via oral\nassociada à medicação intravaginal com\nMetronidazol gel, pois esta combinação demonstrou ser\nmais eficaz no tratamento das vulvovaginites."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-157586","number":"157586","sourceNumber":"157586","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação à Vulvovaginite por Trichomonas vaginallis, podemos afirmar que:","options":{"A":"É considerada uma Doença Sexualmente Transmissível (DST).","B":"É de difícil confirmação diagnóstica.","C":"Pode ser tratada com nistatina tópica.","D":"É uma bactéria que faz parte da flora normal da vagina."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-162501","number":"162501","sourceNumber":"162501","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Cíntia, 25 anos, primigesta, na 27ª semana de gestação, vem à consulta relatando\ncorrimento vaginal branco, grumoso, que coça\nmuito, mas sem odor. Está incomodada por causar\nvergonha quando tem relação sexual com seu companheiro. Anderson, seu parceiro, veio para a\nconsulta com Cíntia e afirma não ter sintomas. A melhor conduta, nesse caso, é:","options":{"A":"Não tratar, visto que a leucorreia apresenta características fisiológicas.","B":"Tratar a candidíase da gestante com medicamento oral e afirmar que sua queixa será resolvida.","C":"Tratar a candidíase da gestante com medicamentos tópicos e, com medicamentos orais, o\nparceiro e afirmar que sua queixa será resolvida.","D":"Tratar a candidíase da gestante com medicamentos tópicos na gestante, podendo ser miconazol\na 2%, creme vaginal (por sete dias), que é\numa das opções de tratamento.","E":"Tratar a tricomoníase com medicamentos via oral na gestante, podendo ser metronidazol, 2 g\n(em dose única), que é uma das opções de tratamento para Cíntia."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-157641","number":"157641","sourceNumber":"157641","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação ao pré-natal, NÃO é correto afirmar que","options":{"A":"a ultrassonografia entre 11 e 13 semanas pode avaliar a medida da translucência nucal e osso\nnasal como fatores preditivos de trissomias.","B":"deve ser oferecida a sorologia para HIV a todas as gestantes, independentemente da idade\ngestacional em que se encontram.","C":"em caso de gestante com VDRL positivo e alérgica à penicilina, pode-se utilizar eritromicina com\na mesma eficácia do ponto de vista materno e\nfetal.","D":"glicemia em jejum acima de 90 mg/dl faz suspeitar de diabete gestacional, necessitando de\nexame confirmatório."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-139750","number":"139750","sourceNumber":"139750","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente em trabalho de parto, portadora de herpes genital, apresenta lesão de\nrecidiva. Indique a opção que apresenta, para esse caso, a MELHOR conduta.","options":{"A":"Tratar a mãe com acyclovir intravenoso.","B":"Tratar o recém-nascido com acyclovir intravenoso.","C":"Indicar cesariana.","D":"Permitir parto vaginal e observar o recém-nascido."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134746","number":"134746","sourceNumber":"134746","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 30 anos relata corrimento branco sem odor, com prurido vulvar intenso e\nardor vaginal às relações sexuais, refere ciclos menstruais regulares, refere uso de\nanticoncepcional oral há 8 anos. Fez exame de Papanicolaou há 8 meses, que deu normal. Qual é\na MELHOR conduta para esse caso?","options":{"A":"Colher novo exame de Papanicolaou.","B":"Prescrever antifúngico oral e vaginal.","C":"Prescrever anti-inflamatório e antibiótico.","D":"Prescrever derivado imidazólico oral e vaginal."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134764","number":"134764","sourceNumber":"134764","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Vaginose bacteriana, uma das principais e mais frequentes infecções vaginais\n(Vulvovaginites), pode ser causada pelos seguintes agentes abaixo, EXCETO:","options":{"A":"Mobiluncus sp.","B":"Gardnerella vaginallis.","C":"Neisseria ghonorreae.","D":"Peptoestreptococos."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134677","number":"134677","sourceNumber":"134677","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Ao abordar uma DST na atenção básica, devemos considerar:","options":{"A":"A presença de corrimento amarelado e de cheiro forte numa menina de cinco anos, que pode\nser comum, não exigindo maiores investigações.","B":"A abordagem que deve incluir anamnese, educação, aconselhamento e identificação dos casos\ne contatos, sintomáticos ou não.","C":"Que não é necessário, numa primeira abordagem aos jovens, focalizar a AIDS ao se fazer a\nprevenção porque as relações ainda são esporádicas.","D":"Que, no exame físico basta focalizar no aparelho genital, pois as DSTs se manifestam\nprincipalmente nessa área."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-111909","number":"111909","sourceNumber":"111909","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Relacione os casos clínicos e os exames solicitados e, em seguida, assinale a\nalternativa contendo a sequência CORRETA. Casos\nclínicos: I. Mulher de 32 anos com história de\naparecimento de múltiplas vesículas genitais dolorosas há 7 dias. Ao exame está com temperatura\nde 37,8 graus Celsius, apresenta lesões pequenas, superficiais, dolorosas, algumas ulceradas, nos\npequenos e grandes lábios e linfadenomegalia inguinal dolorosa bilateral; II. Mulher de 26 anos\ncom 10 dias de história de úlcera genital, única e indolor de 10 mm, firme a palpação, com borda\nelevada e base não necrótica; III. Mulher de 24 anos com história de 2 dias de aparecimento de 3\núlceras profundas e discretamente dolorosas no períneo e grande lábio esquerdo associadas à\nlinfadenomegalia inguinal homolateral dolorosa. Testes: a. Exame de lesão em campo escuro; b.\n\nBacterioscopia de lesão; c. Pesquisa de células de inclusão viral; d. Sorologia para Sífilis.","options":{"A":"I-c / II-a / III-b.","B":"I-d / II-b / III-a.","C":"I-d / II-a / III-c.","D":"I-c / II-d / III-a."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-111874","number":"111874","sourceNumber":"111874","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São sequelas importantes da Doença Inflamatória Pélvica, EXCETO:","options":{"A":"infertilidade.","B":"metrorragia.","C":"aderências.","D":"prenhez ectópica."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-111887","number":"111887","sourceNumber":"111887","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma gestante com 30 semanas chega à unidade básica para iniciar o seguimento\npré-natal. Dos resultados das provas\nlaboratoriais solicitadas, é recebido teste não treponêmico ?\nVDRL = 1/16. Com esse resultado, quais ações devem ser realizadas pela equipe?","options":{"A":"Convocação da gestante para coleta de amostra sanguínea para realização de teste\ntreponêmico para a confirmação do diagnóstico.","B":"Convocação da gestante para tratamento com penicilina benzatina, notificação do caso e\nconvocação do parceiro sexual.","C":"Aguardar a consulta de retorno para o tratamento da gestante e do parceiro sexual com\npenicilina benzatina, notificar o caso.","D":"Convocar gestante e parceiro sexual, que deverão ser tratados com eritromicina. A notificação\ndo caso é compulsória."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-350887","number":"350887","sourceNumber":"350887","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Homem de 25 anos procura atendimento médico com queixa de rash maculopapular\ndifuso e simétrico, envolvendo tronco e\nmembros, incluindo região palmoplantar acompanhado de\nfebre e adenomegalia generalizada simétrica. Qual dos testes abaixo está mais indicado para\nconfirmação diagnóstica para o caso acima?","options":{"A":"Anti-HIV 1 e 2.","B":"FTA -Abs + VDRL.","C":"Anticorpos heterofilos.","D":"Parvovírus B19 IgM e IgG."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-350827","number":"350827","sourceNumber":"350827","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Adriele, de 19 anos, vem para atendimento em seu horário de demanda espontânea.\nMuito abalada e chorosa, ela refere ter sofrido\nviolência sexual por parte do ex-companheiro, de\nquem se separou durante gestação. Refere que o episódio aconteceu há um dia. É puérpera, com\nlactente de dois meses. Sua caderneta de acompanhamento mostra estado vacinal completo e\natualizado, além de sorologias para ISTs negativas. Está em uso de suplementação de ferro e com\nanticoncepcional com progestágeno isolado. Assinale a alternativa correta em relação à notificação\nde violência nesse caso.","options":{"A":"A notificação é compulsória e deve ser feita após a apresentação do Boletim de Ocorrência\n(B.O) pela paciente.","B":"A notificação pela equipe de saúde é de caráter compulsório para as autoridades sanitárias.\n\nCaso a paciente autorize, a equipe também pode notificar autoridades policiais.","C":"A notificação deve ser realizada somente após autorização da paciente, com cautela por parte\nda equipe de saúde para não colocar a paciente\nem risco.","D":"A notificação pela equipe de saúde é de caráter compulsório, sendo obrigada a notificação para\nautoridades policiais em até 24 horas."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-350848","number":"350848","sourceNumber":"350848","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Adriele, de 19 anos, vem para atendimento em seu horário de demanda espontânea.\nMuito abalada e chorosa, ela refere ter sofrido\nviolência sexual por parte do ex-companheiro, de\nquem se separou durante gestação. Refere que o episódio aconteceu há um dia e não foi usada\ncamisinha. É puérpera, com lactente de 60 dias de vida. Sua caderneta de acompanhamento\nmostra estado vacinal completo e atualizado, além de sorologias para ISTs negativas. Está em uso\nde suplementação de ferro e com anticoncepcional com progestágeno isolado. Assinale a\nalternativa correta em relação à quimioprofilaxia de ISTs não-virais no caso.","options":{"A":"Está indicada a quimioprofilaxia com Ceftriaxona e Azitromicina para gonorreia e clamídia. Está\nindicada a quimioprofilaxia com Penicilina benzatina para sífilis.","B":"Não é necessária a quimioprofilaxia, tendo em vista que paciente e parceiro possuem sorologias\nnegativas, conforme registrado em caderneta de acompanhamento durante a gestação.","C":"Não é necessária a quimioprofilaxia, tendo em vista que estado sorológico de agressor é\nconhecido, pois o mesmo é ex-companheiro de\nAdriele, que apresentou sorologias negativas para\nISTs durante toda a gestação.","D":"Está indicada a quimioprofilaxia com Ceftriaxona e Azitromicina para gonorreia, clamídia e\ncancro mole. Não está indicada a\nquimioprofilaxia com Penicilina benzatina para sífilis, tendo em\nvista sorologia negativa durante a gestação."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-350844","number":"350844","sourceNumber":"350844","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"João, um homem trans hetero de 23 anos, casado com Maria, uma mulher cis hetero,\nchega ao seu plantão, relatando ter sido\nvítima de violência sexual por dois homens desconhecidos\nhá cerca de 2 horas. João faz uso de testosterona há 3 anos, e por conta disso, encontra-se em\namenorreia há mais de 2 anos. Sobre o atendimento a pessoas vítimas de violência sexual.","options":{"A":"Deve-se orientar o paciente a realizar primeiro o boletim de ocorrência (B.O.), para que, em caso\nde gravidez, a interrupção de gestação possa\nser realizada. Somente após o B.O. é que deve ser\nrealizado o atendimento médico.","B":"Em caso de gravidez e desejo de interrupção por parte do paciente: a objeção de consciência\npara a realização da interrupção legal da\ngravidez é um direito individual do médico e também\ninstitucional, e cabe à direção do hospital prover um outro hospital para esse atendimento.","C":"Como o paciente encontra-se em uso de testosterona e em amenorreia há muito tempo, será\nnecessário apenas as profilaxias para as Infecções sexualmente transmissíveis.","D":"Em caso de gravidez, o paciente deve ser informado do direito à possibilidade de interrupção da\ngravidez, do direito e da possibilidade de manter a gestação até o seu término, garantindo-se os\ncuidados pré-natais, além de receber informações completas e precisas sobre as alternativas após\no nascimento, que incluem a escolha entre permanecer com a futura criança e inseri-la na família,\nou proceder com os mecanismos legais de doação."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-350839","number":"350839","sourceNumber":"350839","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Primigesta de 35 semanas, acompanhada no pré-natal de alto risco por HIV, admitida\nna maternidade com diagnóstico confirmado pelo\nexame especular de rotura anteparto de\nmembranas ovulares há 1 hora. Paciente refere boa adesão ao uso de terapia antirretroviral (TARV)\noral e traz carga viral de HIV indetectável coletada no segundo trimestre. Frequência cardíaca fetal\nde 144 batimentos/min. Atividade uterina ausente. Apresentação fetal cefálica. Colo encontra-se\nposterior e sem dilatação visível ao exame especular. A conduta adequada é:","options":{"A":"Manter TARV oral e realizar cesárea imediata.","B":"Iniciar zidovudina (AZT) endovenosa e realizar cesárea após 3 horas.","C":"Iniciar zidovudina (AZT) endovenosa e induzir parto vaginal com ocitocina ou misoprostol.","D":"Iniciar terapia antibiótica e aguardar 37 semanas de idade gestacional ou início de trabalho de\nparto espontâneo."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-321310","number":"321310","sourceNumber":"321310","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Homem, de 43 anos, procurou UBS por lesões papulosas descamativas em tronco e\nextremidades com acometimento palmo-plantar, de início há 5 dias. Investigação revelou VDRL\nreagente 1:16. Foi realizado o tratamento com penicilina benzatina intramuscular. Porém, paciente\nprocurou novamente UBS, após 48 horas por cefaleia occipital, irritabilidade e agressividade. Diante\ndo quadro clínico, a conduta terapêutica mais adequada, dentre as opções abaixo é:","options":{"A":"Associar benzodiazepínico devido a reação à penicilina e manter antibiótico atual.","B":"Executar punção lombar e trocar tratamento por penicilina cristalina intravenosa por possível\nneurossífilis.","C":"Realizar punção lombar e trocar antibiótico por ceftriaxona por suspeita de meningoencefalite\nmeningocócica.","D":"Iniciar corticoide oral devido suspeita de reação do tipo Jarisch-Herxheimer e manter tratamento\ncom penicilina benzatina intramuscular."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-321367","number":"321367","sourceNumber":"321367","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Lidia, mulher cis de 24 anos, G1P1, comparece à emergência da maternidade em que\nvocê está de plantão com história de\nconjunção carnal não autorizada ocorrida há mais ou menos\n3h. A mesma tem enxaqueca e história de trombose venosa profunda em gestação anterior há 2\nanos. Considerando o acolhimento e as profilaxias necessárias às vítimas de violência sexual,\nassinale a alternativa CORRETA.","options":{"A":"A paciente deve primeiro realizar um boletim de ocorrência antes do atendimento médico para\nque não se percam vestígios da violência.","B":"O método de primeira escolha para a anticoncepção de emergência, consiste no uso exclusivo\nde um progestágeno, o levonorgestrel.","C":"O método de escolha para a profilaxia de gravidez a ser ofertado a essa paciente seria um DIU\nde cobre, visto história prévia de trombose venosa profunda.","D":"Realizar notificação obrigatória, anticoncepção de emergência, profilaxias para sífilis,\nhepatites B\ne C, HIV, tricomoníase, clamídia,\ngonorreia, cancro mole e tétano."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-321373","number":"321373","sourceNumber":"321373","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"DSS, 19 anos, G0P0, início da vida sexual aos 16 anos, usando contraceptivo oral,\ncomparece ao ambulatório na UBS, apresentando em região vulvar esquerda, ulceração isolada,\nfirme ao toque, com bordas arredondadas e levemente elevadas, com sinais de infecção\nsecundária e pouco dolorosa. Linfadenopatias inguinais ausente. Nega febre. Sobre o quadro\nacima, é correto afirmar que o diagnóstico mais provável é:","options":{"A":"herpes genital, por se tratar de úlcera dolorosa.","B":"cancroide e o melhor tratamento seria azitromicina em dose única.","C":"sífilis e o melhor tratamento seria penicilina benzatina em dose única.","D":"sífilis e o teste mais adequado para confirmação diagnóstica nesse estágio seria o VDRL."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-321375","number":"321375","sourceNumber":"321375","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, de 25 anos, comparece ao serviço de emergência com quadro de calafrios e\ndor pélvica moderada há 48 horas com piora nas últimas 12 horas. Relata corrimento amarelado\nabundante há cerca de uma semana. Encontra-se menstruada há 3 dias. Usuária de dispositivo\nintrauterino (DIU) T de Cobre há dois anos. Ao exame, bom estado geral, afebril, normocorada.\nExame especular: conteúdo amarelado espesso fluindo pelo orifício do colo uterino. Fio do DIU\nvisível. Ao toque vaginal, apresentou dor hipogástrica, à mobilização do colo e à palpação dos\nanexos. Qual a melhor conduta para o quadro?","options":{"A":"Retirada do DIU e internação para esquema antibiótico com ceftriaxona IV por 14 dias +\ndoxiciclinaa VO por 14 dias + metronidazol IV por 14 dias.","B":"Retirada do DIU, seguida de início imediato de esquema antibiótico com ceftriaxona IM dose\núnica, + doxiciclina VO por 14 dias + metronidazol VO por 14 dias.","C":"Antibioticoterapia com ceftriaxona IM dose única + doxiciclina VO por 14 dias + metronidazol VO\npor 14 dias, seguida de reavaliação clínica após 48 a 72 horas de seu início.","D":"Antibioticoterapia com ceftriaxona IV por 14 dias + doxiciclina VO por 14 dias + metronidazol IV\npor 14 dias, além de internação para retirada do DIU após pelo menos duas doses do esquema."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-292858","number":"292858","sourceNumber":"292858","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em uma de suas consultas com Edmilson, ele pergunta se pode conversar sobre outro\nproblema. Considerando o cuidado integral, você explora essa nova demanda. Edmilson relata que\nnamora Iraneide há três meses, e estava tudo bem, porém sua ex-namorada o procurou há 1\nsemana, e ele acabou se relacionando sexualmente com a mesma. Desde então, evoluiu com\ncorrimento uretral. Relata ainda que nesse período, não teve relação sexual com Iraneide. Você\norienta quanto ao diagnóstico e riscos e Edmilson indaga sobre o tratamento. Assinale a alternativa\ncom a opção terapêutica adequada.","options":{"A":"Aciclovir 200mg, 2 comprimidos, VO, 3x/dia por 7 dias.","B":"Doxiciclina 100mg, VO, 1 comprimido, 2x/dia, por 21 dias.","C":"Ceftriaxona 500mg, IM, dose única + Azitromicina 500mg, 02 comprimidos, VO, dose única.","D":"Ceftriaxona 500mg, IM, dose única + Doxiciclina 100mg, VO, 2x/dia, por 14 dias + Metronidazol\n250mg, 2 comprimidos, VO, 2x/dia, por 14\ndias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-292881","number":"292881","sourceNumber":"292881","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher 30 anos, solteira, procura atendimento devido a queixa de conteúdo vaginal\nabundante com odor fétido há cerca de 5 dias. Relata novo parceiro há cerca de 2 meses, em uso\nde contraceptivo combinado oral. Nega outras queixas clínicas, como alterações menstruais ou\ndisúria. Ao exame: Vulva sem alterações. Ao exame especular: conteúdo fluido algo bolhoso em\nmoderada quantidade, de odor fétido. Colpite ausente. Colo com muco opaco, sem alterações.\n\nTeste de pH= 4,8 Resultado de bacterioscopia por Gram: Células escamosas +++ Leucócitos ++\nMicrobiota constituída por: Bacilos curtos Gram-negativos, cocobacilos Gram variáveis e cocos\nGram-positivos. Escore de Nugent= 8. Qual tratamento é mais adequado nesta situação?","options":{"A":"Azitromicina 1g via oral em dose única.","B":"Metronidazol 500mg, via oral, de 12/12 horas por 7 dias.","C":"Fluconazol 150 mg via oral em dose única e Metronidazol gel vaginal 7 dias.","D":"Ceftriaxona 500mg intramuscular, Azitromicina 1g em dose única e Metronidazol gel vaginal 7\ndias."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-259758","number":"259758","sourceNumber":"259758","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A enfermeira da sua equipe de saúde da família o(a) chama pois está atendendo uma\ngestante de 12 semanas, e o teste rápido para sífilis foi reagente. Ao avaliar alguns exames\ntrazidos pela paciente, você identifica uma sorologia para toxoplasmose IgM e IgG positivos. Diante\ndessa situação, qual conduta deve ser adotada?","options":{"A":"Iniciar tratamento para sífilis e para toxoplasmose.","B":"Solicitar VDRL e solicitar teste de avidez para IgG.","C":"Solicitar VDRL e iniciar tratamento para toxoplasmose.","D":"Iniciar tratamento para sífilis e solicitar teste de avidez para IgG."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-259770","number":"259770","sourceNumber":"259770","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Juliana, 15 anos, G1P0A1, vem para revisão de DIU na UBS, inserido há 1 mês após\nabortamento provocado, referindo dor pélvica. Ao exame, apresenta abdome flácido, doloroso à\npalpação profunda em hipogástrio e fossas ilíacas bilateralmente. Nega dor à descompressão\nsúbita do abdome. Evidencia-se corrimento purulento exteriorizando-se pelo OCE ao espéculo e\ndor a mobilização do colo e palpação de anexos no toque bimanual. Qual a melhor conduta?","options":{"A":"Internar paciente, iniciar ceftriaxona e clindamicina e reavaliar após 48 horas.","B":"Iniciar tratamento ambulatorial com doxiciclina e metronidazol e reavaliar com 24 horas.","C":"Retirar o DIU de imediato e colher cultura de secreção endocervical para iniciar tratamento.","D":"Tratar com dose única de azitromicina e ciprofloxacino e retirar DIU depois de 6 horas do\ntratamento."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-259771","number":"259771","sourceNumber":"259771","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 20 anos comparece à primeira consulta ginecológica com queixa de prurido\nvulvar ocasional há alguns dias. Relata\ncorrimento vaginal de longa data, sem relação com fase do\nciclo menstrual. Faz uso de contraceptivo injetável mensal desde a sexarca aos 17 anos. Ao\nexame, apresenta vulva sem hiperemia, com presença de pequenas lesões papilomatosas\nespiculadas, de coloração semelhante à pele, em região perineal. Conteúdo vaginal esbranquiçado,\nescasso, sem odor, não aderido às paredes vaginais. Colo sem lesões. Qual a conduta adequada a\nseguir?","options":{"A":"Coletar exame citopatológico.","B":"Solicitar genotipagem para HPV.","C":"Aplicar ácido tricloroacético a 90%.","D":"Realizar bacterioscopia a fresco do conteúdo vaginal."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-234070","number":"234070","sourceNumber":"234070","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Homem de 20 anos, assintomático, comparece à consulta para apresentar resultados\nde sorologias realizadas na semana anterior:\nFTA-ABs reagente; VDRL reagente em título 1/8. No\nprontuário consta a informação que o paciente havia sido tratado para sífilis secundária, há três\nmeses, com dose única de 2,4 milhões UI de penicilina benzatina. À época, apresentava VDRL\nreagente em título 1/256. Qual a conduta recomendada?","options":{"A":"Indicar punção lombar.","B":"Repetir VDRL dentro de três meses.","C":"Retratar com doxiciclina oral por 14 dias.","D":"Retratar com duas doses de penicilina benzatina."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-234097","number":"234097","sourceNumber":"234097","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A vaginose bacteriana é relatada por alguns especialistas como a causa mais frequente\ndos sintomas vaginais que resultam em consultas\nmédicas. Entre os sintomas, descarga vaginal\nsem irritação é característica. Assinale a assertiva correta sobre os critérios diagnósticos\nutilizados.","options":{"A":"O pH vaginal caracteristicamente está abaixo de 4,5 e resulta da produção de ácido pelas\nbactérias.","B":"Mulheres diagnosticadas com vaginose bacteriana comumente apresentam evidência\nmicroscópica de tricomoníase.","C":"Presença de células epiteliais vaginais com bactérias aderidas, (borda celular pontilhada mal\ndefinida) tém baixa predição para o diagnóstico.","D":"A adição de preparação salina a uma amostra do conteúdo vaginal, para o exame ?a fresco?,\nlibera aminas voláteis com odor de peixe,\nevidente mesmo sem o KOH."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-199669","number":"199669","sourceNumber":"199669","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 18 anos, em atendimento ginecológico, apresenta edema e hiperemia vulvar,\nmanchas vermelhas no colo uterino além de conteúdo vaginal espesso, levemente fétido. Teste do\nKOH foi negativo e o pH foi normal. Exame direto do conteúdo vaginal identificou microorganismos\ncom flagelos móveis na lâmina. Qual a melhor conduta terapêutica?","options":{"A":"Miconazol creme de aplicação vaginal 7 noites.","B":"Azitromicina 1000 mg via oral, em dose única.","C":"Ceftriaxona 250 mg intramuscular, em dose única.","D":"Metronidazol 500 mg via oral 12/12 horas por 7 dias."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-172951","number":"172951","sourceNumber":"172951","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Luciana, primeira gestação, iniciou pré-natal numa UBASF, com 16 semanas, onde\nrealizou teste rápido para Sífilis que foi reagente. Diante desse resultado, qual a melhor conduta\npara Luciana?","options":{"A":"Solicitar teste treponêmico (FTA-ABS) para confirmação e posterior tratamento do casal.","B":"Tratar gestante e parceiro com três doses de penicilina benzatina e fazer controle com FTA-ABS\nmensal.","C":"Iniciar penicilina benzatina, colher VDRL da gestante, testar e tratar parceiro sexual se\npositivo\npara sífilis.","D":"Aguardar confirmação de VDRL reagente para iniciar tratamento do casal e controle com VDRL\nmensal."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-172979","number":"172979","sourceNumber":"172979","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com sorologia reagente para HIV retornou para a consulta pré-natal na 34ª\nsemana de gravidez. Solicitada carga viral cujo resultado foi 5.000 cópias. Ante o valor da carga\nviral, qual deve ser a conduta obstétrica quanto à via do parto e momento da resolução da\ngravidez?","options":{"A":"Cesárea eletiva na 38ª semana.","B":"Indução do parto na 39ª semana.","C":"Indução do parto na 40ª semana.","D":"Aguardar parto espontâneo até a 40ª semana."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-173030","number":"173030","sourceNumber":"173030","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 28 anos, comparece a consulta na UBS com queixa de corrimento vaginal\namarelado, há 3 dias. Nega disúria, dispareunia, prurido ou ardor vaginal. Ao exame especular:\nobserva-se presença de conteúdo vaginal branco, homogêneo, finamente aderido às paredes\nvaginais, mucosa vaginal e colo uterino sem alterações. pH vaginal 6,0. Teste do KOH positivo.\nRealizado exame a fresco: presença de células indicadoras, ausência de leucócitos e raros\nlactobacilos à microscopia. Qual o tratamento adequado para o caso em questão?","options":{"A":"Miconazol creme, aplicação vaginal por 7 noites.","B":"Metronidazol 500 mg oral, 12/12h por 7 dias.","C":"Azitromicina 1 g oral dose única, orientar tratamento do parceiro com droga oral.","D":"Metronidazol gel a 0,75%, um aplicador ao deitar por 5 dias, orientar tratamento do parceiro com\ndroga oral."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-173036","number":"173036","sourceNumber":"173036","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Adolescente de 16 anos comparece a um serviço de emergência ginecológica com\nrelato de violência sexual há cerca de dois\nmeses, na qual houve relação sexual vaginal sem uso\nde preservativo. Paciente não usava método contraceptivo e não deseja engravidar agora. Vem\ncom beta-hCG positivo e ultrassonografia transvaginal compatível com gestação de 10 semanas.\nQual a conduta correta?","options":{"A":"Orientar sobre seus direitos de interrupção de gravidez ou de pré-natal com opção de adoção.","B":"Esclarecer que ela deve procurar o Instituto Médico Legal para autorização da interrupção da\ngravidez.","C":"Realizar exame ginecológico com coleta de sorologias, encaminhando posteriormente para início\ndo pré-natal.","D":"Encaminhar para autorização judicial da interrupção da gravidez, podendo-se aguardar até idade\ngestacional de 20 semanas."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-150863","number":"150863","sourceNumber":"150863","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 24 anos, primigesta, idade gestacional de 14 semanas pela data da última\nmenstruação. Em primeira consulta de pré-natal, na Unidade Básica de Saúde, apresenta teste\nrápido reagente para sífilis e não reagente para HIV. Encontra-se assintomática e relata parceiro\nsexual fixo há 2 anos. Não há anormalidades ao exame físico. Considerando a atual situação\nnacional de escassez de penicilina benzatina, qual a opção que define a melhor conduta?","options":{"A":"Repetir teste rápido para a paciente e solicitá-lo para o parceiro; tratá-la imediatamente com\npenicilina benzatina e o parceiro com doxiciclina.","B":"Solicitar VDRL para a paciente e parceiro, com retorno em 7 dias; tratá-la imediatamente com\npenicilina benzatina e o parceiro com doxiciclina.","C":"Solicitar VDRL para a paciente e parceiro, com retorno em 7 dias; tratá-la com penicilina\nbenzatina e o parceiro com eritromicina, a depender dos resultados.","D":"Repetir teste rápido para a paciente e tratá-la com penicilina benzatina, a depender do\nresultado;\ntratar o parceiro com eritromicina, se o\nteste da paciente for reagente."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-150887","number":"150887","sourceNumber":"150887","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Jovem de 20 anos, comparece à consulta na Unidade Básica de Saúde referindo\ncorrimento há 2 semanas, com odor fétido. Tem\nparceiro único há 4 meses, que apresentava\ndiscreto corrimento uretral hialino. Ao exame especular, evidencia-se muco cervical purulento e\nhemático, além de leve corrimento fluido esbranquiçado vaginal. Ao toque bimanual, exame sem\nanormalidades. Foi realizado teste de Whiff positivo, coleta vaginal para exame direto com\nevidência de células indicadoras, e cultura de coleta endocervical em meio Thayer-Martin negativa,\ncom poucos leucócitos ao gram endocervical. Qual a prescrição ideal a seguir?","options":{"A":"Ciprofloxacino 500 mg VO em dose única e doxiciclina 100 mg VO de 12/12 horas.","B":"Metronidazol 2 g VO, azitromicina 1 g VO e ceftriaxone 250 mg IM, todos em dose única.","C":"Metronidazol 500 mg VO de 12/12 horas por 7 dias e azitromicina 1 g VO em dose única.","D":"Ceftriaxone 250 mg IM em dose única e Metronidazol gel por via vaginal durante 5 a 7 dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-127028","number":"127028","sourceNumber":"127028","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"<p>Paciente secundigesta, comparece para sua consulta pré-natal na Unidade\nBásica de Saúde da Família. Encontra-se no\ncurso da 16ª semana de gestação, assintomática,\napresentando VDRL com título de 1:16. Refere ter sido submetida a tratamento completo\ncom ceftriaxona, a época do diagnóstico, ocorrido há 3 anos, em virtude de alergia à penicilina.\nAnte o enunciado, qual deve ser a conduta?</p>","options":{"A":"Considerar a paciente adequadamente tratada, com o VDRL representando cicatriz sorológica.","B":"Dessensibilização para penicilina benzatina, seguida de 2,4 milhões UI, intramuscular, em dose\núnica.","C":"Contra-indicar penicilina benzatina e fazer novo curso de tratamento com ceftriaxona,\nintramuscular.","D":"Dessensibilização para penicilina benzatina, seguida de 2,4 milhões UI, intramuscular, semanal,\ntrês semanas."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-126942","number":"126942","sourceNumber":"126942","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 30 anos comparece a consulta ginecológica com queixa de corrimento\nvaginal acinzentado, com mau cheiro, há 7 dias e\npiora do odor após relação sexual. Nega disúria,\ndispareunia, prurido ou ardor vaginal. Ao exame especular: mucosa vaginal com pregueamento\nnormal, presença de conteúdo vaginal abundante, esbranquiçado, com mau cheiro e colo\nuterino sem alterações. Sobre o caso acima, qual o diagnóstico etiológico mais provável e o exame\nmais adequado, baseados na história e no exame físico?","options":{"A":"Tricomoníase vaginal e avaliação microscópica corado pelo Gram do conteúdo vaginal com\ndeterminação do pH vaginal.","B":"Vaginose bacteriana e avaliação microscópica de preparação salina do conteúdo vaginal com\nliberação de aminas voláteis.","C":"Vaginite atrófica e avaliação microscópica de esfregaço de secreção vaginal corado pelo Gram\ncom determinação do pH vaginal.","D":"Candidíase vaginal e avaliação microscópica de esfregaço do conteúdo vaginal corado pelo\nGram com liberação de aminas voláteis."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-102111","number":"102111","sourceNumber":"102111","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 17 anos de idade foi a uma UPA apresentando febre de 38,8°C, vômito, dor\npélvica intensa, com sinais claros de irritação peritoneal. Refere que tudo começou após relações\nsexuais, há poucos dias. Qual a conduta terapêutica mais adequada para esse problema?","options":{"A":"Tratamento hospitalar com abordagem cirúrgica imediata, Laparotomia exploradora.","B":"Tratamento ambulatorial com ceftriaxona 250mg, IM, dose única e doxiciclina 100mg VO 2 x dia,\npor 14 dias.","C":"Tratamento hospitalar com clindamicina, 900mg EV a cada 8 h e gentamicina 2mg/Kg\nseguida de 1,5mg/Kg a cada 8h.","D":"Tratamento ambulatorial com cefoxitina, 2g IM, doxiciclina100mg, VO 2 x dia, por 14 dias, e\nmetronidazol 500mg 2x dia,VO, por 14 dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-102159","number":"102159","sourceNumber":"102159","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 16 anos de idade teve início da vida sexual recentemente. Procura\natendimento médico com quadro de úlceras\ndolorosas na região vulvar que tiveram início há dois\ndias e que foram precedidas por vesículas. Baseado no fluxograma da abordagem sindrômica das\nDST, qual o tratamento mais adequado?","options":{"A":"Azitromicina, 1 g VO em dose única.","B":"Aciclovir, 400 mg VO de 8/8 horas por 7 dias.","C":"Doxiciclina, 100 mg VO de 12/12 horas por 21 dias.","D":"Penicilina G Benzatina, 2.400.000 UI IM em dose única."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-81303","number":"81303","sourceNumber":"81303","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 28 anos procura a Unidade de Saúde da Família referindo ter sido vítima de\nestupro, com penetração vaginal. Relata ter duas gestações anteriores e que estava fazendo uso\nregular de anticoncepcional injetável. O agressor foi seu ex-marido. Qual deverá ser a abordagem\nmais adequada para esse caso?","options":{"A":"Prescrever benzodiazepínico nas primeiras 48 horas para alívio do sofrimento.","B":"Solicitar Beta-HCG, VDRL e anti-HIV e prescrever anticoncepção de emergência.","C":"Solicitar um boletim de ocorrência para poder realizar o primeiro atendimento e notificação\ncompulsória.","D":"Prescrever Penicilina benzatina 2,4 milhões IM, ciprofloxacina 500 mg, azitromicina 1 g, em dose\núnica, para profilaxia de sífilis, gonorreia e cancro mole, respectivamente."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-81324","number":"81324","sourceNumber":"81324","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Homem, 34 anos, com história de 10 dias de ulceração peniana, indolor, com bordas\nelevadas e fundo limpo, relata história de relação sexual não protegida cerca de um mês antes.\nTrouxe exame de VDRL realizado há 2 dias, com resultado negativo. De acordo com a\nrecomendação da Organização Mundial de Saúde e do Ministério da Saúde, para o manejo\nsindrômico de úlceras genitais, qual o tratamento medicamentoso mais adequado para esse\npaciente?","options":{"A":"Azitromicina 1 grama, via oral , dose única.","B":"Ceftriaxona 250 mg, intramuscular, dose única.","C":"Penicilina benzatina 2,4 milhões U, intramuscular, dose única.","D":"Penicilina benzatina 2,4 milhões U, intramuscular, dose única e Azitromicina 1 grama, via oral,\ndose\n\núnica."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-81326","number":"81326","sourceNumber":"81326","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Priscila, 15 anos de idade, procura a unidade de saúde da família com queixas de dor\nna região pélvica. Durante a consulta com o\nmédico de família e comunidade, ela relata que sofre\nabuso sexual do padrasto desde os 13 anos de idade. Qual é a conduta mais adequada a ser\ntomada neste momento?","options":{"A":"Preencher o formulário de Notificação/Investigação individual: Violência doméstica, sexual e/ou\noutras violências interpessoais e comunicar ao Conselho Tutelar ou à Vara da Infância e da\nJuventude.","B":"Comunicar à polícia por telefone, encaminhar a paciente a uma Delegacia da Mulher para\nrealizar o Boletim de Ocorrência e agendar\nexame pericial de Corpo de Delito e Conjunção Carnal\nno Instituto Médico Legal.","C":"Prescrever anticoncepção de emergência, realizar profilaxia de DST não viral (sífilis, cancro\nmole, gonorreia, clamidiose e tricomoníase) e\nsolicitar sorologias para sífilis, HIV e hepatites virais,\nalém de dosagem de Beta-HCG.","D":"Solicitar a presença imediata dos pais ou responsáveis legais da adolescente para acompanhar\na consulta médica, inclusive presenciar o exame\nginecológico. Agendar consulta com o psicólogo\ndo Núcleo de Apoio à Saúde da Família (NASF)."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-81309","number":"81309","sourceNumber":"81309","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher, 22 anos de idade, vem ao ambulatório com queixa de ardor ao urinar. No\nexame ginecológico, são identificadas duas úlceras\nprofundas com bordos irregulares no introito\nvaginal, dolorosas à palpação, associadas a linfonodos inguinais palpáveis e dolorosos. Qual o\nmelhor tratamento?","options":{"A":"Aciclovir.","B":"Doxiciclina.","C":"Azitromicina.","D":"Penicilina Benzatina."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-81271","number":"81271","sourceNumber":"81271","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante, no início do pré-natal, apresenta pápulas palmo-plantares\n\neritemato-descamativas, alopécia e placas úmidas na região vulvar e perineal. Foi solicitado o\nexame RPR (Rapid Plasma Reagin), que mostrou\ntitulação de 1:32. Com esses achados, foi\nindicada a terapêutica. Após o início do tratamento, passou a apresentar febre, adinamia, mialgia,\nartralgia e exacerbação das lesões cutâneas. Diante do quadro, qual a conduta mais indicada?","options":{"A":"Manter a terapêutica.","B":"Suspender a terapêutica.","C":"Trocar a medicação por ceftriaxona.","D":"Internar e iniciar a dessensibilização."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-65695","number":"65695","sourceNumber":"65695","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 22 anos procura a Unidade Básica de Saúde (UBS), relatando ter sido vítima\nde violência sexual há 24 horas. O médico foi\nquestionado pela paciente em relação à\nanticoncepção de emergência. Referiu não estar utilizando nenhum método contraceptivo há 6\nmeses. Qual o contraceptivo mais adequado nessa situação?","options":{"A":"Desogestrel, 75 mcg, VO, em dose única.","B":"Acetato de medroxiprogesterona, 150 mg, IM, dose única.","C":"Não há mais indicação, pois já se passaram mais de 12 horas.","D":"Levonorgestrel, 0,75 mg, VO, em duas doses com intervalo de 12 horas.","E":"Contraceptivos orais combinados de terceira geração (etinilestradiol 30 mcg + gestodeno 75\nmcg), dois comprimidos, VO, em dose única."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-65686","number":"65686","sourceNumber":"65686","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 18 anos de idade, solteira com namorado, procura emergência médica com\nquadro de dor hipogástrica associada a corrimento amarelado há três dias, iniciado após o término\nda menstruação. Ao exame especular, apresenta conteúdo amarelado discreto com leve odor\nfétido. Ao toque vaginal, o colo é doloroso à mobilização, além de dor à palpação em hipogástrio e\nfossas ilíacas direita e esquerda. Não apresenta febre ou sinais de peritonite. A melhor conduta\nmedicamentosa é:","options":{"A":"Ampicilina 1 g EV 6/6 horas por 48 horas associada à azitromicina 1 g VO em dose única.","B":"Clindamicina 900 mg EV 8/8 horas associada à gentamicina 1,5 mg/kg 8/8 horas por 72 horas.","C":"Ceftriaxona 250 mg IM dose única associada à doxiciclina 100 mg VO 12/12 horas por 14 dias.","D":"Cefoxitina 2 g EV 12/12 horas associada à doxiciclina 100 mg EV 12/12 horas até melhora\nclínica.","E":"Penicilina benzatina 1,2 milhões de UI IM associada ao metronidazol 500 mg VO 12/12 horas por\n14 dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-51131","number":"51131","sourceNumber":"51131","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante de 20 semanas recebe resultado de VDRL 1:64 realizado no primeiro\ntrimestre. Apresenta há 2 meses quadro de lesões\nexantemáticas na pele e mucosa bucal, além de\nlesões em alvo na palma das mãos. Qual o tratamento apropriado?","options":{"A":"Penicilina cristalina 2.400.000 UI IM em dose única.","B":"Penicilina benzatina 2.400.000 UI IM em dose única.","C":"Penicilina cristalina 2.400.000 UI IM em 3 doses semanais.","D":"Penicilina benzatina 2.400.000 UI IM em 3 doses semanais."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-51116","number":"51116","sourceNumber":"51116","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 25 anos de idade apresenta sinusiorragia. Apresenta-se, ao exame de colo\nuterino, com ectopia inflamada. Qual o agente etiológico mais provável?","options":{"A":"Candida albicans.","B":"Gardnerella vaginalis.","C":"Trichomonas vaginalis.","D":"Chlamydia trachomatis."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-51107","number":"51107","sourceNumber":"51107","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Que alternativa apresenta consequências da vaginose bacteriana além dos sintomas do\ntrato genital inferior?","options":{"A":"As infecções pós-operatórias, incluindo a pós-abortiva, a celulite da cúpula vaginal\n\npós-histerectomia e endomiometrite pós-cesariana estão associadas à vaginose bacteriana\nassintomática. A profilaxia antibiótica pré-operatória pode NÃO reduzir essas complicações.","B":"A vaginose bacteriana incide em 15 a 20% nas mulheres grávidas. Estudos demonstram que a\nvaginose bacteriana aumenta o risco de parto prematuro em até 40%. Esses resultados NÃO são\npreveníveis pelo uso de metronidazol por via oral.","C":"A vaginose bacteriana está associada com endocervicite muco purulento. Até 50% de pacientes\nassistidas em uma clínica especializada em doenças sexualmente transmissíveis têm diagnóstico\nde endocervicite muco purulenta e vaginose coexistentes.","D":"A vaginose bacteriana está fortemente associada com aborto espontâneo no segundo trimestre,\nbem como de outros resultados adversos da\ngravidez. O tratamento com clindamicina VO, 300 mg\nduas vezes ao dia, durante 5 dias, NÃO reduz a incidência de perda no segundo trimestre."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-51214","number":"51214","sourceNumber":"51214","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Adolescente do sexo masculino procura a Unidade de Saúde por apresentar pequeno\ncorrimento uretral fluido e esbranquiçado, percebido antes da primeira micção matinal, às vezes só\npercebido através de ordenha manual. Sua parceira não apresenta qualquer sintoma. Quais são os\ndois principais agentes etiológicos mais prováveis para esse caso?","options":{"A":"Streptococcus agalactiae e Papilomavírus humano.","B":"Clamydia trachomatis e Ureaplasma urealyticum.","C":"Clamydia trachomatis e Trichomonas vaginalis.","D":"Gardnerella vaginalis e Clamydia trachomatis."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-51268","number":"51268","sourceNumber":"51268","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Homem de 25 anos comparece à unidade básica de saúde com queixa de lesão, de\naparecimento há 1 semana, em pênis. Nega surgimento de vesículas no local. Ao exame,\nconstata-se lesão ulcerada única em região balanoprepucial, pouco dolorosa, com bordos\nendurecidos. Constata-se adenopatia inguinal não supurativa, móvel, indolor e múltipla. Refere\nrelações sexuais desprotegidas com múltiplos parceiros em uma festa há 3 semanas. Qual a\nconduta?","options":{"A":"Iniciar penicilina G benzatina 3 doses de 1.200.000 UI IM, solicitar sorologias para HIV,\nhepatite\nB e convocar parceiros.","B":"Iniciar penicilina G benzatina dose única de 2.400.000 UI IM, solicitar sorologias para HIV,\nsífilis,\nhepatites B e C e convocar parceiros.","C":"Iniciar penicilina G benzatina 3 doses de 2.400.000 UI IM + azitromicina 1 g VO dose única e\nencaminhar para serviço especializado.","D":"Iniciar penicilina G benzatina dose única de 2.400.000 UI IM + azitromicina 1 g VO dose única,\nsolicitar sorologias para HIV, sífilis, hepatites B e C e convocar parceiros."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-51299","number":"51299","sourceNumber":"51299","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 28 anos de idade, com parceiro há 3 meses, apresentou quadro de vesículas\ne ardência na região perineal há 1 semana,\nseguido do surgimento de úlcera muito dolorosa no\nlocal, que vem progredindo com melhora e formação de crosta no local, recentemente. Qual o\nagente etiológico provável?","options":{"A":"Treponema pallidum.","B":"HPV ? papiloma vírus humano.","C":"HSV- Herpes vírus hominis 1 ou 2.","D":"Calymmatobacterium granulomatis."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-141617","number":"141617","sourceNumber":"141617","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 20 anos, vida sexual ativa e em uso de contraceptivo hormonal, refere\ncorrimento vaginal, amarelado associado à\ndisúria. Ao exame especular, observa-se corrimento\nendocervical purulento, colo friável e hiperemiado, e o exame do muco cervical revelou a presença\nde diplococos Gram-negativos intracelulares. O agente etiológico provável é:","options":{"A":"Chlamydia trachomatis.","B":"Neisseria gonorrhoeae.","C":"Trichomonas vaginalis.","D":"Gardnerella vaginalis."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-141581","number":"141581","sourceNumber":"141581","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Ambulatório de Ginecologia: paciente, 30 anos, G4P3C3A1, última cesárea +\nlaqueadura tubária há 5 anos, com queixa de dor\nem fossa ilíaca direita de forte intensidade tipo\npontada há 2 dias, associada a febre não aferida. Nega queixas urinárias ou alterações do hábito\nintestinal. Ao exame EGB, afebril, abdome doloroso a palpação profunda em hipogástrio e fossas\nilíacas. Blumberg negativo. Colo friável. Toque doloroso a mobilização do colo uterino e palpação\ndos fundos de saco laterais. Anexos impalpáveis. Qual a melhor opção terapêutica?","options":{"A":"Clindamicina e Cefalotina.","B":"Azitromicina e Ciprofloxacino.","C":"Metronidazol e Nitrato de Miconazol.","D":"Ceftriaxona, Doxiciclina e Metronidazol."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-141590","number":"141590","sourceNumber":"141590","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 15 anos, G1P1, queixa-se de corrimento vaginal persistente associado a\nprurido intenso. Ao exame especular, observa-se conteúdo vaginal branco, grumoso, aderido às\nparedes vaginais. Hiperemia e edema de vagina e vulva. Qual a melhor avaliação nesse caso?","options":{"A":"Teste do KOH.","B":"Colpocitologia oncótica.","C":"Cultura da endocérvice.","D":"Exame direto do conteúdo vaginal."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-45360","number":"45360","sourceNumber":"45360","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A presença de uma úlcera genital indolor, endurecida, sem linfadenopatia inguinal, é,\nmais provavelmente, por:","options":{"A":"herpes.","B":"lesões por HPV.","C":"cancroide.","D":"sífilis.","E":"linfogranuloma venéreo."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-37446","number":"37446","sourceNumber":"37446","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Qual a droga de escolha para o tratamento da sífilis na gravidez?","options":{"A":"Estearato de eritromicina.","B":"Azitromicina.","C":"Penicilina G benzatina.","D":"Ceftriaxona.","E":"Amoxacilina."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-37462","number":"37462","sourceNumber":"37462","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Creuza de 29 anos teve o diagnóstico laboratorial de tricomoníase. Ao exame clínico,\ndeve-se encontrar:","options":{"A":"Corrimento branco, inodoro, espesso, tipo leite talhado.","B":"Corrimento branco-amarelado, com odor de peixe podre e bolhas esparsas.","C":"Corrimento abundante, amarelo-esverdeado, purulento e bolhoso e \"colo em framboesa\" pelo\nTeste de Schiller.","D":"Corrimento abundante, purulento e bolhoso.","E":"Corrimento discreto, verde-amarelado e muco-purulento."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-37466","number":"37466","sourceNumber":"37466","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 22 anos há 7 dias apresentando dor abdominal de forte intensidade, iniciada\napós a menstruação. Ao exame especular observou-se conteúdo vaginal anormal e ao toque\nvaginal bidigital dor à palpação dos anexos e dor à mobilização uterina. O tratamento mais\napropriado, dentre os abaixo, é:","options":{"A":"Ceftriaxone 250mg IM, dose única associada a doxiciclina 100mg, VO, 12/12h, por 14 dias.","B":"Penicilina cristalina, 4 milhões de U EV, 6/6h, por 2 dias.","C":"Ceftriaxone 250mg IM, dose única associada ao\nmetronidazol 500mg 2x/dia por 14 dias.","D":"Ampicilina 500 mg VO, 6/6h, por 14 dias associada a doxiciclina 100mg, VO, 12/12h, por 14\ndias.","E":"Eritromicina 500mg, VO, 6/6h por sete dias associada ao metronidazol 500mg 2x/dia por 10 dias."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-349732","number":"349732","sourceNumber":"349732","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em relação à reação de Jarisch-Herxheimer, assinale a alternativa correta.","options":{"A":"Ocorre no final do tratamento da sífilis, no qual o paciente pode apresentar exacerbação das\nlesões cutâneas, com eritema, dor ou prurido.","B":"Cursa com febre, dor de cabeça, sudorese, calafrios e tremores, sendo necessária a suspensão\nimediata do tratamento devido ao alto risco de reação anafilática.","C":"É uma reação alérgica grave à penicilina com alto risco de reação anafilática e necessidade de\nadministração de adrenalina intramuscular profilática.","D":"Ocorre no início do tratamento de sífilis em resposta ao derrame de proteínas e de outras\nestruturas dos treponemas mortos pela penicilina na corrente sanguínea.","E":"Também é conhecida como síndrome de Stevens-Johnson."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-349690","number":"349690","sourceNumber":"349690","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Como manifestação da sífilis secundária, é possível encontrar","options":{"A":"cancro mole.","B":"múltiplas vesículas em vulva.","C":"leucorreia purulenta proveniente do colo uterino.","D":"condiloma plano.","E":"úlcera única em vagina."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-349685","number":"349685","sourceNumber":"349685","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Durante um plantão no pronto-socorro obstétrico, o médico avalia uma paciente de 10\nsemanas de gestação apresentando múltiplas\nvesículas em região vaginal com diagnóstico clínico\nde herpes genital, sendo a primo-infecção. Quanto ao tratamento para esse caso, é correto indicar","options":{"A":"aciclovir 400 mg uma vez ao dia por 6 meses.","B":"fanciclovir 100 mg três vezes ao dia por 10 dias.","C":"valaciclovir 1000 mg 1 vez ao dia por 5 dias.","D":"aciclovir 400 mg três vezes ao dia por 7 dias.","E":"fanciclovir 50 mg a cada 5 horas, pulando a dose da madrugada."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-365567","number":"365567","sourceNumber":"365567","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 20 anos de idade deu entrada no pronto-socorro referindo ter sido\nvítima de abuso sexual há duas horas, com queixa de sangramento vaginal de pequena monta,\nassociado a escoriações pelo corpo. Em relação ao atendimento das pacientes vítimas de abuso\nsexual, assinale a alternativa correta.","options":{"A":"O caso deve ser referenciado ao Instituto Médico Legal de imediato, para exame clínico e para\nprovidências legais.","B":"A paciente deverá ser acolhida, o atendimento inicial e o tratamento das lesões deverão ser\nprestados e, depois disso, ela deverá ser aconselhada a procurar a delegacia para as devidas\nprovidências legais pertinentes ao caso.","C":"A profilaxia das doenças sexualmente transmissíveis e o tratamento das lesões somente\npoderão ocorrer após registro do boletim de\nocorrência da autoridade policial.","D":"A paciente deverá acionar a delegacia de polícia para que o atendimento ocorra na presença da\nautoridade policial."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-349699","number":"349699","sourceNumber":"349699","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um ginecologista é chamado para avaliar uma paciente de 20 anos, nuligesta,\napresentando dor abdominal de início há uma\nsemana e que foi internada na enfermaria do hospital\nlocal para investigação. A data da última menstruação foi há 15 dias. Refere não utilizar método\ncontraceptivo de maneira regular, apenas condom esporádico. Relata dispareunia e apresenta\ndismenorreia que melhora com uso de AINES. PA 120x60 mmHg, FC 90 bpm, Sat. O2 99%, T.\naxilar 38,4°C. Ao exame abdominal, leve dor à palpação superficial de região suprapúbica e o\nexame ginecológico apresenta corrimento de coloração amarelada proveniente do colo uterino\nassociado à dor à mobilização do colo uterino. O exame ultrassonográfico revela sinal da roda\ndentada. Diante desse caso clínico, assinale a principal hipótese diagnóstica e a conduta\nadequada.","options":{"A":"Doença inflamatória pélvica / O tratamento deve ser realizado obrigatoriamente em domicílio\ncom antibioticoterapia via oral.","B":"O sinal da roda dentada mostra que se trata de um quadro de apendicite associado à doença\ninflamatória pélvica / A indicação é cirúrgica e deve-se iniciar antibioticoterapia.","C":"Pielonefrite complicada por uretrite / Realizar internação e antibioticoterapia endovenosa.","D":"A principal suspeita, diante do sinal da roda dentada, é gestação ectópica / Realizar\ninternamento e solicitar beta quantitativo a cada 48 horas.","E":"Doença inflamatória pélvica / Realizar internação, sendo possível iniciar ceftriaxona e\nmetronidazol endovenoso e, à medida que a\npaciente melhorar e não apresentar mais quadro febril,\no esquema pode ser trocado para via oral."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-365585","number":"365585","sourceNumber":"365585","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma gestante, atualmente com 38 semanas, G2P1, iniciou o pré-natal com 12 semanas\nde gestação em unidade de saúde da família de\nsua região e, naquela ocasião, realizou teste\nrápido para sífilis e para HIV, com resultado negativa. Retornou à consulta com 32 semanas de\ngestação, assintomática, com resultado de teste rápido de HIV não reagente e, para sífilis, reagente\ncom resultado de VDRL - 1/16. Assinale a alternativa que apresenta o diagnóstico e a conduta\npreconizada pelo Ministério da Saúde do Brasil (PCDT 2022) para o caso clínico mencionado.","options":{"A":"Sífilis primária: realizar penicilina benzatina 2,4 milhões UI, dose única, e tratar parceiro.","B":"Sífilis secundária: realizar penicilina benzatina 2,4 milhões UI, por 2 semanas, e tratar\nparceiro.","C":"Sífilis latente tardia: realizar penicilina benzatina 2,4 milhões UI, por 3 semanas, e tratar\nparceiro.","D":"Sífilis latente recente: realizar penicilina benzatina 2,4 milhões UI, dose única, e tratar\nparceiro."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-365608","number":"365608","sourceNumber":"365608","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma gestante, atualmente com 38 semanas, G2P1, iniciou o pré-natal com 12 semanas\nde gestação em unidade de saúde da família de\nsua região e, naquela ocasião, realizou teste\nrápido para sífilis e para HIV, com resultado negativa. Retornou à consulta com 32 semanas de\ngestação, assintomática, com resultado de teste rápido de HIV não reagente e, para sífilis, reagente\ncom resultado de VDRL - 1/16. Relativamente ao caso clínico citado, e considerando que a\npaciente em análise tenha apresentado VDRL = 1/32, qual valor de VDRL significaria que a\npaciente teve sucesso no tratamento após seis meses?","options":{"A":"1/8","B":"1/4","C":"1/2","D":"1/16"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-349702","number":"349702","sourceNumber":"349702","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Sobre a candidíase vaginal, informe se é verdadeiro (V) ou falso (F) o que se afirma a\nseguir e assinale a alternativa com a sequência correta. ( ) O exame microscópico da leucorreia\nvaginal, após aplicação de KOH a 10%, permite a identificação da levedura. ( ) A Candida albicans\né dimórfica, apresentando tanto leveduras quanto hifas. ( ) A cultura para cândida vaginal é\nrecomendada como rotina. ( ) O tratamento primário para a prevenção de infecção recorrente é feito\ncom fluconazol oral, uma vez por semana por 2 meses.","options":{"A":"F - F - V - V.","B":"F - V - V - F.","C":"V - V - V - F.","D":"V - V - F - V.","E":"V - V - F - F."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-322169","number":"322169","sourceNumber":"322169","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"As infecções sexualmente transmissíveis são um grave problema de saúde pública no\nBrasil, devendo-se ter especial atenção à população adolescente. Considerando somente as\ninfecções adquiridas, qual, das seguintes, pode ser tranmitida de outras formas além da sexual?","options":{"A":"Sífilis.","B":"Hepatite B.","C":"Gonorreia.","D":"Linfogranuloma venéreo.","E":"Cancro mole."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-322187","number":"322187","sourceNumber":"322187","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Pacientes que apresentam vaginose citolítica podem ter alguns sintomas semelhantes\na outros tipos de vaginites, como prurido e\ncorrimento esbranquiçado antes do período menstrual;\nardor; queimação; disúria e dispareunia. Essa semelhança de sintomas com outras patologias do\ntrato genital inferior pode atrasar o seu diagnóstico. Em relação à vaginose citolítica, é correto\nafirmar que","options":{"A":"é causada pela proliferação excessiva de Lactobacillus e pela redução do PH vaginal, que se\nencontra menor ou igual a quatro.","B":"o processo inflamatório intenso é causado por Streptococcus do grupo B e Escherichia Coli.","C":"tem como agente etiológico o parasita flagelado Trichomonas vaginalis.","D":"é o processo inflamatório vaginal causado pela proliferação de fungos como o Candida tropicalis.","E":"é causada pela substituição da flora microbiana vaginal denominada Lactobacillus por bactérias\nanaeróbias e facultativas."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-322194","number":"322194","sourceNumber":"322194","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma gestante de 18 anos, G1, que não realizou pré-natal, com aproximadamente 38\nsemanas de idade gestacional, calculada pela\ndata da última menstruação, chega à maternidade\nem trabalho de parto, com 3 contrações em 10 minutos e toque vaginal colo esvaecido com 6 cm\nde dilatação. Nesse caso, visando reduzir os riscos de transmissão vertical do HIV, é correto\nafirmar que:","options":{"A":"Deve ser realizado teste rápido de HIV na admissão e, caso o resultado seja positivo, iniciar\ninfusão de AZT.","B":"Deve ser realizado teste rápido de HIV na admissão e, caso o resultado seja positivo, será uma\nindicação absoluta de cesárea.","C":"Deve ser realizado teste rápido de HIV na admissão e, caso o resultado seja positivo, a\namniotomia precoce será indicada.","D":"Deve ser realizado teste rápido de HIV na admissão e, caso o resultado seja positivo, o parto\ninstrumentalizado e a episiotomia estão indicados para acelerar o nascimento.","E":"Deve ser realizado teste rápido de HIV na admissão e, caso o resultado seja negativo, exclui-se\ncompletamente a possibilidade de essa paciente possuir o vírus do HIV."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-322204","number":"322204","sourceNumber":"322204","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 26 anos agenda consulta com ginecologista devido à dor pélvica com\nduração aproximadamente 30 dias. Relata que não tem\nparceiro fixo e, nos últimos meses,\napresentou relação desprotegida. Ao exame especular, apresenta secreção purulenta proveniente\ndo colo do útero e, no toque vaginal, dor à mobilização do colo do útero e anexos. O ultrassom\nginecológico não mostrou anormalidades. Para essa paciente, qual esquema antibiótico é o mais\nrecomendado?","options":{"A":"Ceftriaxona e amoxicilina.","B":"Cefalexina e ciprofloxacino.","C":"Doxiciclina e azitromicina.","D":"Ceftriaxona e azitromicina.","E":"Clindamicina e metronidazol."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-322206","number":"322206","sourceNumber":"322206","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 40 anos apresenta leucorreia de odor fétido. Na citologia oncótica\ncervical, foi demonstrada a presença de clue\ncells. Sobre esse assunto, informe se é Verdadeiro (V)\nou Falso (F) o que se afirma a seguir e assinale a alternativa com a sequência correta. ( ) O teste\nde aminas possivelmente será positivo. ( ) O PH vaginal, nesse caso, será menor que 4,5. ( )\nGardnerella Vaginalis, Bacterioides, Mobiluncus e Peptococcus fazem parte da flora normal, desde\nque em pequenas quantidades. ( ) Nesse caso, é necessário o tratamento do parceiro.","options":{"A":"V - V - V - F.","B":"V - F - V - F.","C":"V - V - F - F.","D":"F - F - F - V.","E":"F - F - V - F."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-337583","number":"337583","sourceNumber":"337583","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 14 anos, virgem, apresenta queixa de corrimento vaginal escuro de\nodor fétido associado a prurido. Após exame clínico e laboratorial, foi identificada a presença de\nGardnerella vaginalis. Em relação ao caso clínico exposto, julgue o item a seguir. Essa paciente\ndeve ser internada para o tratamento, pois tem contraindicação ao uso de pomada vaginal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-337584","number":"337584","sourceNumber":"337584","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 14 anos, virgem, apresenta queixa de corrimento vaginal escuro de\nodor fétido associado a prurido. Após exame\nclínico e laboratorial, foi identificada a presença de\nGardnerella vaginalis. Em relação ao caso clínico exposto, julgue o item a seguir. A paciente pode\nser tratada com metronidazol.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-337585","number":"337585","sourceNumber":"337585","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 14 anos, virgem, apresenta queixa de corrimento vaginal escuro de\nodor fétido associado a prurido. Após exame\nclínico e laboratorial, foi identificada a presença de\nGardnerella vaginalis. Em relação ao caso clínico exposto, julgue o item a seguir. Pode-se tratar de\num caso de abuso sexual, pois a Gardnerella é transmitida via relação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-337586","number":"337586","sourceNumber":"337586","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 14 anos, virgem, apresenta queixa de corrimento vaginal escuro de\nodor fétido associado a prurido. Após exame clínico e laboratorial, foi identificada a presença de\nGardnerella vaginalis. Em relação ao caso clínico exposto, julgue o item a seguir. É obrigatório o\ntratamento da Gardnerella, independentemente de haver ou não sintomas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-337587","number":"337587","sourceNumber":"337587","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 14 anos, virgem, apresenta queixa de corrimento vaginal escuro de\nodor fétido associado a prurido. Após exame clínico e laboratorial, foi identificada a presença de\nGardnerella vaginalis. Em relação ao caso clínico exposto, julgue o item a seguir. Assim como a\ncândida Albicans, a Gardnerella pode ser encontrada na microbiota vaginal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-337588","number":"337588","sourceNumber":"337588","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 14 anos, virgem, apresenta queixa de corrimento vaginal escuro de\nodor fétido associado a prurido. Após exame clínico e laboratorial, foi identificada a presença de\nGardnerella vaginalis. Em relação ao caso clínico exposto, julgue o item a seguir. O PH vaginal\ndessa paciente será maior que 4,5.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-305326","number":"305326","sourceNumber":"305326","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"H.O.S, feminino, 23 anos, chega ao serviço de pronto atendimento com queixa de\ncorrimento vaginal. Relata, ao médico residente, ter relações sexuais com parceiro único há 5\nmeses, não usando preservativo. Nega ISTs prévias. Ao exame físico ginecológico: genitália\nexterna sem alterações. Ao exame com espéculo, vê-se colo uterino com presença de\nmicroulcerações, além de corrimento amarelo esverdeado, bolhoso e de odor fétido. Notam-se\nainda paredes vaginais íntegras. Assinale a alternativa correta acerca da principal hipótese\ndiagnóstica e possível conduta para esse caso.","options":{"A":"Tricomoníase, iniciar o esquema com Metronidazol para a paciente.","B":"Tricomoníase, iniciar o esquema com Metronidazol para a paciente e para seu parceiro sexual.","C":"Vaginose bacteriana, iniciar o esquema com Metronidazol para a paciente.","D":"Vaginose bacteriana, iniciar o esquema com Metronidazol para a paciente e para seu parceiro\nsexual.","E":"Candidíase vulvovaginal, iniciar o tratamento da paciente com fluconazol."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-305336","number":"305336","sourceNumber":"305336","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"M.A.S, 26 anos, procurou o PA com queixa de lesão dolorosa em região genital com\ninício há 4 dias. Ao exame, apresenta úlcera em região vulvar, com fundo purulento e dolorosa à\npalpação. Foi observado, ainda, um linfonodo aumentado na região inguinal esquerda, drenando\nsecreção por orifício único. Qual é a principal hipótese diagnóstica?","options":{"A":"Herpes genital.","B":"Linfogranuloma venéreo.","C":"Cancro mole.","D":"Sífilis (cancro duro).","E":"Donovanose."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-298934","number":"298934","sourceNumber":"298934","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um paciente de 35 anos de idade compareceu à consulta na unidade básica de saúde\n(UBS) com queixa de disúria e presença de\nsecreção peniana há dois dias. Relata relações sexuais\ndesprotegidas nas últimas duas semanas. Ao exame físico, observou-se presença de drenagem de\nsecreção mucopurulenta na uretra. Foram realizados testes rápidos, na UBS, para HIV, hepatites B\ne C e sífilis, obtiveram-se resultados não reagentes. Considerando esse caso clínico e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Trata-se de uma infecção\nsexualmente transmissível (IST), sendo os patógenos mais prováveis a Neisseria gonorrhoeae e a\nChlamydia trachomatis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-298935","number":"298935","sourceNumber":"298935","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um paciente de 35 anos de idade compareceu à consulta na Unidade Básica de Saúde\n(UBS) com queixa de disúria e presença de\nsecreção peniana há dois dias. Relata relações sexuais\ndesprotegidas nas últimas duas semanas. Ao exame físico, observou-se presença de drenagem de\nsecreção mucopurulenta na uretra. Foram realizados testes rápidos, na UBS, para HIV, hepatites B\ne C e sífilis, obtiveram-se resultados não reagentes. Considerando esse caso clínico e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Caso não haja laboratório disponível\npara diferenciar o patógeno, o tratamento preconizado pelo Ministério da Saúde é ceftriaxona 500\nmg intramuscular e azitromicina 1.000 mg via oral, ambas em dose única.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-274401","number":"274401","sourceNumber":"274401","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante com 12 semanas apresenta teste VDRL positivo nos exames de pré-natal.\nPaciente não refere história clínica de úlcera genital e desconhece sorologia do parceiro. A\nprescrição do tratamento dessa gestante deve ocorrer","options":{"A":"no momento da consulta.","B":"se houver elevação da titulação de VDRL.","C":"após resultado de teste treponêmico.","D":"após resultado de teste do parceiro.","E":"após resultado do teste no recém-nascido."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-274414","number":"274414","sourceNumber":"274414","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 37 anos procura consultório com queixa de corrimento vaginal associado à\nardência, prurido e dispareunia. O exame especular mostra corrimento amarelo-esverdeado\nbolhoso e hiperemia de mucosa, sugestivo de colpite. A principal hipótese diagnóstica é","options":{"A":"candidíase vaginal.","B":"corpo estranho.","C":"tricomoníase.","D":"vaginose bacteriana.","E":"vaginose citolítica."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261283","number":"261283","sourceNumber":"261283","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 15 anos de idade vai à consulta com o ginecologista assistente,\nreferindo que a \"camisinha estourou\" durante\nrelação sexual consensual há cerca de quatro\nsemanas. Relata que o parceiro procurou um urologista e foi diagnosticado com alguma doença\nsexualmente transmissível (DST), sendo prescrito tratamento com azitromicina e ceftriaxona,\nambos em doses únicas. A paciente queixa-se de dor em baixo ventre, náuseas e vômitos nos\núltimos dois dias. Nega febre. Ao exame físico, é identificado corrimento amarelo-esverdeado e\ncom odor fétido, e demonstra dor à mobilização do colo do útero e à palpação dos anexos.\n\nApresenta uma ultrassonografia transvaginal sem laudo, com sinais de salpingite. Demais aspectos\ndo exame não puderam ser avaliados, pois as\nimagens estavam pouco nítidas. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O diagnóstico mais\nprovável é de doença inflamatória pélvica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261285","number":"261285","sourceNumber":"261285","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 15 anos de idade vai à consulta com o ginecologista assistente,\nreferindo que a \"camisinha estourou\" durante\nrelação sexual consensual há cerca de quatro\nsemanas. Relata que o parceiro procurou um urologista e foi diagnosticado com alguma doença\nsexualmente transmissível (DST), sendo prescrito tratamento com azitromicina e ceftriaxone,\nambos em doses únicas. A paciente queixa-se de dor em baixo ventre, náuseas e vômitos nos\núltimos dois dias. Nega febre. Ao exame físico, é identificado corrimento amarelo-esverdeado e\ncom odor fétido, e demonstra dor à mobilização do colo do útero e à palpação dos anexos.\n\nApresenta uma ultrassonografia transvaginal sem laudo, com sinais de salpingite. Demais aspectos\ndo exame não puderam ser avaliados, pois as\nimagens estavam pouco nítidas. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A presença de\nnáuseas e vômitos é o único critério para tratamento hospitalar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261286","number":"261286","sourceNumber":"261286","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 15 anos de idade vai à consulta com o ginecologista assistente,\nreferindo que a \"camisinha estourou\" durante\nrelação sexual consensual há cerca de quatro\nsemanas. Relata que o parceiro procurou um urologista e foi diagnosticado com alguma doença\nsexualmente transmissível (DST), sendo prescrito tratamento com azitromicina e ceftriaxone,\nambos em doses únicas. A paciente queixa-se de dor em baixo ventre, náuseas e vômitos nos\núltimos dois dias. Nega febre. Ao exame físico, é identificado corrimento amarelo-esverdeado e\ncom odor fétido, e demonstra dor à mobilização do colo do útero e à palpação dos anexos.\n\nApresenta uma ultrassonografia transvaginal sem laudo, com sinais de salpingite. Demais aspectos\ndo exame não puderam ser avaliados, pois as\nimagens estavam pouco nítidas. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O tratamento deve ser\nhospitalar pela presença de salpingite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261287","number":"261287","sourceNumber":"261287","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 15 anos de idade vai à consulta com o ginecologista assistente,\nreferindo que a \"camisinha estourou\" durante\nrelação sexual consensual há cerca de quatro\nsemanas. Relata que o parceiro procurou um urologista e foi diagnosticado com alguma doença\nsexualmente transmissível (DST), sendo prescrito tratamento com azitromicina e ceftriaxone,\nambos em doses únicas. A paciente queixa-se de dor em baixo ventre, náuseas e vômitos nos\núltimos dois dias. Nega febre. Ao exame físico, é identificado corrimento amarelo-esverdeado e\ncom odor fétido, e demonstra dor à mobilização do colo do útero e à palpação dos anexos.\n\nApresenta uma ultrassonografia transvaginal sem laudo, com sinais de salpingite. Demais aspectos\ndo exame não puderam ser avaliados, pois as\nimagens estavam pouco nítidas. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Um dos esquemas\nantibióticos para tratamento hospitalar pode ser a associação de clindamicina + gentamicina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261288","number":"261288","sourceNumber":"261288","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 15 anos de idade vai à consulta com o ginecologista assistente,\nreferindo que a \"camisinha estourou\" durante\nrelação sexual consensual há cerca de quatro\nsemanas. Relata que o parceiro procurou um urologista e foi diagnosticado com alguma doença\nsexualmente transmissível (DST), sendo prescrito tratamento com azitromicina e ceftriaxone,\nambos em doses únicas. A paciente queixa-se de dor em baixo ventre, náuseas e vômitos nos\núltimos dois dias. Nega febre. Ao exame físico, é identificado corrimento amarelo-esverdeado e\ncom odor fétido, e demonstra dor à mobilização do colo do útero e à palpação dos anexos.\n\nApresenta uma ultrassonografia transvaginal sem laudo, com sinais de salpingite. Demais aspectos\ndo exame não puderam ser avaliados, pois as\nimagens estavam pouco nítidas. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Caso seja indicado\ntratamento com metronidazol, o médico deve alertar a paciente a não ingerir bebidas alcoólicas até\n24 horas após o tratamento, pelo risco de efeito dissulfiram.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261289","number":"261289","sourceNumber":"261289","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 15 anos de idade vai à consulta com o ginecologista assistente,\nreferindo que a \"camisinha estourou\" durante a\nrelação sexual consensual há cerca de quatro\nsemanas. Relata que o parceiro procurou um urologista e foi diagnosticado com alguma Doença\nSexualmente Transmissível (DST), sendo prescrito tratamento com azitromicina e ceftriaxona,\nambos em doses únicas. A paciente queixa-se de dor em baixo ventre, náuseas e vômitos nos\núltimos dois dias. Nega febre. Ao exame físico, é identificado corrimento amarelo-esverdeado e\ncom odor fétido, e demonstra dor à mobilização do colo do útero e à palpação dos anexos.\n\nApresenta uma ultrassonografia transvaginal sem laudo, com sinais de salpingite. Demais aspectos\ndo exame não puderam ser avaliados, pois as\nimagens estavam pouco nítidas. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Pode-se considerar a\npaciente como vítima de estupro de vulnerável.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-261290","number":"261290","sourceNumber":"261290","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma adolescente de 12 anos de idade sofre uma queda ao andar de bicicleta, colidindo\na região genital contra o quadro central. A\npaciente é levada pela mãe a uma emergência pediátrica\npara avaliação, em razão de edema vulvar. Ao chegar, a paciente refere dor pélvica importante. É\navaliada por um cirurgião pediátrico que identifica hematoma em grandes lábios, estável desde o\nacidente, segundo a mãe, associado a edema de pequenos e grandes lábios. Quanto ao caso\nclínico apresentado e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir.\nA presença de instabilidade hemodinâmica indica necessidade de exploração cirúrgica do\nhematoma imediatamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250138","number":"250138","sourceNumber":"250138","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 26 anos de idade, previamente hígida, compareceu à consulta\nginecológica com queixa de que, há uma semana, vem apresentando secreção vaginal\namarelo-esverdeada, abundante, bolhosa, com cheiro ruim e associada à disúria e dispareunia.\n\nInforma relações sexuais desprotegidas com parceiro novo há duas semanas. Com base nesse\ncaso hipotético, julgue o item a seguir. O quadro\nclínico descrito é sugestivo de candidíase vaginal\ne espera-se encontrar pseudo-hifas no exame a fresco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250139","number":"250139","sourceNumber":"250139","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 26 anos de idade, previamente hígida, compareceu à consulta\nginecológica com queixa de que, há uma semana, vem apresentando secreção vaginal\namarelo-esverdeada, abundante, bolhosa, com cheiro ruim e associada à disúria e dispareunia.\n\nInforma relações sexuais desprotegidas com parceiro novo há duas semanas. Com base nesse\ncaso hipotético, julgue o item a seguir. Ao\nexame da secreção vaginal apresentada pela paciente,\npode ser encontrado protozoário móvel e pH elevado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250140","number":"250140","sourceNumber":"250140","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 26 anos de idade, previamente hígida, compareceu à consulta\nginecológica com queixa de que, há uma semana, vem apresentando secreção vaginal\namarelo-esverdeada, abundante, bolhosa, com cheiro ruim e associada à disúria e dispareunia.\n\nInforma relações sexuais desprotegidas com parceiro novo há duas semanas. Com base nesse\ncaso hipotético, julgue o item a seguir. Para a\ncondição descrita, está indicada a busca ativa por\noutras doenças sexualmente transmissíveis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250141","number":"250141","sourceNumber":"250141","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 32 anos de idade refere, na consulta ginecológica de rotina, que\napresenta secreção mamária espontânea à\nesquerda. Com base nesse caso hipotético, julgue o\nitem a seguir. A secreção de cor esverdeada é sugestiva de infecção ou malignidade subjacente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-250145","number":"250145","sourceNumber":"250145","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O câncer de colo uterino é o câncer ginecológico mais comum nas mulheres. No que\ndiz respeito a essa temática, julgue o item a\nseguir. Os subtipos 6 e 11 são os mais relacionados ao\ncarcinoma de células escamosas de colo uterino.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-239322","number":"239322","sourceNumber":"239322","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento\nvaginal acinzentado e com odor fétido na última\nsemana. Refere também que gostaria de realizar\ncheck-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria\nmãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica\npregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de\nidade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse\ncaso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir.\nConsiderando diagnóstico de vaginose bacteriana por Gardnerella vaginalis, o tratamento poderá\nser feito com metronidazol via oral, devendo-se, ainda, convocar parceria sexual para tratamento\nadequado do casal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-239335","number":"239335","sourceNumber":"239335","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente vítima de estupro deseja realizar a interrupção da gravidez. A respeito\ndesse caso clinico, julgue o item a seguir. O\nmédico apenas deverá realizar o procedimento quando\na paciente apresentar documentação necessária, a saber, termo de consentimento livre e\nesclarecido, boletim de ocorrência policial e exame de corpo de delito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-211971","number":"211971","sourceNumber":"211971","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Determinada paciente de 38 anos de idade, G1P0, com 13 semanas de idade\ngestacional, apresenta queixa de leucorreia branca\nlíquida com odor fétido. Ao exame especular,\nevidenciam-se corrimento homogêneo branco-acinzentado e teste das aminas positivo. Acerca do\ncaso clínico mencionado, assinale a alternativa que corresponde ao tratamento mais adequado\npara essa paciente.","options":{"A":"Metronidazol 250 mg, oito comprimidos via oral em dose única.","B":"Fluconazol 150 mg, um comprimido via oral em dose única.","C":"Metronidazol 500 mg via oral a cada 12 horas durante sete dias.","D":"Nistatina creme vaginal durante sete noites.","E":"Doxiciclina 100 mg, comprimido via oral a cada 12 horas durante sete dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-211990","number":"211990","sourceNumber":"211990","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Certa paciente de 17 anos de idade chega ao pronto-socorro apresentando queixa de\ndor pélvica de moderada intensidade,\ncalafrios, náuseas, vômitos e leucorreia de coloração\namarelada. Refere que os sintomas se iniciaram há algumas horas. Ao exame físico, a paciente\nmanifesta dor de forte intensidade à mobilização cervical, TAx de 38,2°C e saída de secreção\npurulenta pelo orifício cervical ao exame especular. De acordo com o diagnóstico provável, assinale\na alternativa que indica o melhor tratamento a ser proposto para a paciente desse caso clínico.","options":{"A":"Ambulatorial, ceftriaxona 250 mg IM dose única + doxiciclina 100 mg 2x/dia por 14 dias.","B":"Hospitalar, clindamicina 900 mg EV 8h/8h + gentamicina de acordo com o peso.","C":"Ambulatorial, doxiciclina 100 mg VO 2x/dia + azitromicina 1 g dose única.","D":"Hospitalar, doxiciclina 100 mg VO 2x/dia + cefalexina 500 mg 4x/dia.","E":"Hospitalar, ceftriaxona 250 mg IM dose única + metronidazol 1,5 mg EV 1x/dia."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-196630","number":"196630","sourceNumber":"196630","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Certa paciente de 27 anos de idade procura atendimento em emergência clínica por dor\npélvica há dois dias, mal-estar, febre, náuseas e vômitos. Na anamnese, refere ser sexualmente\nativa, apresentando corrimento vaginal há cinco dias, associado a dispareunia e sangramento\n\npós-coital. Ao exame físico, a paciente está hipocorada, taquicárdica, com abdome doloroso à\npalpação e com sinais de irritação\nperitoneal, pressão arterial de 88 mmHg x 40 mmHg, FC de 126\nbpm, com 22 irpm, sat 0? igual a 64% com óculos nasal 3 L/min. Quanto ao exame especular, há\npresença de corrimento mucopurulento e, no toque vaginal, apresenta dor importante à mobilização\ndo colo uterino. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. O principal diagnóstico é doença inflamatória pélvica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-196644","number":"196644","sourceNumber":"196644","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Certa paciente de 27 anos de idade procura atendimento em emergência clínica por dor\npélvica há dois dias, mal-estar, febre, náuseas e vômitos. Na anamnese, refere ser sexualmente\nativa, apresentando corrimento vaginal há cinco dias, associado a dispareunia e sangramento\n\npós-coital. Ao exame físico, a paciente está hipocorada, taquicárdica, com abdome doloroso à\npalpação e com sinais de irritação\nperitoneal, pressão arterial de 88 mmHg x 40 mmHg, FC de 126\nbpm, com 22 irpm, sat 0? igual a 64% com óculos nasal 3 L/min. Quanto ao exame especular, há\npresença de corrimento mucopurulento e, no toque vaginal, apresenta dor importante à mobilização\ndo colo uterino. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Não é necessário solicitar beta HCG para essa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-196647","number":"196647","sourceNumber":"196647","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Certa paciente de 27 anos de idade procura atendimento em emergência clínica por dor\npélvica há dois dias, mal-estar, febre, náuseas e vômitos. Na anamnese, refere ser sexualmente\nativa, apresentando corrimento vaginal há cinco dias, associado a dispareunia e sangramento\n\npós-coital. Ao exame físico, a paciente está hipocorada, taquicárdica, com abdome doloroso à\npalpação e com sinais de irritação\nperitoneal, pressão arterial de 88 mmHg x 40 mmHg, FC de 126\nbpm, com 22 irpm, sat 0? igual a 64% com óculos nasal 3 L/min. Quanto ao exame especular, há\npresença de corrimento mucopurulento e, no toque vaginal, apresenta dor importante à mobilização\ndo colo uterino. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Deve-se iniciar antibioticoterapia em regime ambulatorial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-196653","number":"196653","sourceNumber":"196653","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Certa paciente de 27 anos de idade procura atendimento em emergência clínica por dor\npélvica há dois dias, mal-estar, febre, náuseas e vômitos. Na anamnese, refere ser sexualmente\nativa, apresentando corrimento vaginal há cinco dias, associado a dispareunia e sangramento\n\npós-coital. Ao exame físico, a paciente está hipocorada, taquicárdica, com abdome doloroso à\npalpação e com sinais de irritação\nperitoneal, pressão arterial de 88 mmHg x 40 mmHg, FC de 126\nbpm, com 22 irpm, sat 0? igual a 64% com óculos nasal 3 L/min. Quanto ao exame especular, há\npresença de corrimento mucopurulento e, no toque vaginal, apresenta dor importante à mobilização\ndo colo uterino. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. A ecografia é importante para se avaliar a presença de abscesso tubo-ovariano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-196628","number":"196628","sourceNumber":"196628","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Determinada paciente de 16 anos de idade iniciou atendimento pré-natal em posto de\nsaúde da família e foi diagnosticada com\nHIV nas sorologias de primeiro trimestre, iniciando terapia\nantirretroviral adequada e com boa adesão imediatamente. Os demais exames de rotina de\n\npré-natal mostraram-se normais. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Caso a\ncarga viral, após 34 semanas de gestação, seja superior a\n\n1.000 cópias, a cesária eletiva com 38 semanas estará indicada, devendo ser acompanhada de\ninfusão intravenosa de AZT na gestante, durante o parto, e do uso de AZT e nevirapina oral na\ncriança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-196636","number":"196636","sourceNumber":"196636","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Determinada paciente de 16 anos de idade iniciou atendimento pré-natal em posto de\nsaúde da família e foi diagnosticada com\nHIV nas sorologias de primeiro trimestre, iniciando terapia\nantirretroviral adequada e com boa adesão imediatamente. Os demais exames de rotina de\n\npré-natal mostraram-se normais. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Caso a\ngestante apresente carga viral indetectável após a 34ª\nsemana, pode-se realizar o parto vaginal, não sendo necessária a administração materna de AZT\ninjetável ou o uso de nevirapina na criança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-179166","number":"179166","sourceNumber":"179166","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"O agente etiológico da doença de transmissão exclusivamente sexual, mais frequente\nnas regiões tropicais, que se caracteriza por\napresentar lesões múltiplas (podendo ser única), tipo\núlceras, habitualmente dolorosas, de borda irregular, com contornos eritematoedematosos e fundo\nirregular, cobertas por exsudato necrótico, amarelado e de odor fétido que, quando removido,\nrevela tecido de granulação que apresenta sangramento fácil quando submetido a traumatismos,\nocorrendo na fúrcula e na face interna dos grandes lábios, lesões que produzam sintomatologia\ndiscreta no colo uterino e na parede vaginal, lesões extragenitais e infecções assintomáticas é\no(a)","options":{"A":"Chlamydia tracomatis.","B":"Calymmatobacterium granulomatis (Klebsiella granulomatis, Donovania granulomatis).","C":"Neisseria gonorrhoeae.","D":"papilomavírus humano.","E":"Haemophilus ducrey."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-179181","number":"179181","sourceNumber":"179181","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando-se que a gravidez decorrente de violência sexual seja um dos maiores\ntemores das vítimas, reforça-se a opção pela contracepção de emergência. Nessas situações,\nquando o ritonavir estiver incluso no esquema de profilaxia da AIDS, o melhor método será","options":{"A":"somente o levonorgestrel.","B":"o método de Yuzpe (administração combinada de um estrogênio e um progestágeno sintético).","C":"a associação etinilestradiol e levonorgestrel.","D":"somente o etinilestradiol.","E":"qualquer estrogênio, desde que em altas doses."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177703","number":"177703","sourceNumber":"177703","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 20 anos de idade procura um atendimento de emergência, relatando estupro\ncom coito vaginal há 2 horas. Refere fazer\nuso regular de contraceptivo oral combinado. Com base\nnesse caso hipotético e considerando os conhecimentos médicos a eles relacionados, julgue o item\na seguir. No Brasil, os casos de violência sexual contra a mulher são de notificação obrigatória.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177708","number":"177708","sourceNumber":"177708","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 20 anos de idade procura um atendimento de emergência, relatando estupro\ncom coito vaginal há 2 horas. Refere fazer\nuso regular de contraceptivo oral combinado. Com base\nnesse caso hipotético e considerando os conhecimentos médicos a eles relacionados, julgue o item\na seguir. A paciente vítima de violência sexual deve ser acolhida pela equipe de saúde somente\napós a realização da ocorrência policial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177675","number":"177675","sourceNumber":"177675","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 20 anos de idade procura um atendimento de emergência, relatando estupro\ncom coito vaginal há 2 horas. Refere fazer\nuso regular de contraceptivo oral combinado. Com base\nnesse caso hipotético e considerando os conhecimentos médicos a eles relacionados, julgue o item\na seguir. Deve-se realizar a profilaxia das DSTs, como hepatites virais, HIV, sífilis, e dos agentes\ninfecciosos gonococo e clamídia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177691","number":"177691","sourceNumber":"177691","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 25 anos de idade, do sexo feminino, refere dor no baixo ventre há 5 dias,\nleucorreia e dispareunia. Nega disúria e febre. Faz uso regular de anticoncepcional oral combinado.\nRelata ter tido dois parceiros sexuais nos últimos 4 meses. Ao exame, acusa dor à palpação no\nbaixo ventre, sem sinais de irritação peritoneal. No exame especular, evidencia-se leucorreia\nmucopurulenta e, ao toque vaginal, a paciente alega importante dor à mobilização do colo uterino.\nCom base nesse caso clínico, julgue o item a seguir. O quadro clínico é compatível com doença\ninflamatória pélvica, que é uma infecção polimicrobiana, cujos agentes etiológicos principais são o\nMycoplasma Genitalium e o Ureaplasma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177697","number":"177697","sourceNumber":"177697","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 25 anos de idade, do sexo feminino, refere dor no baixo ventre há 5 dias,\nleucorreia e dispareunia. Nega disúria e febre. Faz uso regular de anticoncepcional oral combinado.\nRelata ter tido dois parceiros sexuais nos últimos 4 meses. Ao exame, acusa dor à palpação no\nbaixo ventre, sem sinais de irritação peritoneal. No exame especular, evidencia-se leucorreia\nmucopurulenta e, ao toque vaginal, a paciente alega importante dor à mobilização do colo uterino.\nCom base nesse caso clínico, julgue o item a seguir. Devem ser solicitados, para a paciente,\nexames para outras DSTs, como HIV, sífilis, hepatite B e hepatite C.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177562","number":"177562","sourceNumber":"177562","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 25 anos de idade, do sexo feminino, refere dor no baixo ventre há 5 dias,\nleucorreia e dispareunia. Nega disúria e febre. Faz uso regular de anticoncepcional oral combinado.\nRelata ter tido dois parceiros sexuais nos últimos 4 meses. Ao exame, acusa dor à palpação no\nbaixo ventre, sem sinais de irritação peritoneal. No exame especular, evidencia-se leucorreia\nmucopurulenta e, ao toque vaginal, a paciente alega importante dor à mobilização do colo uterino.\nCom base nesse caso clínico, julgue o item a seguir. O tratamento da paciente em questão deverá\nser com antibióticos de amplo espectro, em regime ambulatorial, com seguimento/revisão em 72\nhoras.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-154354","number":"154354","sourceNumber":"154354","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 23 anos de idade, comparece ao consultório ginecológico com queixa de\núlcera vulvar indolor. Nega trauma local. Há\ndois dias, apresenta febre de cerca de 38 °C. Ao ser\nindagada, relata relação sexual desprotegida há duas semanas. Ao exame físico, percebe-se bom\nestado geral, afebril, além de lesão ulcerada na fúrcula vaginal, única, região inguinal com\nadenomegalia dolorosa, drenando secreção purulenta espontaneamente por múltiplos orifícios. No\ncaso clínico apresentado o diagnóstico mais provável é","options":{"A":"cancro mole.","B":"cancro duro.","C":"úlcera de Lipschutz.","D":"linfogranuloma venéreo.","E":"donovanose."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152099","number":"152099","sourceNumber":"152099","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 19 anos de idade, primigesta, com 35 semanas de gestação, tabagista de\n10 cigarros/dia, com má adesão ao pré-natal,\napresenta exames solicitados de terceiro trimestre,\nentre eles VDRL 1:16, e demais sorologias não reagentes. Paciente nega tratamento prévio para\nsífilis e desconhece o diagnóstico da doença; não realizou sorologias de primeiro e segundo\ntrimestre. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o\nitem a seguir. O tratramento padrão ouro é ceftriaxona EV dose única.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152101","number":"152101","sourceNumber":"152101","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 19 anos de idade, primigesta, com 35 semanas de gestação, tabagista de\n10 cigarros/dia, com má adesão ao pré-natal,\napresenta exames solicitados de terceiro trimestre,\nentre eles VDRL 1:16, e demais sorologias não reagentes. Paciente nega tratamento prévio para\nsífilis e desconhece o diagnóstico da doença; não realizou sorologias de primeiro e segundo\ntrimestre. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o\nitem a seguir. Não é necessário tratar o parceiro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152108","number":"152108","sourceNumber":"152108","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 19 anos de idade, primigesta, com 35 semanas de gestação, tabagista de\n10 cigarros/dia, com má adesão ao pré-natal,\napresenta exames solicitados de terceiro trimestre,\nentre eles VDRL 1:16, e demais sorologias não reagentes. Paciente nega tratamento prévio para\nsífilis e desconhece o diagnóstico da doença; não realizou sorologias de primeiro e segundo\ntrimestre. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o\nitem a seguir. O tratamento padrão ouro é penicilina benzatina 7.200.000 UI, IM para o casal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152063","number":"152063","sourceNumber":"152063","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 19 anos de idade, primigesta, com 35 semanas de gestação, tabagista de\n10 cigarros/dia, com má adesão ao pré-natal,\napresenta exames solicitados de terceiro trimestre,\nentre eles VDRL 1:16, e demais sorologias não reagentes. Paciente nega tratamento prévio para\nsífilis e desconhece o diagnóstico da doença; não realizou sorologias de primeiro e segundo\ntrimestre. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o\nitem a seguir. Em caso de alergia à medicação padrão-ouro, a paciente deve ser dessensibilizada\nem meio hospitalar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152073","number":"152073","sourceNumber":"152073","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 19 anos de idade, primigesta, com 35 semanas de gestação, tabagista de\n10 cigarros/dia, com má adesão ao pré-natal,\napresenta exames solicitados de terceiro trimestre,\nentre eles VDRL 1:16, e demais sorologias não reagentes. Paciente nega tratamento prévio para\nsífilis e desconhece o diagnóstico da doença; não realizou sorologias de primeiro e segundo\ntrimestre. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o\nitem a seguir. Por se tratar de uma sorologia não treponêmica, o VDRL, nesse caso, deve ser um\nfalso positivo e, portanto, não se deve realizar o tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-152153","number":"152153","sourceNumber":"152153","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A paciente T. C. R., de 14 anos de idade, chega ao respectivo domicílio e relata à mãe\ndela que o vizinho a forçou a manter relações sexuais com ele há aproximadamente duas horas.\n\nEla está chorosa, com receio de contar o ocorrido ao pai e temendo engravidar, pois não usa\nmétodo contraceptivo no momento. A mãe a acolhe e\nconduz a adolescente até uma Unidade de\nPronto Atendimento (UPA), tanto pela qualidade da atenção à saúde prestada pela equipe quanto\npela confiança naqueles profissionais. Considerando a situação hipotética apresentada, a Política\nde Amparo à Criança e ao Adolescente, a Política de Atenção à Violência contra a Mulher do\nMinistério da Saúde, as portarias que definem o Serviço de Atenção às Pessoas em Situação de\nViolência Sexual e a conduta do médico assistente, julgue o item a seguir. Na unidade de\natendimento, deve ocorrer o acolhimento da vítima, bem como o encaminhamento ao Serviço de\nReferência para a Atenção Integral às Pessoas em Situação de Violência Sexual. Esse serviço,\nque, inclusive, pode ser um dos serviços oferecidos na UPA, é realizado por equipe\nmultiprofissional e engloba: acolhimento; anamnese e registro em prontuário; realização de exames\ne profilaxias necessárias; e, notificação de violência sexual e de outras violências.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-131846","number":"131846","sourceNumber":"131846","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"No que se refere à infecção por cândida e ao respectivo tratamento, assinale a\nalternativa correta.","options":{"A":"A nistatina é contraindicada no tratamento das infecções mucocutâneas por cândida.","B":"O tratamento por via oral com fluconazol somente é indicado quando a infecção se localizar na\norofaringe.","C":"O fluconazol está preferencialmente indicado para pacientes neutropênicos.","D":"Geralmente, é necessária a remoção de material protético (por exemplo, articulação artificial)\ninfectado por cândida para que o tratamento seja bem-sucedido.","E":"Pacientes imunocompetentes com infecção mucocutânea devem evitar o uso de azóis no\ntratamento da infecção por cândida."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-105565","number":"105565","sourceNumber":"105565","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 24 anos de idade, G2PN2A0, consultou-se com ginecologista devido\nà queixa de leucorreia. Foram realizados o\nteste das aminas (positivo) e o exame a fresco da\nsecreção vaginal, sendo que a conclusão do médico foi de que se tratava de vaginose por\nGardnerella vaginalis. Considerando esse caso hipotético, assinale a alternativa que apresenta o\nachado que se espera ter sido visto no exame a fresco.","options":{"A":"Hifas e esporos.","B":"Protozoário flagelado.","C":"Cariomegalia.","D":"Leveduras.","E":"Clue cells."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-108178","number":"108178","sourceNumber":"108178","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos técnicos, éticos e legais relacionados a doenças infecciosas\ne ao atendimento de pessoas vítimas de\nviolência sexual, julgue o item que se segue. As vítimas de\nviolência sexual que ingressarem nos serviços de saúde deverão ser submetidas ao tratamento\ncom antirretrovirais, medicamentos que, nessas situações, são utilizados para reduzir o risco de\ncontaminação pelo HIV.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-108165","number":"108165","sourceNumber":"108165","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos técnicos éticos e legais relacionados a doenças infecciosas\ne ao atendimento de pessoas vítimas de\nviolência sexual, julgue o item que se segue. O uso de\npreservativos não elimina os riscos de transmissão do HPV.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-108133","number":"108133","sourceNumber":"108133","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos técnicos, éticos e legais relacionados à doenças infecciosas\ne ao atendimento de pessoas vítimas de\nviolência sexual, julgue o item que se segue. A síndrome\nde Behcet é uma doença autoimune que geralmente se manifesta por meio de lesões orais e\ngenitais acompanhadas de inflamação ocular.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-79641","number":"79641","sourceNumber":"79641","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A.M.S., adolescente, apresenta edema doloroso em ambos os lábios, pele com\ncoloração azulada e descreve sangramento proveniente da vulva. De acordo com o descrito no\ntexto, A.M.S. sofre de hematoma vulvar, uma condição patológica para a qual deve ser feito\ndiagnóstico diferencial de algumas doenças. Nesse caso, é possível excluir:","options":{"A":"Cistos de Bartholin.","B":"Linfogranuloma venéreo.","C":"Hidradenite supurativa.","D":"Líquen escleroso.","E":"Veias varicosas vulvares."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-79668","number":"79668","sourceNumber":"79668","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Para investigação laboratorial de doença inflamatória pélvica sugere-se: I. hemograma\ncompleto. II. cultura cervical. III. coloração de Gram. IV. dosagem de CA-125. É correto o que está\ncontido em:","options":{"A":"I e II, apenas.","B":"III, apenas.","C":"I, II e III, apenas.","D":"IV, apenas.","E":"I, II, III e IV."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-88663","number":"88663","sourceNumber":"88663","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Suponha que uma adolescente de quinze anos de idade tenha sido violentada\nsexualmente e tenha procurado auxílio em\npronto-socorro, onde foi realizada ocorrência policial e\navaliação pelo médico de plantão. Com relação às condutas adotadas por esse médico, julgue o\nitem a seguir. Um protocolo medicamentoso indicado para a paciente incluiria uma alta dosagem de\nprogestogênios: levonorgestrel, 0,75 mg, em duas doses, com intervalo de doze horas; 1 g de\nazitromicina, dose única, por via oral; zidovudina e lamivudina associada a nelfinavir por quatro\nsemanas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-64285","number":"64285","sourceNumber":"64285","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um paciente de trinta anos de idade foi atendido no ambulatório de clínica médica,\nrelatando a presença, havia dois dias, de\nintenso prurido peniano e, havia um dia, a ocorrência de\nintensa ardência durante a micção, com eliminação de secreção purulenta pela uretra. O paciente\ninformou, ainda, ter tido, havia quatro dias, relação sexual extraconjugal sem uso de preservativo.\nFoi colhida amostra de secreção para exames microbiológicos. No material coletado, corado pelo\nGram, os esfregaços bacterioscópicos evidenciaram diplococos gram-negativos, dispostos aos\npares no interior de leucócitos polimorfonucleares. Com base nesse caso clínico, julgue o item que\nse segue. No que se refere a esse caso, o principal diagnóstico é o cancroide e o tratamento de\nprimeira escolha recomendado é a administração de azitromicina 1g, por via oral, uma vez por\nsemana, durante três semanas.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-64268","number":"64268","sourceNumber":"64268","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Julgue o item seguinte relativo à Doença Inflamatória Pélvica (DIP) e ao Vírus do\nPapiloma Humano (HPV). A DIP, uma infecção monomicrobiana, em geral, inicia-se com\nmanifestações clínicas típicas de tricomoníase ou candidíase vaginal.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-52623","number":"52623","sourceNumber":"52623","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um jovem de vinte e cinco anos de idade procurou atendimento médico com relato de\nque, há dois dias, notou a presença de uma pequena ferida na glande peniana. Informou não ser\nusuário de drogas ilícitas, disse ter tido relação sexual com mais de três parceiras nas últimas\nduas\nsemanas, e que nem sempre usa preservativo. Negou uso regular de medicamentos e outras\ndoenças. O exame do pênis evidenciou a presença de lesão ulcerada, na face posterior do sulco\nbalanoprepucial, arredondada, com 1 cm de extensão, indolor, borda elevada e endurecida e base\ninfiltrada com pequena quantidade de secreção serosa. Os gânglios inguinais estavam palpáveis\nbilateralmente, eram móveis, bem definidos, tinham consistência elástica e estavam indolores. O\njovem não apresentava outras alterações no restante do exame físico. Com referência a esse caso\nclínico julgue o item abaixo. Nessa situação clínica, a principal hipótese diagnóstica é de sífilis\nprimária.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-45749","number":"45749","sourceNumber":"45749","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Para o tratamento dos processos infecciosos que podem acometer a mulher, é\nnecessário o conhecimento acerca dos\nmicro-organismos envolvidos e do espectro antibiótico a ser\nutilizado. Assinale a alternativa que apresenta associação correta entre a infecção e o antibiótico\nadequado ao seu tratamento.","options":{"A":"Infecção do trato urinário inferior: nitrofurantoína.","B":"Endometrite: clindamicina + meropenem.","C":"Mastite não puerperal: cefalexina.","D":"Tricomoníase: azitromicina.","E":"Doença inflamatória pélvica (tratamento hospitalar): ceftriaxona + penicilina benzatina."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366174","number":"366174","sourceNumber":"366174","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos da atenção integral às pessoas com Infecções Sexualmente\nTransmissíveis (ISTS), bem como sua importância para a Saúde da mulher e a imagem\napresentada que mostra lesão em espelho julgue o seguinte item. Como estratégia de prevenção\nprimária, o Protocolo Clínico e Diretrizes Terapêuticas (PCDT) do Ministério da Saúde recomenda\nrastreio anual para adolescentes e jovens com idade menor ou igual a 30 anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366174.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366173","number":"366173","sourceNumber":"366173","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos da atenção integral às pessoas com Infecções Sexualmente\nTransmissíveis (ISTS), bem como sua importância para a Saúde da mulher e a imagem\napresentada que mostra lesão em espelho julgue o seguinte item. Observam-se, na imagem,\nvesículas confluentes nos lábios maiores, algumas delas apresentando características crostosas\ntípicas de uma infecção viral. O quadro clínico é identificado como doloroso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366173.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366171","number":"366171","sourceNumber":"366171","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos da atenção integral às pessoas com Infecções Sexualmente\nTransmissíveis (ISTS), bem como sua importância para a Saúde da mulher e a imagem\napresentada que mostra lesão em espelho julgue o seguinte item. Lesões genitais como\nLinfogranuloma Venéreo, Sífilis e Donovanose habitualmente são úlceras indolores.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366171.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366170","number":"366170","sourceNumber":"366170","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos da atenção integral às pessoas com Infecções Sexualmente\nTransmissíveis (ISTS), bem como sua importância para a Saúde da mulher e a imagem\napresentada que mostra lesão em espelho julgue o seguinte item. A cranco de Ducrey é uma\ninfecção causada pelo Haemophilus ducreyi que cursa com úlceras dolorosas, geralmente múltiplas\ndevido à autoinoculação, de bordos irregulares com base suja que, quando removida, mostra-se\ntecido de granulação de sangramento fácil.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366170.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366169","number":"366169","sourceNumber":"366169","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos da atenção integral às pessoas com Infecções Sexualmente\nTransmissíveis (ISTS), bem como sua importância para a Saúde da mulher e a imagem\napresentada que mostra lesão em espelho julgue o seguinte item. No que tange à Sífilis,\nrecomenda-se iniciar investigação por teste treponênico, primeiro a ficar reagente no caso da\ninfecção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366169.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366168","number":"366168","sourceNumber":"366168","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os aspectos da atenção integral às pessoas com Infecções Sexualmente\nTransmissíveis (ISTS), bem como sua importância para a Saúde da mulher e a imagem\napresentada que mostra lesão em espelho julgue o seguinte item. A maior parte dos casos de DIP\né causada por agentes sexualmente transmissíveis ou associada à vaginose bacteriana sendo os\ndois principais agente etiológicos a Chlamydia trachomatis e Neisseria gonorrhoeae.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366168.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352313","number":"352313","sourceNumber":"352313","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica (DIP) é considerada como um conjunto de sinais e\nsintomas decorrentes da ascensão de microrganismos\na partir do trato genital mais distal e\npropagação para estruturas com endométrio, anexos, peritônio. A respeito da DIP, os conceitos que\no tema suscita e seus conhecimentos prévios, julgue o item abaixo. A Neisseria gonorrhoeae e a\nChlamydia trachomatis são os principais agentes etiológicos da DIP.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366167","number":"366167","sourceNumber":"366167","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando as imagens apresentadas (exame especular e exame a fresco de\nmaterial colhido), bem como os assunto\ncorrelatos, julgue o item subsecutivo. Espera-se encontrar\nvaginal pH < 4,5 e whiff test positivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366167.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352312","number":"352312","sourceNumber":"352312","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica (DIP) é considerada como um conjunto de sinais e\nsintomas decorrentes da ascensão de\nmicrorganismos a partir do trato genital mais distal e\npropagação para estruturas com endométrio, anexos, peritônio. A respeito da DIP, os conceitos que\no tema suscita e seus conhecimentos prévios, julgue o item abaixo. São fatores de risco início de\nvida sexual precoce, baixo nível socioeconômico, tabagismo, etilismo, múltiplas parcerias sexuais e\nmulheres com estado civil solteira.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366166","number":"366166","sourceNumber":"366166","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando as imagens apresentadas (exame especular e exame a fresco de\nmaterial colhido), bem como os assunto\ncorrelatos, julgue o item subsecutivo. É esperado que até\ntrês quartos de mulheres em idade reprodutivas apresentem pelo menos um episódio vulvovaginite\ndurante suas vidas como o mostrado acima.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366166.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352311","number":"352311","sourceNumber":"352311","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica (DIP) é considerada como um conjunto de sinais e\nsintomas decorrentes da ascensão de\nmicrorganismos a partir do trato genital mais distal e\npropagação para estruturas com endométrio, anexos, peritônio. A respeito da DIP, os conceitos que\no tema suscita e seus conhecimentos prévios, julgue o item abaixo. A DIP tem padrão que varia de\nsubagudo a oligossintomático no qual a febre é comum na maioria dos casos. Em quadros\nsubagudos é mais relevante que dor pélvica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366165","number":"366165","sourceNumber":"366165","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando as imagens apresentadas (exame especular e exame a fresco de\nmaterial colhido), bem como os assunto\ncorrelatos, julgue o item subsecutivo. Apesar de os\nsintomas serem extremamente desagradáveis, a condição representada é relativamente comum e\nbenigna e não tem caráter facilitador para aquisição e nem transmissão de outras ISTS.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366165.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352310","number":"352310","sourceNumber":"352310","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica (DIP) é considerada como um conjunto de sinais e\nsintomas decorrentes da ascensão de\nmicrorganismos a partir do trato genital mais distal e\npropagação para estruturas com endométrio, anexos, peritônio. A respeito da DIP, os conceitos que\no tema suscita e seus conhecimentos prévios, julgue o item abaixo. Por ter possibilidade de\nascensão intraperitoneal e possibilidade de sepse grave, o tratamento ambulatorial não é opção\nmesmo em casos leves.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366164","number":"366164","sourceNumber":"366164","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando as imagens apresentadas (exame especular e exame a fresco de\nmaterial colhido), bem como os assunto\ncorrelatos, julgue o item subsecutivo. O principal agente\netiológico do quadro exposto aparenta ter correlação hormônio-dependente, pois raramente\nacomete mulheres em idade reprodutiva ou em terapia hormonal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366164.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352309","number":"352309","sourceNumber":"352309","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica (DIP) é considerada como um conjunto de sinais e\nsintomas decorrentes da ascensão de\nmicrorganismos a partir do trato genital mais distal e\npropagação para estruturas com endométrio, anexos, peritônio. A respeito da DIP, os conceitos que\no tema suscita e seus conhecimentos prévios, julgue o item abaixo. Por ser uma doença profunda\ndo sistema genital feminino e baixo risco de infeção para parcerias, o tratamento para estes está\nindicado apenas nos casos sintomáticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-366163","number":"366163","sourceNumber":"366163","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando as imagens apresentadas (exame especular e exame a fresco de\nmaterial colhido), bem como os assunto\ncorrelatos, julgue o item subsecutivo. É mito que uso de\nantibióticos facilitam proliferação de fungos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/366163.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352308","number":"352308","sourceNumber":"352308","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Doença Inflamatória Pélvica (DIP) é considerada como um conjunto de sinais e\nsintomas decorrentes da ascensão de\nmicrorganismos a partir do trato genital mais distal e\npropagação para estruturas com endométrio, anexos, peritônio. A respeito da DIP, os conceitos que\no tema suscita e seus conhecimentos prévios, julgue o item abaixo. Pacientes com dor em\nhipocôndrio direito também podem ter suspeita de DIP devido aderências no fígado. Nesses casos,\né importante a suspeita da Síndrome de Fitz-Hugh-Curtis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352343","number":"352343","sourceNumber":"352343","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Clara, uma adolescente de 16 anos, comparece à unidade básica de saúde (UBS) em\nbusca de atendimento médico. Na recepção,\no atendente responsável pelo acolhimento verifica o\nendereço de Clara, confirma que ela reside na área de abrangência da UBS e a encaminha para a\nsala da equipe de saúde da família de sua área. Lá, ela é atendida por uma enfermeira da equipe,\nque, após coletar informações sobre a queixa e sua duração, bem como aferir os sinais vitais,\nreconhece sinais de gravidade. Diante disso, a enfermeira aloca a paciente em uma maca na sala\nde medicação e chama imediatamente o médico da equipe, que a atende prontamente. Clara relata\nque está sentindo dor na região hipogástrica e disúria há cerca de três dias, com uma piora\ngradual. Ela teve calafrios durante a última noite, mas não percebeu que poderia estar com febre. A\npaciente está mais preocupada com as dores e com um atraso menstrual. Ela não consegue\nfornecer a data da última menstruação, mas acredita que tenha ocorrido antes do nascimento de\nseu irmão, que hoje tem três meses. Ao realizar o exame físico, a equipe de saúde observa que\nClara está sonolenta, febril, eupneica, sudoreica, com livedo e mal perfundida. Os pulsos estão\nsimétricos, as bulhas cardíacas são normofonéticas, mas a paciente apresenta taquicardia e um\nsopro sistólico. O exame abdominal revela dor à palpação na região hipogástrica. Além disso, foram\nidentificadas equimoses em diferentes estágios de evolução em seu tórax e abdome. Quando\nquestionada sobre as lesões equimóticas, Clara começa a chorar e pede para não abordar mais o\nassunto. Tendo como base o caso acima, a política nacional de humanização, os atributos e\nfunções da atenção primária e conhecimentos correlatos, julgue o item a seguir. Se, durante a\ninternação hospitalar, Clara relatar violência sexual, os profissionais de saúde devem abordar a\nquestão com acolhimento, discrição e direcionamento para definição de conduta apenas na medida\nem que a paciente queira discutir o assunto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352342","number":"352342","sourceNumber":"352342","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Clara, uma adolescente de 16 anos, comparece à unidade básica de saúde (UBS) em\nbusca de atendimento médico. Na recepção,\no atendente responsável pelo acolhimento verifica o\nendereço de Clara, confirma que ela reside na área de abrangência da UBS e a encaminha para a\nsala da equipe de saúde da família de sua área. Lá, ela é atendida por uma enfermeira da equipe,\nque, após coletar informações sobre a queixa e sua duração, bem como aferir os sinais vitais,\nreconhece sinais de gravidade. Diante disso, a enfermeira aloca a paciente em uma maca na sala\nde medicação e chama imediatamente o médico da equipe, que a atende prontamente. Clara relata\nque está sentindo dor na região hipogástrica e disúria há cerca de três dias, com uma piora\ngradual. Ela teve calafrios durante a última noite, mas não percebeu que poderia estar com febre. A\npaciente está mais preocupada com as dores e com um atraso menstrual. Ela não consegue\nfornecer a data da última menstruação, mas acredita que tenha ocorrido antes do nascimento de\nseu irmão, que hoje tem três meses. Ao realizar o exame físico, a equipe de saúde observa que\nClara está sonolenta, febril, eupneica, sudoreica, com livedo e mal perfundida. Os pulsos estão\nsimétricos, as bulhas cardíacas são normofonéticas, mas a paciente apresenta taquicardia e um\nsopro sistólico. O exame abdominal revela dor à palpação na região hipogástrica. Além disso, foram\nidentificadas equimoses em diferentes estágios de evolução em seu tórax e abdome. Quando\nquestionada sobre as lesões equimóticas, Clara começa a chorar e pede para não abordar mais o\nassunto. Tendo como base o caso acima, a política nacional de humanização, os atributos e\nfunções da atenção primária e conhecimentos correlatos, julgue o item a seguir. Uma vez\nconfirmada a gravidez de Clara, mesmo que tenha sido resultado de violência sexual, ela não tem\ndireito ao aborto legal devido à idade gestacional, que já ultrapassa as 12 semanas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-334902","number":"334902","sourceNumber":"334902","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao exame a fresco e à coloração por Gram da secreção vaginal, no\ncontexto de caso clínico de vulvovaginite, assinale a alternativa correta.","options":{"A":"A identificação de leveduras e (ou) pseudo-hifas no exame a fresco favorece o diagnóstico de\ntricomoníase.","B":"A presença de micro-organismos flagelados no exame a fresco favorece o diagnóstico de\ncandidíase vulvovaginal.","C":"Na coloração pelo Gram, a presença de bacilos Gram-negativos fusiformes é sugestiva de\nMobiluncus spp.","D":"A identificação de ?clue cells?, ou ce?lulas alvo, no exame a fresco é altamente preditiva da\npresença de vaginose citolítica.","E":"O índice de Nugent pode ser utilizado na investigação de vulvovaginites e tem como objetivo\naveriguar a possibilidade de candidíase vulvovaginal, a partir de uma gradação em cruzes da\npresença de leveduras e pseudo-hifas por campo de 100 x."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343453","number":"343453","sourceNumber":"343453","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Tricomoníase é causada pelo Trichomonas Vaginalis. É uma doença sexualmente\ntransmissível, cujo risco de ser adquirida é\nde 60% a 80% em intercurso sexual único. Nas\nmulheres, afeta a vulva, a vagina e o colo do útero. A mucosa vaginal pode ficar dolorida, erosada,\ninflamada e com coloração amarelada e espumosa. Essa enfermidade ocorre através de:","options":{"A":"Bactéria.","B":"Protozoário.","C":"Vírus.","D":"Fungo."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343455","number":"343455","sourceNumber":"343455","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao Linfogranuloma Venéreo (LGV), é CORRETO afirmar:","options":{"A":"O agente etiológico é o Haemophilus ducreyi L1, L2 e L3.","B":"A localização preferencial é na genitália interna e tem altíssima prevalência em nosso meio.","C":"O período de incubação é de 20 a 40 dias.","D":"A lesão primária de curta duração se apresenta como ulceração (ferida) ou pápula."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-343462","number":"343462","sourceNumber":"343462","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"ACSN, 26 anos, procura UBS queixando-se de corrimento vaginal profuso, disúria e\ndispareunia. Ao exame especular paredes vaginais e ectocérvice apresentam-se hiperemiadas,\ncom presença de secreção amarelo-esverdeada com pequenas bolhas, além de colo uterino com\n\n?aspecto de morango?. Relata ter múltiplos parceiros sexuais e não usar método de barreira.\nNesse caso, o exame a ser realizado é:","options":{"A":"Exame de secreção vaginal com coloração de Gram; observadas ?células-chave?.","B":"Cultura de secreção vaginal; observado crescimento de Streptococcus Agalactiae.","C":"Bacterioscopia a fresco de secreção vaginal; observados parasitas flagelados com movimentos\npendulares.","D":"Exame a fresco de secreção vaginal com hidróxido de potássio; observadas pseudo-hifas e\nesporos."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-301319","number":"301319","sourceNumber":"301319","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 21 anos de idade procura atendimento na emergência em razão de\ndor em abdome inferior e dois episódios de febre não aferida nas duas últimas semanas.\n\nApresentou agravamento significativo do quadro há um dia, com piora do estado geral.\nAntecedentes: união estável, GOP0, faz uso de\nmétodo contraceptivo hormonal oral e não recorda\na DUM. Relata hábitos fisiológicos inalterados. Ao exame físico, destacam-se temperatura axilar =\n39,1 °C, PA = 112 mmHg X 59 mmHg. FC = 109 bpm e abdome doloroso à palpação, sem dor a\ndescompressão brusca. O exame especular evidencia secreção vaginal abundante, com aspecto\npurulento e odor fétido. Ao toque vaginal, nota-se dor a mobilização do colo uterino e anexos. Na\necografia transvaginal, há presença de pequena quantidade de liquido livre e espesso no fundo de\nsaco de Douglas, sem outras alterações. Acerca desse caso clinico, julgue o item abaixo. A\ndosagem de beta-hCG está dispensada, uma vez que a paciente é usuária de método\ncontraceptivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-301320","number":"301320","sourceNumber":"301320","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 21 anos de idade procura atendimento na emergência em razão de\ndor em abdome inferior e dois episódios de febre não aferida nas duas últimas semanas.\n\nApresentou agravamento significativo do quadro há um dia, com piora do estado geral.\nAntecedentes: união estável, GOP0, faz uso de\nmétodo contraceptivo hormonal oral e não recorda\na DUM. Relata hábitos fisiológicos inalterados. Ao exame físico, destacam-se temperatura axilar =\n39,1 °C, PA = 112 mmHg X 59 mmHg. FC = 109 bpm e abdome doloroso à palpação, sem dor a\ndescompressão brusca. O exame especular evidencia secreção vaginal abundante, com aspecto\npurulento e odor fétido. Ao toque vaginal, nota-se dor a mobilização do colo uterino e anexos. Na\necografia transvaginal, há presença de pequena quantidade de liquido livre e espesso no fundo de\nsaco de Douglas, sem outras alterações. Acerca desse caso clinico, julgue o item abaixo. O\ndiagnóstico é doença inflamatória pélvica, indicando-se internação para antibioticoterapia e\nabordagem cirúrgica para drenagem de abscesso tubo-ovariano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-291468","number":"291468","sourceNumber":"291468","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um paciente de 32 anos de idade vem ao retorno em seu médico de família para\nchecar resultados de sorologias solicitados na\nconsulta anterior. A paciente refere 2 gestações\nprévias, e nega atividade sexual há mais de 1 ano, após seu divórcio. Ao checar os exames, o\nmédico identifica VDRL positivo à diluição de 1:2 (valor de referência: negativo) e o TPHA reagente\n(valor de referência: não reagente), HBsAg negativo, anti-HBc negativo, anti-HCV negativo e\n\nanti-HIV negativo. Ao exame físico, ela não apresenta nenhuma lesão genital ou extragenital. Ela\nafirma que realizou tratamento com penicilina na última gestação há 4 anos (relata 2 injeções em\ncada nádega, em 3 aplicações). O médico checa o prontuário da paciente e identifica o registro da\naplicação de 3 doses de penicilina benzatina (2 400 000 UI a cada dose) durante o último pré-natal.\nDiante do que foi exposto, qual a conduta correta?","options":{"A":"Tratar a paciente com penicilina benzatina 2 400 000 UI, 1 vez por semana, por 3 semanas.","B":"Considerar como cicatriz sorológica devido à comprovação do tratamento prévio com penicilina.","C":"Solicitar um novo teste rápido para confirmar caso de sífilis.","D":"Tratar a paciente com penicilina benzatina 2 400 000 UI em dose única."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-273321","number":"273321","sourceNumber":"273321","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente 19 anos nuligesta com quadro de dor em baixo ventre há 3 dias associado a\nfebre aferida de 39 graus. Refere ainda dispareunia. Ao exame físico apresenta-se em bom estado\ngeral com temperatura axilar de 38º C, FC: 100 bpm, PA 100x60 mmHg, abdome doloroso em\nandar inferior, descompressão brusca dolorosa. Ao exame especular observa-se secreção\namarelada com odor, ao toque doloroso a mobilização uterina. Realizou Ultrassonografia\nTransvaginal com imagem anexial esquerda sugestiva de abscesso com maior diâmetro de 4cm.\n\nAcerca do quadro acima, assinale a alternativa CORRETA:","options":{"A":"Trata-se de doença inflamatória pélvica com necessidade de internação para antibioticoterapia\nvenosa com clindamicina e gentamicina e\nreavaliação em 24 horas.","B":"Trata-se de vaginose bacteriana com tratamento sugerido de metronidazol tópico ou\nmetronidazol oral dose única.","C":"Trata-se de doença inflamatória pélvica sem necessidade de internação para antibioticoterapia,\ncom doxiciclina e azitromicina.","D":"Trata-se de infecção sexualmente transmissível por donovanose com tratamento sugerido de\nciprofloxacino."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-268896","number":"268896","sourceNumber":"268896","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um paciente de 40 anos de idade compareceu à consulta queixando-se de lesões\neritematosas e maculares em tronco,\nmembros superiores, membros inferiores, palmas e plantas,\ncom início há dois meses. Negou uso recente de medicação e qualquer outro sintoma. Apresentou\nsorologia positiva para sífilis e VDRL = 1:1024, PA = 120 mmHg x 80 mmHg, FC = 88 bpm, FR = 20\nirpm e SatO2 = 98%. Acerca desse caso clínico, assinale a alternativa correspondente a outro\nsintoma que se espera encontrar nesse paciente e à conduta adequada para esse caso.","options":{"A":"Alopecia no couro cabeludo (em clareira) e nas porções distais das sobrancelhas. Prescrever\npenicilina benzatina 1.200.000 unidades.","B":"Alopecia no couro cabeludo (em clareira) e nas porções distais das sobrancelhas. Prescrever\npenicilina benzatina 2.400.000 unidades.","C":"Linfadenopatia generalizada. Prescrever penicilina benzatina 4.800.000 unidades.","D":"Linfadenopatia generalizada. Prescrever penicilina benzatina 7.200.000 unidades.","E":"Alopecia no couro cabeludo (em clareira) e nas porções distais das sobrancelhas. Realizar\npunção lombar para avaliar existência de\nneurossífilis; prescrever penicilina cristalina 18 milhões de\nunidades por dia, por 14 dias."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-263356","number":"263356","sourceNumber":"263356","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma gestante com 18 anos de idade e 32 semanas de gestação realizou tratamento\ncom penicilina benzatina para sífilis no final do\nprimeiro trimestre de gestação. Desde então, não\ncompareceu às consultas de pré-natal porque ficou isolada em casa devido à pandemia da\n\nCOVID-19. A paciente, então, retorna com resultado de exames mostrando VDRL com aumento de\nduas diluições em relação ao título anterior.\nNesse caso, a conduta apropriada é","options":{"A":"repetir o VDRL e adotar conduta expectante.","B":"instituir novo tratamento com outro fármaco.","C":"repetir o tratamento com penicilina benzatina.","D":"encaminhar a paciente ao serviço pré-natal de alto risco."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-291492","number":"291492","sourceNumber":"291492","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente usuária de dispositivo intrauterino (DIU) de cobre T380A procurou atendimento\nmédico para dores pélvicas de início agudo.\nRelata dores em pontadas alternadas com cólicas.\n\nRelatou disúria e corrimento vaginal sem odor fétido e transparente associado ao aparecimento de\ndispareunia. Ao exame especular evidenciado secreção cervical mucoide saindo pelo orifício\nexterno do colo uterino. Fio do DIU aparente. Colo fechado. Toque evidenciado colo com\nsensibilidade dolorosa à mobilização. Toque bimanual evidenciado sensibilidade no anexo\nesquerdo. Solicitado ultrassom transvaginal evidenciado formação à esquerda espessada e com\naspecto tortuoso e irregular sugestivo de hidrossalpinge. O provável agente microbiológico e o\ntratamento adequado são, respectivamente,","options":{"A":"Clamídia; azitromicina.","B":"Trichomonas; metronidazol.","C":"Gardnerella; fluconazol.","D":"Treponema; penicilina."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-263373","number":"263373","sourceNumber":"263373","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um homem com 39 anos de idade, previamente hígido, é atendido em centro de saúde\ncom lesão peniana, mal-estar e febre baixa\nhá 5 dias. O paciente nega descarga uretral e nega\nlesões penianas prévias. Não tem parceira sexual estável, tendo relações sexuais desprotegidas\ncom diferentes mulheres esporadicamente. Em seu exame físico, apresenta temperatura axilar =\n37,8 °C e está corado, hidratado e anictérico. Há linfonodos axilares, epitrocleares e inguinais\npalpáveis, pequenos, fibroelásticos. Verifica-se lesão ulcerada e úmida em corpo peniano. O teste\nrápido para sífilis realizado no momento da consulta foi positivo. Não há relato de tratamento com\nantimicrobianos no último ano. Relata que, há cerca de 10 anos, ao tomar penicilina benzatina\nintramuscular para tratar faringite, teve dor no local da aplicação, sem lesões e com remissão\nespontânea. Nesse momento, qual é a conduta correta para esse paciente?","options":{"A":"Prescrever doxiciclina 100 mg, por via oral, de 12 em 12 horas por 15 dias e, após 3 meses,\nrealizar VDRL.","B":"Solicitar FTA-Abs e, se teste for positivo, prescrever doxiciclina 100 mg, por via oral, de 12 em\n12 horas por 30 dias.","C":"Aplicar penicilina benzatina 2,4 milhões UI em dose única, por via intramuscular, e solicitar\nVDRL nessa consulta.","D":"Solicitar VDRL e, se teste for positivo, prescrever penicilina benzatina 2,4 milhões UI por via\nintramuscular, 3 doses, com intervalos de 7 dias."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-268919","number":"268919","sourceNumber":"268919","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de 24 anos de idade, G0P0, sem comorbidades diagnosticadas,\ncompareceu ao pronto-socorro de ginecologia\nreferindo ardência e formigamento em região vulvar,\nhá três dias, acompanhados por \"íngua\" em região inguinal. Relata evolução com surgimento de\nbolhas em grande lábio esquerdo, ardência, no local, ao urinar e dor que dificulta a utilização de\nroupas íntimas. Nega episódios prévios semelhantes. Ao exame, evidenciaram-se múltiplas úlceras\nagrupadas em grande lábio esquerdo, dolorosas, rasas e de fundo limpo. Acerca desse caso clínico\ne considerando os conhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"O agente etiológico da patologia em questão é o Haemophilus ducreyi, e os linfonodos\nenvolvidos podem evoluir para abscessos inguinais com supuração (bubões).","B":"O tratamento da paciente poderia ser realizado com aciclovir 400 mg de oito em oito horas, por 7\na 14 dias.","C":"Deve ser solicitado VDRL para confirmação desse diagnóstico, o qual será considerado positivo\nem caso de títulos maiores que 1:8.","D":"Na possibilidade de uma gestante em trabalho de parto, com bolsa íntegra e presença de lesões\nativas, no canal de parto, causadas pelo agente etiológico em questão, deve-se permitir que o parto\ntranscorra por via vaginal, com posterior administração de vacina e imunoglobulina ao neonato.","E":"Deve ser realizado o tratamento das parcerias sexuais concomitantemente ao tratamento da\npaciente, independentemente da presença, ou não, de lesões ativas pelos parceiros."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-263392","number":"263392","sourceNumber":"263392","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma adolescente com 18 anos de idade chega à Unidade Básica de Saúde com queixa\nde sinusorragia, dispareunia e corrimento\namarelado sem odor e sem prurido. A paciente nega\noutras queixas. Ao realizar exame físico, os resultados foram os seguintes: PA = 120 x 75 mmHg,\npulso = 70 bpm, temperatura axilar = 36,5 °C. Seu abdome está plano, flácido e indolor à palpação.\nEm exame especular, percebe-se corrimento amarelado, sem bolhas e sem grumos presentes na\nvagina e no orifício cervical externo, colo uterino sangrante ao toque e doloroso à mobilização. Seu\npH vaginal está próximo de 4,0 e o teste de Whiff deu negativo. Qual é o provável agente etiológico\ndo quadro clínico apresentado por essa adolescente?","options":{"A":"Candida albicans.","B":"Gardnerella vaginalis.","C":"Trichomonas vaginalis.","D":"Chlamydia trachomatis."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-291520","number":"291520","sourceNumber":"291520","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Um homem de 27 anos de idade, homoafetivo, com atividade sexual ativa e passiva\ncom múltiplos parceiros, ocasionalmente sem uso\nde preservativo, procura a Unidade Básica de\nSaúde com quadro arrastado de dor anorretal e tenesmo retal, associado à descarga anal\nmucopio-sanguinolenta, além de febre, calafrios, cefaleia, mal-estar, mialgias e \"íngua\" à direita.\nSegundo informa, o quadro iniciou-se há cerca de 7 dias. Nega infecções sexualmente\ntransmissíveis recentes, tendo sua última relação sexual não protegida ocorrida 4 semanas antes.\n\nNega ter observado qualquer lesão ulcerada genital ou anal no período. Suas vacinações estão em\ndia, mas nunca recebeu vacina contra o HPV. Ao exame físico, o paciente se apresenta em regular\nestado geral, febril, com presença de adenopatia inguinal supurativa unilateral, à direita, dando\nsaída a secreção purulenta por diversos tratos fistulosos locais; os linfonodos são grandes,\nlocalizados acima e abaixo do ligamento inguinal de Poupard, sendo recobertos por pele inflamada,\nfina e fixa aos planos profundos. Anuscopia revela a saída de secreção piossanguinolenta local,\ncom mucosa hiperemiada, sem úlceras locais, sendo o toque retal muito doloroso. É procedida\npunção de um linfonodo inguinal flutuante, sendo o material aspirado encaminhado para coloração\npelo Gram e pesquisa em campo escuro, que posteriormente não mostraram a presença de bacilos\nGram-negativos agrupados em correntes (tipo \"cardume de peixe\"), nem Treponema pallidum.\n\nMedicado com sintomáticos, o paciente retorna duas semanas após para saber os resultados,\nquando se queixa de ter surgido dificuldade\npara evacuar, exigindo muito esforço. Ao toque retal, é\npalpado um estreitamento concêntrico a cerca de 5 cm da margem anal. A melhor hipótese\ndiagnóstica para o caso e uma forma através da qual, se disponível, poderia ser feito o diagnóstico\ndefinitivo de tal condição são","options":{"A":"carcinoma escamoso de ânus; pesquisa de HPV à biópsia por retossigmoidoscopia.","B":"linfogranuloma venéro; pesquisa por teste de amplificação de ácidos nucleicos no material da\nlesão inguinal.","C":"doença de Crohn; colonoscopia com biópsia das lesões e pesquisa de anticorpo\nanti-Saccharomyces cerevisiae.","D":"sarcoma de Kaposi anorretal; sorologia no sangue com pesquisa anticorpos anti-HHV8."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-266470","number":"266470","sourceNumber":"266470","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A ginecologia infanto-puberal é a área de estudo que abrange os cuidados do sistema\nreprodutor feminino, desde o nascimento até a puberdade. Essa área abarca, por exemplo,\ndistúrbios de diferenciação sexual, sinequias, corrimentos e traumas genitais. A respeito desse\nassunto, julgue o item a seguir. As queixas mais usuais quando do atendimento ginecológico de\ncrianças incluem o corrimento vaginal, cuja causa mais comum, tanto na idade infantil quanto na\nidade adulta, é a candidíase - infecção fúngica desencadeada, entre outros fatores, por higiene\níntima incorreta e uso de roupa íntima de tecido sintético.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-266473","number":"266473","sourceNumber":"266473","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mariana, adolescente de quinze anos de idade e moradora do Sol Nascente (bairro\nperiférico do Distrito Federal), descobriu que\nestava gestante de alguns \"meses de gravidez\", por\nter apresentado, após relação sexual com seu parceiro, sangramento transvaginal de moderada\nquantidade. Como não menstruava havia alguns meses, resolveu procurar uma emergência\nmédica. Quando do seu atendimento, entre os exames solicitados, constava um ?-hcg, que veio\npositivo, com resultado de 50.000 mUi/mL. Já no seguimento gestacional, nos exames de rotina de\n\n3.° trimestre, Mariana apresentou VDRL reagente 1/128, sem apresentar quaisquer sintomas\natípicos. Foi proposto, então, tratamento\ncom penicilina G benzatina 2,4 milhões de UI IM,\nsemanalmente, o que totalizou 3 aplicações (dose final 7,2 milhões de UI IM de penicilina G\nbenzatina). O seu parceiro também foi tratado. A paciente negou novos parceiros sexuais nesse\nintervalo e qualquer lesão cutânea. A respeito desse caso clínico e dos vários aspectos\nrelacionados à obstetrícia, julgue o item a seguir. Se a criança nascer uma semana após a última\ndose do medicamento citado e o VDRL materno intraparto for de 1/32, será possível considerar que\na paciente terá sido adequadamente tratada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-266475","number":"266475","sourceNumber":"266475","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mariana, adolescente de quinze anos de idade e moradora do Sol Nascente (bairro\nperiférico do Distrito Federal), descobriu que\nestava gestante de alguns \"meses de gravidez\", por\nter apresentado, após relação sexual com seu parceiro, sangramento transvaginal de moderada\nquantidade. Como não menstruava havia alguns meses, resolveu procurar uma emergência\nmédica. Quando do seu atendimento, entre os exames solicitados, constava um ?-hcg, que veio\npositivo, com resultado de 50.000 mUi/mL. Já no seguimento gestacional, nos exames de rotina de\n\n3.° trimestre, Mariana apresentou VDRL reagente 1/128, sem apresentar quaisquer sintomas\natípicos. Foi proposto, então, tratamento com\npenicilina G benzatina 2,4 milhões de UI IM,\nsemanalmente, o que totalizou 3 aplicações (dose final 7,2 milhões de UI IM de penicilina G\nbenzatina). O seu parceiro também foi tratado. A paciente negou novos parceiros sexuais nesse\nintervalo e qualquer lesão cutânea. A respeito desse caso clínico e dos vários aspectos\nrelacionados à obstetrícia, julgue o item a seguir. Nessa situação, caso a mãe de Mariana exigisse\nque fosse feito um aborto, com base na alegação de que a filha, pela idade, havia sido estuprada,\nmas Mariana, por sua vez, afirmasse que havia planejado a gravidez e desejava ter a criança, a\nequipe médica, com base na legislação pertinente, deveria manter a gestação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-274661","number":"274661","sourceNumber":"274661","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"As infecções do trato genital inferior são as causas de queixas mais comuns das\npacientes ginecológicas. Dentre elas, estão as\ninfecções vulvares, sendo uma das mais conhecidas\no HPV (papilomavírus humano). Acerca do HPV, é CORRETO afirmar:","options":{"A":"Os sinais e sintomas de verrugas genitais incluem lesões moles, sésseis e coceiras.","B":"As verrugas genitais são geralmente diagnosticadas pela inspeção macroscópica.","C":"A minoria das infecções por HPV é assintomática ou subclínica.","D":"Pacientes grávidas, imunossuprimidas e diabéticas têm risco diminuído."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-274675","number":"274675","sourceNumber":"274675","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A violência não é somente um problema do campo jurídico ou da segurança pública e\nda polícia, mas também é uma preocupação no\ncampo da saúde, como objeto científico e foco de\nprogramas de assistência e prevenção. Quanto ao tema, considerando as orientações da agência\nespecializada das nações unidas, destinada às questões relativas à saúde, a violência se\ncaracteriza como:","options":{"A":"O uso impremeditado da força física ou do poder, real ou em ameaça, contra si próprio, contra\noutra pessoa ou contra um grupo ou uma\ncomunidade, que resulte ou tenha a possibilidade de\nresultar em lesão, morte, dano físico, deficiência de desenvolvimento ou privação.","B":"O uso intencional da força física ou do poder, real ou em ameaça, contra si próprio, contra outra\npessoa ou contra um grupo ou uma comunidade, que resulte ou tenha a possibilidade de resultar\nem lesão, morte, dano psicológico, deficiência de desenvolvimento ou privação.","C":"O uso intencional da força física ou do poder, real ou em ameaça, contra si próprio, contra outra\npessoa ou contra apenas um determinado grupo, que resulte ou tenha a possibilidade de resultar\nem lesão, morte, dano físico, deficiência de desenvolvimento ou privação.","D":"O uso impremeditado da força física ou do poder, real ou em ameaça, contra si próprio, contra\noutra pessoa ou contra um grupo ou uma\ncomunidade, que resulte ou tenha a possibilidade de\nresultar em lesão, morte, dano psicológico, deficiência de desenvolvimento ou privação."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-274676","number":"274676","sourceNumber":"274676","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A violência doméstica que ocorre, sobretudo, no espaço privado da casa e das relações\nafetivo-familiares foi, por muito tempo, entendida como uma espécie de ?destino? de muitas\nmulheres. Quanto a esse modo de pensar, é CORRETO afirmar:","options":{"A":"Evidencia que os impactos da violência na saúde das mulheres são de várias ordens, além de\nnumerosos, refletindo negativamente na saúde geral, sexual, reprodutiva e mental.","B":"Evita que a violência seja vista como parte inexorável das relações entre homens e mulheres.","C":"Banaliza a violência, tornando-a uma situação comum e natural.","D":"Estabelece que a violência é um contexto que traz adoecimentos, representando situações de\nalto risco e caracterizando as mulheres como uma população vulnerável nesse aspecto."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-244493","number":"244493","sourceNumber":"244493","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 32 anos de idade, G1P0, idade gestacional de 37 semanas e 3 dias,\nportadora de HIV (não sabe informar carga\nviral) procurou o pronto-socorro por contrações uterinas.\nAo exame físico, mostrou-se em bom estado geral, anictérica, acianótica, normocorada. BCF = 150\nbpm. Presença de dinâmica uterina de duas contrações de 50 segundos a cada 10 minutos. Toque\nvaginal com colo fechado, longo, grosso, posterior, bolsa íntegra, apresentação cefálica. De acordo\ncom esse caso clínico, quanto à via de parto, a melhor conduta seria:","options":{"A":"Indicar de cesariana imediata pelo risco de transmissão vertical.","B":"Iniciar método Krause para estimular parto vaginal.","C":"Iniciar indução de parto com misoprostol.","D":"Estimular parto vaginal com uso de ocitocina.","E":"Estimular parto vaginal com episiotomia e fórceps de alívio para antecipar o parto, pelo maior\nrisco de transmissão vertical."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-227431","number":"227431","sourceNumber":"227431","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de vinte e cinco anos de idade consultou-se com ginecologista por\napresentar lesão vulvar que, segundo ela,\nhavia surgido cerca de seis dias após uma relação\nsexual desprotegida. No exame físico, ela apresentava lesão ulcerada localizada na face interna\ndos grandes lábios, dolorosa, sangrante, com bordas irregulares, eritematosas, com fundo\npurulento e de odor fétido. Considerando o precedente caso clínico, julgue o item subsecutivo. O\ndebridamento cirúrgico de úlceras vulvares de origem infecciosa melhora a eficácia do tratamento\nantimicrobiano.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-230608","number":"230608","sourceNumber":"230608","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A vacina tetravalente para HPV NÃO apresenta cobertura para o subtipo:","options":{"A":"6.","B":"11.","C":"16.","D":"33."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-227432","number":"227432","sourceNumber":"227432","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente de vinte e cinco anos de idade consultou-se com ginecologista por\napresentar lesão vulvar que, segundo ela,\nhavia surgido cerca de seis dias após uma relação\nsexual desprotegida. No exame físico, ela apresentava lesão ulcerada localizada na face interna\ndos grandes lábios, dolorosa, sangrante, com bordas irregulares, eritematosas, com fundo\npurulento e de odor fétido. Considerando o precedente caso clínico, julgue o item subsecutivo. A\nazitromicina e a ceftriaxona são opções de tratamento indicadas para a paciente do caso\napresentado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-230610","number":"230610","sourceNumber":"230610","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Faz parte dos critérios maiores para o diagnóstico de Doença Inflamatória Pélvica\nsegundo o Ministério da Saúde:","options":{"A":"massa pélvica.","B":"conteúdo vaginal ou secreção endocervical anormal.","C":"dor a mobilização do colo uterino.","D":"leucocitose em sangue periférico."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-227438","number":"227438","sourceNumber":"227438","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação a patologias ginecológicas benignas, julgue o próximo item. Nos casos de\ndoença inflamatória pélvica, massas anexiais\nhipervascularizadas identificadas por doppler\napresentam maior probabilidade de resposta ao tratamento antimicrobiano que lesões pouco\nvascularizadas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-230621","number":"230621","sourceNumber":"230621","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Ocorre aumento de casos de sífilis que pode ser atribuído, em parte, à expansão da\ncobertura de testagem, com a ampliação do uso de testes rápidos e redução do uso de\npreservativo. Somente podemos aceitar como CORRETA a alternativa:","options":{"A":"É importante ressaltar que, nos últimos anos, tem-se observado um aumento constante no\nnúmero de casos de sífilis em gestantes, sífilis congênita e sífilis adquirida.","B":"Ocorre uma resistência dos profissionais de saúde à administração da penicilina na Atenção\nHospitalar.","C":"Ocorreu uma maior oferta mundial de penicilina.","D":"Ocorreu piora do sistema de vigilância, refletindo-se no aumento de casos notificados."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-227447","number":"227447","sourceNumber":"227447","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis,\njulgue o item que se segue. Situação hipotética: Um casal\nheterossexual compareceu a consultório médico para uma avaliação pré-concepcional. O médico\nsolicitou a realização de teste rápido para sífilis. Tanto o homem quanto a mulher estavam\nassintomáticos e informaram que nunca tinham sido submetidos a esse tipo de exame. O resultado\npara ambos foi positivo, e o teste VDRL revelou a seguinte titulação: 1/64 (homem) e 1/32 (mulher).\nAssertiva: Nessa situação, o casal deve ser tratado com benzilpenicilina benzatina IM na dose de\n2,4 milhões UI (1,2 milhão UI em cada glúteo) uma vez por semana durante duas semanas. Após\nesse período de tratamento, o casal deve realizar novo teste não treponêmico, para monitoramento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-227457","number":"227457","sourceNumber":"227457","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A respeito do cuidado à saúde da mulher na APS, julgue o item subsecutivo. No\natendimento a mulher maior de idade que\ntenha sido vítima de violência sexual, o médico da família\ne comunidade deve atender às seguintes etapas de atendimento: acolher a vítima; registrar a\nhistória; fazer o exame físico; realizar testes rápidos; prescrever contracepção de emergência com\nlevonorgestrel; realizar quimioprofilaxia para IST; preencher a ficha de notificação compulsória de\nviolências; registrar ocorrência na delegacia especializada no atendimento à mulher (DEAM) mais\npróxima da UBS, nos termos da Lei Maria da Penha; e propor acompanhamento social e\npsicológico à vítima.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-227458","number":"227458","sourceNumber":"227458","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A respeito do cuidado à saúde da mulher na APS, julgue o item subsecutivo. Segundo a\nlegislação vigente, o abortamento não será considerado crime se for praticado, com o\nconsentimento da mulher ou, se incapaz, de seu representante legal, por médico nos casos em que\na gestação for resultante de estupro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-206123","number":"206123","sourceNumber":"206123","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Ao adicionar hidróxido de potássio a 10% ao corrimento vaginal, a liberação de odor de\npeixe podre ocorre devido à liberação de:","options":{"A":"Amônia.","B":"Cloreto de sódio.","C":"Cadaverina e putrescina.","D":"Ureia."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-206092","number":"206092","sourceNumber":"206092","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"As úlceras genitais representam síndrome clínica produzida por agentes infecciosos\nsexualmente transmissíveis e que se manifestam como lesões ulcerativas erosivas. Indique a\nalternativa INCORRETA a respeito desse assunto.","options":{"A":"Podem ser precedidas ou não por pústulas e/ou vesículas.","B":"Podem ser acompanhadas ou não de dor, ardor, prurido, drenagem de material mucopurulento,\nsangramento e linfadenopatia regional.","C":"Os agentes podem ser encontrados isoladamente ou em associação em uma mesma lesão,\ncomo, por exemplo, úlcera genital por T. pallidum e HSV-2.","D":"A presença de úlcera genital não está associada a elevado risco de transmissão e aquisição do\nHIV."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-206101","number":"206101","sourceNumber":"206101","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Diagnóstico Laboratorial de Doenças Sexualmente Transmissíveis apresenta diversas\ncaracterísticas e condutas. Aponte a que se mostra INCORRETA.","options":{"A":"Se o resultado mostrar infecção por algum desses patógenos, o tratamento apropriado deve ser\ninstituído, mas não se deve referir às parcerias sexuais para avaliação e tratamento.","B":"A cultura para a N. gonorrhoeae em meio seletivo de Thayer-Martin ou similar é fundamental, em\nespecial, para estudos-sentinela, em razão da possibilidade de realizar testes de susceptibilidade\naos antimicrobianos.","C":"A imunofluorescência direta tem leitura subjetiva exige microscópio e profissionais bem\ntreinados, sendo que a sensibilidade está aquém do esperado.","D":"Se nenhum dos critérios acima estiver presente, a pesquisa de N. gonorrhoeae e C. trachomatis\npode ser realizada, métodos de biologia\nmolecular que têm elevada sensibilidade e especificidade\nquando comparados com os demais e podem identificar essas infecções associadas."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-212050","number":"212050","sourceNumber":"212050","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Julgue o item a seguir, relativo ao pré-natal, parto e puerpério. A droga de escolha para\no tratamento da sífilis na gravidez é a\npenicilina benzatina nas seguintes doses: 2.400.000 UI em\ndose única na condição primária, 4.800.000 UI dividida em duas doses com intervalo semanal na\nsífilis secundária e 7.200.000 UI dividida em três doses com intervalos semanais na lues terciária.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-212064","number":"212064","sourceNumber":"212064","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Julgue o item a seguir, relativo ao pré-natal, parto e puerpério. Nos casos de gravidez\ndecorrente de estupro, a mulher terá direito a atendimento especial nos hospitais e serviços de\nsaúde autorizados e poderá solicitar a interrupção legal da gravidez sem a obrigatoriedade de\nformalização de boletim de ocorrência policial, exame de corpo de delito ou autorização judicial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-206137","number":"206137","sourceNumber":"206137","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Raramente, na Uretrite gonocócica ocorre queixa de sensibilidade aumentada no\nepidídimo e queixas compatíveis com balanite (dor, prurido, hiperemia da região prepucial,\ndescamação da mucosa e, em alguns casos, material purulento e de odor desagradável no\nprepúcio). Podemos apenas considerar ERRADO o seguinte item. Aponte-o.","options":{"A":"O período de incubação é cerca de dez dias após a infecção.","B":"O corrimento mucopurulento ou purulento é frequente.","C":"As complicações no homem ocorrem por infecção ascendente a partir da uretra (orqui-\n\n-epididimite e prostatite).","D":"A infecção retal é geralmente assintomática, mas pode causar corrimento retal (12%) ou dor/\ndesconforto perianal ou anal (7%)."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-206141","number":"206141","sourceNumber":"206141","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando os métodos diagnósticos para uretrites, o diagnóstico das uretrites pode\nser realizado com base em um dos seguintes\nsinais e sintomas ou achados laboratoriais. Aponte o\nitem que está INCORRETO, dentre os listados abaixo.","options":{"A":"Drenagem purulenta ou mucopurulenta ao exame físico.","B":"Bacterioscopia pela coloração Gram de secreção uretral, apresentando > 5 polimorfonucleares\n(PMN) em lâmina de imersão.","C":"A coloração de Gram é preferível por se tratar de método rápido para o diagnóstico de gonorreia\nem homens sintomáticos com corrimento uretral.","D":"A infecção gonocócica é estabelecida pela presença de diplococos Gram-negativos\nintracelulares em leucócitos mononucleares\n\napenas."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177273","number":"177273","sourceNumber":"177273","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 28 anos de idade, do sexo feminino, comparece ao pronto-socorro de\nginecologia com queixa de secreção vaginal diferente do habitual. Refere início da atividade sexual\naos 15 anos de idade, com 10 parceiros desde então. Não possui parceiro fixo atualmente e faz\nuso de preservativo de forma eventual. Faz uso diário de absorvente íntimo, em razão da presença,\nde secreção vaginal, que incomoda. Ao exame físico, foi evidenciada secreção branca grumosa,\ncom intensa hiperemia das paredes vaginais. A respeito do caso clínico, assinale a alternativa\ncorreta.","options":{"A":"A paciente deve ser tratada com creme vaginal de metronidazol.","B":"Se fosse realizada lâmina a fresco da secreção vaginal, o resultado seria a visualização de\npseudo-hifas ao microscópio.","C":"O tratamento profilático para casos de repetições e feito com azitromicina, via oral, uma vez por\nsemana.","D":"O teste de Whiff positivo confirma o diagnóstico da paciente.","E":"Casos semelhantes a esse devem contar com a presença do parceiro no tratamento, por se\ntratar de doença de transmissão exclusivamente sexual."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177230","number":"177230","sourceNumber":"177230","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 28 anos de idade, do sexo feminino, comparece ao pronto-socorro de\nginecologia com queixa de secreção vaginal diferente do habitual. Refere início da atividade sexual\naos 15 anos de idade, com 10 parceiros desde então. Não possui parceiro fixo atualmente e faz\nuso de preservativo de forma eventual. Faz uso diário de absorvente íntimo, em razão da presença\nde secreção vaginal, que incomoda. Ao exame físico, foi evidenciada secreção branca grumosa,\ncom intensa hiperemia das paredes vaginais. Decorridas 3 semanas, a paciente retoma, desta vez\ncom queixa de lesão vulvar, com aspecto ulcerado. Ela nega trauma local. A úlcera é única, indolor,\ncom linfonodomegalia ipsilateral, que drena espontaneamente em múltiplos orifícios. Com base no\nexposto, assinale a alternativa CORRETA.","options":{"A":"O tratamento ideal deve ser feito com penicilina cristalina.","B":"A lesão tem diagnóstico diferencial de cancro duro. A diferença é que, nessa última possibilidade\ndiagnóstica, não há linfonodomegalia com fistulização e o VDRL se encontra negativo.","C":"O diagnóstico mais provável é cancro mole.","D":"Pacientes com esse tipo de úlcera genital têm obrigatoriamente que fazer tratamento\nconcomitante com o parceiro, já que a referida\nenfermidade sempre é considerada uma doença de\ntransmissão sexual.","E":"Essa é uma das formas de apresentação da infecção por Haemophilus ducreyi."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-177258","number":"177258","sourceNumber":"177258","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 22 anos de idade, do sexo masculino, apresenta-se em consulta sem hora\nmarcada em posto de Saúde da Família, com queixas de ardência uretral e secreção uretral\nesbranquiçada há cerca de 2 semanas. Ele não apresenta outras queixas. Refere comportamento\nsexual com várias parceiras no último ano, com uso infrequente de preservativo. A respeito do\nreferido caso, assinale a alternativa correta.","options":{"A":"O tratamento deve ser realizado com eiprofloxacino + azitromicina.","B":"O diagnóstico etiológico é de gonorreia.","C":"As parceiras do paciente devem ser imediatamente informadas a respeito se sua exposição de\nrisco pelo serviço de saúde e convocadas para tratamento.","D":"O exame da região genital é dispensável nesse caso.","E":"Deve-se oferecer teste rápido para sífilis e HIV ao paciente."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183860","number":"183860","sourceNumber":"183860","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao atendimento a vitima de violência sexual e à vacinação de gestante\ncontra hepatite B, julgue o item a seguir. A\nabordagem emergencial ás vítimas de violência sexual\ninclui a profilaxia para a infecção por papilomavirose humana (HPV).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183865","number":"183865","sourceNumber":"183865","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao atendimento a vitima de violência sexual e à vacinação de gestante\ncontra hepatite B, julgue o item a seguir. Tanto\na vacinação contra a hepatite B (IGHAHB) são\ncontraindicadas à gestante, esteja ela em qualquer idade gestacional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183878","number":"183878","sourceNumber":"183878","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao atendimento a vitima de violência sexual e à vacinação de gestante\ncontra hepatite B, julgue o item a seguir. Os\npilares da atenção em emergência a vitima de violência\nsexual incluem: obtenção do relato detalhado de episódio, notificação do caso, avaliação clínica\ncompleta, profilaxia contra infecções sexualmente transmissíveis (IST), não revitimização e\ncontracepção de emergência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-175168","number":"175168","sourceNumber":"175168","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São características das Vulvovaginites:","options":{"A":"A melhora ao menstruar é característica de vaginose bacteriana.","B":"As hifas são encontradas na infecção por gonococo.","C":"Secreção com odor fétido é encontrado nos casos de candidiase.","D":"As Clue cells são encontradas na infecção por gardnerella."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183892","number":"183892","sourceNumber":"183892","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao atendimento a vitima de violência sexual e à vacinação de gestante\ncontra hepatite B, julgue o item a seguir. Em\nobediência ao príncipio bioético da autonomia da\npaciente, o médico não pode se negar a realizar a interrupção da gestação de uma jovem de\nquinze anos de idade vítima de violência sexual que, além de preencher os critérios para a\ninterrupção legal da gestação, tenha a anuência de seus representantes legais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183902","number":"183902","sourceNumber":"183902","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao atendimento a vitima de violência sexual e à vacinação de gestante\ncontra hepatite B, julgue o item a seguir. Na\nprofilaxia de HIV, é preferível o esquema de sete dias\nde uso da zidovudina (AZT)/ lamivudina (3TC), na apresentação de dose fixa combinada, associado\nao tenofovir (TDF).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183958","number":"183958","sourceNumber":"183958","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao tratamento de agravos resultantes de violência sexual, julgue o item a\nseguir. É facultativa a notificação de casos suspeitos ou confirmados de violência sexual e\ndoméstica, devendo-se respeitar a vontade da vítima de permanecer anônima.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-183962","number":"183962","sourceNumber":"183962","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao tratamento de agravos resultantes de violência sexual, julgue o item a\nseguir. O atendimento à vítima de violência sexual deve basear-se no respeito à diversidade,\nprimando-se pelo acolhimento e pela humanização, sem quaisquer julgamentos morais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-157992","number":"157992","sourceNumber":"157992","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Lactente, sexo feminino, de 1 ano de idade, é levada à consulta pela mãe, com\nresultado de parcial de urina coletado no dia anterior, o qual evidencia discreta leucocitúria e\nhematúria microscópica. Nesse caso clínico, a conduta mais adequada é a seguinte:","options":{"A":"Solicitar pesquisa de BAAR na urina.","B":"Solicitar pesquisa de dismorfismo eritrocitário na urina.","C":"Solicitar urocultura e iniciar tratamento para infecção do trato urinário.","D":"Solicitar ultrassonografia do aparelho urinário para afastar litíase.","E":"Afastar e (ou) tratar vulvovaginite e, posteriormente, repetir parcial de urina."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-157976","number":"157976","sourceNumber":"157976","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 30 anos de idade, com parceiro único, queixa-se de secreção vaginal com\nodor fétido, esverdeada. Ao exame físico, foi identificada secreção vaginal verde bolhosa, com\nhiperemia de paredes vaginais e \"colo em framboesa\". Nesse caso clínico, o tratamento envolve:","options":{"A":"Fluconazol via oral para o casal, associado a creme vaginal de miconazol.","B":"Uso local de lactobacilos e orientação quanto a hábitos de higiene.","C":"Creme vaginal com associação de metronidazol e miconazol.","D":"Metronidazol creme vaginal apenas para a paciente, já que não se trata de infecção de\ntransmissão sexual.","E":"Metronidazol via oral para o casal."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-158051","number":"158051","sourceNumber":"158051","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 21 anos de idade, estudante de medicina, comparece a consulta por\nsurgimento de tumoração em região inguinal\nhá cerca de duas semanas, com dor e eritema na\ntumoração e febre de 38ºC há dois dias. O paciente refere que apresenta aventuras sexuais\nfrequentes e que, eventualmente, não usa preservativo. Ao ser questionado quanto a esse\ncomportamento, justificou que \"DST não é doença, é experiência de vida\". Nega que tenha notado\nqualquer lesão genital ou apresentado secreção uretral. Não apresenta comorbidades. Foi\nrealizado USG de região inguinal, que demonstrou linfonodomegalia inguinal unilateral. O teste\nrápido para sífilis apresentou resultado negativo. Considerando esse caso clínico, o provável\ndiagnóstico desse paciente e as Diretrizes Terapêuticas do Ministério da Saúde, assinale a\nalternativa que indica o medicamento correto para o tratamento.","options":{"A":"Penicilina G benzatina.","B":"Doxiciclina.","C":"Ceftriaxone.","D":"Metronidazol.","E":"Azitromicina."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-154512","number":"154512","sourceNumber":"154512","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Gestante de 9 semanas comparece à sua primeira consulta de pré-natal sem queixas.\nA sorologia para sífilis revela VDRL 1:64 e\nFTA-Abs positivo. A paciente refere ser alérgica a\npenicilina e nunca ter tratado para sífilis. É CORRETO afirmar que:","options":{"A":"A transmissão vertical da sífilis está relacionada a diversas complicações como crescimento\nuterino restrito, óbito fetal e anomalias\ncongênita, embora tenha um melhor prognóstico quanro\nmais recente for a infecção materna.","B":"Os testes treponêmicos devem ser solicitados no primeiro e terceiro semestre de gestação e\nconstituem o método de escolha para\n\nrastreio da sífilis.","C":"No caso acima está indicado o tratamento com estearato de eritromicina, macrolídeo com\neficácia semelhante à da penicilina.","D":"A infecção congênita por sífilis deve ser pesquisada no recém-nascido o mais rápido possível,\nsendo confirmada infecção caso o VRDL e o FTA-Abs\nIgG sejam positivos.","E":"Para que o tratamento para sífilis seja considerado adequado a gestante deve ter sido tratada,\nnecessariamente, com penicilina."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-168468","number":"168468","sourceNumber":"168468","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher com 25 anos de idade procura a Unidade Básica de Saúde com queixa de\ncorrimento vaginal, fluído, de coloração esbranquiçada e odor forte há 15 dias. Ao exame\nespecular, observa-se conteúdo vaginal esbranquiçado e bolhoso. Ao realizar a avaliação do pH\nvaginal com fita, obteve-se valor de 6,5. O teste das aminas apresentou resultado positivo. Pelos\nachados evidenciados, conclui-se que o diagnóstico correto é","options":{"A":"cervicite por HPV.","B":"vaginose citolitica.","C":"vaginose bacteriana.","D":"candidíase vulvovaginal."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-168491","number":"168491","sourceNumber":"168491","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher com 28 anos de idade, casada, Gesta 2 Para 2, em uso irregular de\npreservativo, encontra-se assintomática, mas procura atendimento na Unidade Básica de Saúde,\nrelatando que seu esposo apresentou quadro de uretrite há 2 semanas e que foi tratado com\nceftriaxona e azitromicina. Ao exame especular da paciente, observa-se colo uterino epitelizado\ncom conteúdo vaginal de aspecto mucoide, sem odor fétido. Para essa paciente, indica-se","options":{"A":"tratamento com ceftriaxona e azitromicina.","B":"coleta de material endocervical para cultura.","C":"coleta de conteúdo vaginal para bacterioscopia pelo método de Gram.","D":"conduta expectante e convocação do parceiro para orientação ao casal."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-159527","number":"159527","sourceNumber":"159527","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"No que se refere às intercorrências clínicas da gestação, julgue o item a seguir. Durante\no trabalho de parto e no parto de gestantes HIV\npositivas, a terapia antirretroviral, a cesariana\neletiva e a manutenção das membranas íntegras pelo maior tempo possível são fatores de\nproteção contra a infecção vertical.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-159532","number":"159532","sourceNumber":"159532","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma jovem de vinte e um anos de idade, foi vítima de violência sexual e buscou\nimediatamente atendimento em pronto-socorro;\ncontudo, um ano e dois meses após o ocorrido,\ndesenvolveu lesões verrucosas características de condiloma acuminado. Considerando esse caso\nclínico, julgue o item a seguir. A infecção desenvolvida pela referida paciente não guarda relação\ncom o episódio de violência ocorrido.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-159528","number":"159528","sourceNumber":"159528","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Em um dia normal de trabalho, médicos de família e comunidade atendem a muitos\ncasos diferentes. Certa manhã, determinado\nmédico atendeu a quinze pacientes, entre os quais se\nencontravam os seguintes: (1) uma criança de cinco anos de idade com suspeita de abuso sexual,\ntrazida pela mãe; (2) um idoso de sessenta e seis anos de idade, tabagista, com Diabetes Melito\n(DM) e Hipertensão Arterial Sistêmica (HAS); (3) uma mulher de vinte e três anos de idade,\nestudante universitária, que não tomava banho havia uma semana; (4) um bebê de uma semana de\nvida (5) e sua mãe, puérpera, para consulta normal; (6) um adolescente de dezessete anos de\nidade, com rolha de cera; (7) uma idosa de setenta e um anos de idade, com Diabetes Melito (DM)\ne obesa com úlcera no membro inferior esquerdo, (8) e sua filha, e cuidadora, de quarenta e nove\nanos de idade, que não dormia regularmente havia um mês. Considerando esses casos clínicos,\njulgue o item a seguir. Com relação ao caso 1, considerando tratar-se de mera suspeita de violência\npor abuso sexual, sem nenhuma comprovação, o médico agirá corretamente ao decidir não fazer\nnotificação.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-129017","number":"129017","sourceNumber":"129017","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A vaginose bacteriana é caracterizada pelo desequilíbrio da flora vaginal normal devido\nao aumento exagerado de bactérias, em especial\nas anaeróbias, associado à ausência ou redução\nacentuada dos lactobacilos acidófilos, que são os agentes predominantes na vagina normal. Não se\ntrata de infecção por transmissão sexual, mas pode ser desencadeada, em mulheres predispostas,\npor contato com sêmen, que possui pH elevado. Considerando essas informações, assinale a\nalternativa que apresenta o micro-organismo mais comumente envolvido nesses casos.","options":{"A":"Haemophilus ducreyi","B":"Klebsiella granulomatis","C":"Chlamydia trachomatis","D":"Treponema pallidum","E":"Gardnerella vaginalis"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-133986","number":"133986","sourceNumber":"133986","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"No que se refere à infecção pelo Vírus da Imunodeficiência Humana (HIV) na gestação,\nassinale a alternativa CORRETA:","options":{"A":"São critérios indicativos de cesárea eletiva na gestante infectada pelo HIV: carga viral acima de\n500 cópias/ml, gestante fora de trabalho de\nparto, bolsa íntegra e idade gestacional acima de 38\nsemanas.","B":"Tanto na cesárea eletiva quanto no parto normal da gestante infectada pelo HIV, a zidovudina\nintraparto deve ser administrada por via endovenosa, na dose de 2 mg/kg de peso (dose de\nataque), seguida de duas doses de manutenção (1 mg/kg de peso), com intervalo de uma hora\nentre cada uma.","C":"A quase totalidade dos casos de transmissão vertical do HIV ocorrem durante o parto e durante\na amamentação natural, sendo raros os casos de\ntransmissão vertical do HIV durante a gestação.","D":"O teste de diagnóstico rápido da infecção HIV, realizado no momento em que a gestante chega\nà maternidade em trabalho de parto, permite que a\ngestante não testada no pré-natal tenha acesso\nà zidovudina endovenosa durante o trabalho de parto.","E":"A suspensão do aleitamento natural e sua substituição por aleitamento artificial não deve ser\nfeito apenas com o teste de diagnóstico rápido da infecção HIV, realizado no momento em que a\ngestante chega à maternidade em trabalho de parto, devendo-se, para tal conduta, sempre\naguardar os testes definitivos."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-134001","number":"134001","sourceNumber":"134001","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 28 anos de idade, com vida sexual ativa, nuligesta, com história de\ninfertilidade primária, chega ao ambulatório de\nginecologia com queixa de dor pélvica. Ao exame\nclínico, a paciente encontra-se febril, abdome sem sinais de irritação peritoneal, exame especular\ncom exteriorização de muco purulento pela cérvice uterina e toque vaginal com dor hipogástrica,\ndor à mobilização do colo uterino e dor à palpação de anexos. Foi submetida a ultrassonografia\ntransvaginal, que não evidenciou alterações. Considerando esse caso clínico hipotético, assinale a\nalternativa que apresenta corretamente a principal hipótese diagnóstica e os agentes etiológicos\nprimários envolvidos no quadro.","options":{"A":"Hipótese diagnóstica: doença inflamatória pélvica. Agente etiológicos: Gardnerella vaginalis e\nStreptococcus agalactiae.","B":"Hipótese diagnóstica: vaginose bacteriana. Agente etiológicos: gardnerella vaginalis e\nStreptococcus agalactiae.","C":"Hipótese diagnóstica: abscesso tubo-ovariano. Agente etiológicos: Gardnerella vaginalis e\nStreptococcus agalactiae.","D":"Hipótese diagnóstica: vaginose bacteriana. Agente etiológicos: Neisseria gonorrhoeae e\nChlamydia trachomatis.","E":"Hipótese diagnóstica: doença inflamatória pélvica. Agente etiológicos: Neisseria gonorrhoeae e\nChlamydia trachomatis."},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-133934","number":"133934","sourceNumber":"133934","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A respeito do tratamento da sífilis, assinale a alternativa correta.","options":{"A":"O tratamento da neurossífilis deve ser feito com penicilina benzatina 7,2 milhões de UI (dose\ntotal), IM, em três doses semanais de 2,4 milhões de UI cada.","B":"O tratamento da sífilis terciária ou latente tardia deve ser feito com penicilina cristalina 3 a\n4\nmilhões de UI, EV, a cada quatro horas, ou por infusão contínua, no total de 18 a 24 milhões de\nUI/dia por 10 a 14 dias.","C":"A droga de primeira linha para o tratamento da sífilis atualmente não é mais a penicilina, mas\nsim o estearato de eritromicina 500 mg de VO, a cada seis horas, durante 15 a 30 dias.","D":"Nos casos de sífilis secundária, deve-se utilizar penicilina benzatina 4,8 milhões de UI (dose\ntotal), IM, em duas doses semanais de 2,4 milhões de UI cada.","E":"Para o tratamento da sífilis latente com menos de um ano de evolução, preconiza-se penicilina\nbenzatina 2,4 milhões de UI, IM, em dose única."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-111283","number":"111283","sourceNumber":"111283","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente jovem, nulípara, com vida sexual ativa, refere a febre acima de 38,5° C,\ncorrimento vaginal mucopurulento e dor pélvica intensa. Ao exame ginecológico, apresenta dor à\nmobilização do colo uterino e palpa-se massa pélvica. O exame ultrassonográfico revelou imagem\nsugestiva de abscesso tubo-ovariano medindo 6 cm. A conduta mais adequada neste caso é:","options":{"A":"Antibioticoterapia de amplo espectro ambulatorial.","B":"Antibioticoterapia de amplo espectro endovenosa hospitalar.","C":"Aspiração guiada por ultra-sonografia.","D":"Exploração cirúrgica.","E":"Tratamento antiinflamatório."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-111298","number":"111298","sourceNumber":"111298","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Ginecologista no centro de saúde da periferia atendeu a três pacientes X, Y e Z. Os\nachados, entre sinais e sintomas, dessas\ntrês pacientes estão relacionados a seguir: (X) Corrimento\nespesso e aderente, dispareunia, cultura em meio de Nickerson; (Y) Colo de aspecto tigróide ao\nexame especular, prurido e dispareunia, cultura em meio de Diamond; (Z) Corrimento fluido e\nhomogêneo, 50% assintomáticas, diagnóstico quando 3 dos 4 critérios de Amsel presentes. Diantes\ndo exposto, analise a alternativa que apresenta os diagnósticos de X, Y e Z, respectivamente.","options":{"A":"Infecção por gonococo, tricomoníase, infecção por clamídia.","B":"Candidíase, tricomoníase, vaginose bacteriana.","C":"Infecção por gonococo, candidíase, tricomoníase.","D":"Vaginose bacteriana, tricomoníase, infecção por gonococo.","E":"Tricomoníase, candidíase, vaginose bacteriana."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-97756","number":"97756","sourceNumber":"97756","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher com 32 anos de idade, solteira, sem vida sexual ativa, refere ter sido vítima\nde violência sexual. Por ocasião do estupro, a\npaciente não contou nada a ninguém e,\nposteriormente, descobriu que estava grávida. No momento atual, a gestante manifesta para seu\nmédico o desejo de interromper a gravidez. O profissional médico recusa-se a fazer o aborto\nnessas condições e argumenta que há necessidade de verificação da denúncia de estupro pelo\nmédico do Instituto Médico Legal (IML). O médico aciona o Serviço Social da instituição e a polícia\nlocal, para que a gestante possa lavrar o Boletim de Ocorrência do estupro, esclarecendo que esse\ndocumento servirá como consentimento para o procedimento. Nessa situação, a conduta médica foi","options":{"A":"adequada, pois para a prática do abortamento legal há necessidade de decisão judicial\nafirmando o estupro.","B":"inadequada, pois o laudo do IML não é exigido legalmente para realização do abortamento em\ncasos de estupro.","C":"adequada, pois a vítima de um crime contra a dignidade sexual deve imediatamente comunicar a\nocorrência à polícia para início de ação penal pública incondicionada.","D":"inadequada, pois o consentimento da mulher é feito por documento próprio, devendo ser\nassinado pela vítima que deseja o abortamento e por um familiar."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-80726","number":"80726","sourceNumber":"80726","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Considerando a figura referente ao exame à fresco da secreção vaginal de paciente\ncom queixa de corrimento vaginal, dispareunia e\nprurido, assinale a alternativa que apresenta o\ntratamento adequado. (VER IMAGEM).","options":{"A":"Clindamicina.","B":"Azitromicina.","C":"Metronidazol.","D":"Fluconazol.","E":"Ciprofloxacina."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/80726.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-97824","number":"97824","sourceNumber":"97824","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma paciente realizou tratamento correto de sífilis com seis semanas de gestação,\nquando apresentou titulação do VDRL igual a 1:16.\nNovos testes de VDRL na 22ª, 29ª e 37ª\nsemanas gestacionais revelaram titulações abaixo de 1:8. A paciente encontra-se assintomática,\ncom exame clínico obstétrico e demais exames laboratoriais dentro da normalidade. O teste de\nimunofluorescência indireta (FTA-Abs) realizado na 37ª semana mostrou-se positivo. A\ninterpretação correta para os achados laboratoriais dessa paciente é:","options":{"A":"reinfecção sifilítica.","B":"cicatriz sorológica.","C":"sífilis latente tardia.","D":"resistência do Treponema."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-97800","number":"97800","sourceNumber":"97800","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher com 25 anos de idade comparece ao Ambulatório e refere aparecimento,\nhá 10 dias, de ferida dolorosa na vulva,\nmostrada na foto abaixo. (VER IMAGEM) Relata relação\nsexual desprotegida há 30 dias. Nega dor ou febre. Ao exame, observa-se lesão única, ulcerada,\nde bordas endurecidas. Considerando a etiologia mais provável, o exame que deve ser solicitado\npara confirmação diagnóstica é:","options":{"A":"bacterioscopia de esfregaço da lesão corado pelo método de Gram.","B":"pesquisa em campo escuro do agente etiológico.","C":"pesquisa bacteriológica a fresco.","D":"cultura de secreção da lesão."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":["question_bank/media/medcurso/medcurso-gineco-gin-6/97800.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-97785","number":"97785","sourceNumber":"97785","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma adolescente, com 19 anos de idade, comparece ao plantão da Unidade de\nEmergência relatando ter sofrido violência\nsexual há cerca de 48 horas. Afirma que não procurou o\natendimento antes por ter recebido ameaças anônimas por telefone. Afirma que sofreu penetração\nvaginal com ejaculação. A profilaxia da infecção por HIV com antirretrovirais para a paciente deve\nser","options":{"A":"realizada com a neviparina ou o efavirenz.","B":"iniciada em até 96 horas da violência sexual.","C":"mantida sem interrupção por quatro semanas.","D":"é contraindicada pelo tempo já decorrido."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-75496","number":"75496","sourceNumber":"75496","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher com 19 anos de idade, primigesta, com gestação de 22 semanas, procura\nserviço de pronto atendimento obstétrico\npor apresentar lesões ulceradas, rasas e dolorosas em\nvulva, iniciadas há um dia, acompanhadas de febre não aferida e mal-estar geral. Relata que o\nquadro se iniciou há três dias, precedido por sensação de queimação no local. Nega qualquer lesão\nsemelhante anterior. Não se observam alterações em gânglios inguinais. A hipótese diagnóstica e a\nconduta CORRETA para a paciente são, respectivamente:","options":{"A":"Cancro mole; iniciar doxiciclina.","B":"Herpes genital; iniciar aciclovir oral.","C":"Donovanose; iniciar penicilina benzatina.","D":"Sífilis primária; iniciar penicilina benzatina.","E":"Condiloma plano; cauterizar com ácido tricloroacético 90%."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-75468","number":"75468","sourceNumber":"75468","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente com 30 anos de idade, primigesta, ao fazer sua ultrassonografia para avaliar a\nespessura da prega nucal, recebeu o exame com duas fotografias, identificadas e datadas. Uma\ndas fotografias apresenta a face do feto em posição sagital e a outra com a visualização do polo\ncefálico no corte transversal, demonstrando a ausência da calota craniana e ausência de\nparênquima cerebral identificável. Considerando que a paciente não deseja prosseguir com a\ngravidez, a orientação correta a ser fornecida é que a interrupção da gravidez","options":{"A":"não pode ser realizada em hipótese alguma, devendo a gravidez ser mantida até o termo.","B":"pode ser realizada, somente após obtenção de\n\nautorização judicial e assinatura de termo de consentimento informado pela paciente e seu esposo.","C":"somente pode ser realizada se a gravidez incorrer em risco de vida para a gestante, devendo\nesse laudo ser assinado por dois médicos\ncapacitados.","D":"é permitida somente se o achado ultrassonográfico for confirmado definitivamente por\nultrassonografia\n\nmorfológica realizada entre 20-24 semanas de gestação.","E":"é permitida com base em laudo ultrassonográfico\n\nassinado por dois médicos capacitados, contendo as fotos do exame, e após assinatura pela\npaciente de termo de consentimento informado para submeter-se ao procedimento."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-75561","number":"75561","sourceNumber":"75561","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher com 30 anos de idade, nulípara, última menstruação há sete dias, usuária de\nanticoncepcional hormonal combinado, relata dor em baixo ventre, de forte intensidade. A dor é\nacompanhada de náuseas e vômitos, tendo o quadro se iniciado há quatro dias, com piora\nsignificativa nas últimas 12 horas. Ao exame físico, pressão arterial = 110 x 70 mmHg, temperatura\n\n= 38,7 °C, abdome com dor intensa à palpação no andar inferior e à descompressão brusca em\nfossas ilíacas. Ao exame especular, presença\nde conteúdo amarelado com um pouco de sangue e\nconteúdo purulento exteriorizando-se pelo orifício do colo uterino. Toque vaginal evidenciando dor à\nmobilização uterina e à palpação dos anexos, bilateralmente. Sobre a conduta indicada para a\nsituação descrita, é correto afirmar que:","options":{"A":"faz-se necessária a presença de leucocitose e\nvelocidade de hemossedimentação elevada para\nconfirmação diagnóstica.","B":"faz-se necessária a identificação do agente etiológico na secreção cervical antes de iniciar o\ntratamento medicamentoso.","C":"a paciente deve ser encaminhada para tratamento em ambiente hospitalar.","D":"o tratamento inicial deve ser cirúrgico para melhor\navaliar o comprometimento do sistema reprodutivo","E":"deve ser instituído o tratamento clínico ambulatorial de imediato, com retorno em 48 horas para\nreavaliação."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-137534","number":"137534","sourceNumber":"137534","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher de 21 anos, nuligesta, casada, em uso de método contraceptivo oral,\nprocurou atendimento ginecológico com queixa de corrimento vaginal branco-acinzentado, de\npequena intensidade e odor fétido, que se iniciou há 5 dias. A paciente relata ter feito uso de\nfluconazol oral sem melhora. Nesse caso, qual o principal agente etiológico e a conduta\nterapêutica a ser adotada?","options":{"A":"Chlamydia; tratamento com tinidazol.","B":"Candidíase; tratamento com cetoconazol.","C":"Gonococo; tratamento com metronidazol.","D":"Trichomoníase; tratamento com ampicilina.","E":"Gardenerella; tratamento com secnidazol."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-137575","number":"137575","sourceNumber":"137575","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher de 27 anos de idade é atendida em Unidade de Pronto Atendimento\ne relata ter sido estuprada por homem\ndesconhecido 1 hora antes. Qual a conduta mais\nadequada nessa situação?","options":{"A":"Acolher a paciente, prestar atendimento médico e psicológico e, em seguida, encaminhá-la à\nDelegacia de Polícia para registro obrigatório do boletim de ocorrência.","B":"Encaminhar a paciente à Delegacia de Polícia para registro de boletim de ocorrência e,\napós retornar à Unidade se houver lesões físicas a serem reparadas.","C":"Prestar atendimento com apoio de equipe multidisciplinar , com reparação das lesões,\nmedidas de profilaxia de doenças\n\nsexualmente transmissíveis e gestação, acompanhamento psicológico e comunicação do fato,\npelo médico, à autoridade policial.","D":"Encaminhar a paciente à Delegacia de Polícia mais próxima para registro de boletim de\nocorrência e solicitar que, após ter feito isso, volte à Unidade para atendimento médico com\nexame ginecológico e medidas de profilaxia e reabilitação física e emocional.","E":"Acolher a paciente e prestar atendimento com apoio de equipe multidisciplinar , com reparação\ndas lesões, medidas de profilaxia de doenças\nsexualmente transmissíveis e gestação,\nacompanhamento psicológico e orientação quanto ao registro de boletim de ocorrência."},"answer":"E","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-137608","number":"137608","sourceNumber":"137608","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Uma mulher solteira, de 20 anos de idade, procurou atendimento médico em um\nCentro de Atenção Especializada por apresentar , há três semanas, o que chamou de ?ferida? na\nregião genital externa. Ao exame, observa-se lesão ulcerada, não dolorosa, com bordos\nendurecidos, fundo liso e brilhante, medindo 0,8 cm de diâmetro, localizada em pequeno lábio\ndireito. Foram solicitados exames que evidenciaram VDRL = 1:32, FT A - Abs (+), Elisa -\nHIV = (-), HBsAg = (-). Diante desse quadro, qual o medicamento mais adequado?","options":{"A":"Ceftriaxona.","B":"Norfloxacina.","C":"Ciprofloxaxina.","D":"Penicilina benzatina.","E":"Sulfametoxazol/T rimpetropim."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-354125","number":"354125","sourceNumber":"354125","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"?A vaginose bacteriana (VB) é uma alteração da flora bacteriana vaginal normal que\nacarreta a diminuição do número de\nlactobacilos produtores de peróxido de hidrogênio e o\nsupercrescimento de bactérias predominantemente anaeróbicas. O tipo mais comum de vaginite\nnos EUA é a VB. As bactérias anaeróbicas são encontradas em menos de 1% da flora de mulheres\nnormais. No entanto, em mulheres com VB, a concentração de anaeróbios, bem como de G.\nvaginalis e Mycoplasma hominis, é 100 a 1.000 vezes maior que em mulheres normais. Em geral,\nos lactobacilos estão ausentes.? Tratado de Ginecologia ? Jonathan S. Berek Avalie as afirmativas\nabaixo: I. Pacientes com vaginose bacteriana apresentam odor vaginal tipo peixe, notável\nsobretudo após o coito. II. O pH vaginal de pacientes com vaginose bacteriana é menor que 4,5. III.\nO metronidazol é o medicamento de escolha para o tratamento de pacientes com vaginose\nbacteriana e deve também ser prescrito ao parceiro sexual. IV. O exame microscópico das\nsecreções vaginais mostra um número elevado de células-alvo e notável ausência de leucócitos.\n\nSobre a vaginose bacteriana, é correto o que se afirma em:","options":{"A":"I apenas.","B":"IV apenas.","C":"I e IV apenas.","D":"I, II e IV apenas.","E":"I, III e IV apenas."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-351620","number":"351620","sourceNumber":"351620","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A sífilis é uma infecção bacteriana sistêmica, crônica, curável e exclusiva do ser\nhumano. Quando não tratada, evolui para estágios\nde gravidade variada, podendo acometer\ndiversos órgãos e sistemas do corpo. As manifestações clínicas da sífilis adquirida estão divididas\nde acordo com o tempo de infecção, evolução e estágios da doença, que orientam o seu\ntratamento e monitoramento, conforme segue: sífilis recente (primária, secundária e latente\nrecente): até um ano de evolução; sífilis tardia (latente tardia e terciária): mais de um ano de\nevolução. (PCDT-IST-2022, pág. 44 e 45). Correlacione o tipo de sífilis (COLUNA I) às suas\nmanifestações clínicas (COLUNA II). COLUNA I; 1. Sífilis primária. 2. Sífilis secundária. 3. Sífilis\nlatente. 4. Sífilis terciária. COLUNA II; ( ) Fase de silêncio clínico. ( ) Cancro duro. ( ) Lesões\ngomosas e nodulares, de caráter destrutivo. ( ) Roséolas, placas mucosas, condiloma plano,\nmadarose. Assinale a alternativa que apresenta a sequência CORRETA.","options":{"A":"3 ? 1 ? 4 ? 2","B":"3 ? 2 ? 4 - 1","C":"4 ? 3 ? 1 - 2","D":"3 ? 2 ? 1 ? 4"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-351623","number":"351623","sourceNumber":"351623","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 36 anos procura atendimento por apresentar secreção vaginal acinzentada\ncom odor fétido principalmente após coito há 15\ndias. Ao exame físico: exame especular evidencia\npresença de secreção acinzentada, aderida às paredes vaginais. Assinale a alternativa que\napresenta a PRINCIPAL hipótese diagnóstica.","options":{"A":"Candidíase vaginal","B":"Tricomoníase","C":"Vaginose bacteriana","D":"Herpes genital"},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-351624","number":"351624","sourceNumber":"351624","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A Gestante deve ser orientada sobre a importância da testagem para o vírus HIV no\npré-natal e os benefícios do diagnóstico precoce. Em gestantes soropositivas (HIV) com gestação\nplanejada, intervenções adequadas no pré-natal, parto e aleitamento, o risco de transmissão\nvertical é reduzido a menos de 2%. Neste contexto, analise as afirmativas a seguir: I- Em gestante\nsoropositiva para HIV o nível de carga viral deve ser realizado pelo menos 3 vezes na gestação: Na\nprimeira consulta; duas a quatro semanas após a introdução do TARV (Terapia Antirretroviral) e a\npartir da trigésima quarta semana de gestação. II- A TARV pode ser iniciada na gestação antes\nmesmo dos resultados dos exames de LT-CD4+, carga viral e genotipagem. III- A Tuberculose é a\nprincipal causa de óbito em pacientes com HIV (+) sendo esta patologia a única investigação\nobrigatória a ser realizada na gestação e puerpério. Assinale a alternativa CORRETA.","options":{"A":"Apenas a alternativa I está correta.","B":"Apenas a alternativa II está correta.","C":"Apenas a alternativa III está correta.","D":"Apenas as alternativas I e II estão corretas."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-351626","number":"351626","sourceNumber":"351626","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mulher de 20 anos veio à consulta relatando dor intensa na vulva e disúria. Cerca de\ndois dias antes, apresentou quadro clínico de prurido vulvar acompanhado de febre, mal-estar,\ncefaleia e mialgia. Ao exame da vulva, observaram-se lesões erosadas e ulceradas, dolorosas ao\ntoque. Foram palpados gânglios aumentados nas regiões inguinais. Assinale a alternativa que\napresenta a PRINCIPAL hipótese diagnóstica.","options":{"A":"Candidíase vulvar","B":"Herpes genital","C":"Hidradenite vulvar","D":"Linfogranuloma venéreo"},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-354121","number":"354121","sourceNumber":"354121","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"?A sífilis na gestante (SG) e a sífilis congênita (SC) recrudesceram na última década no\nBrasil. De 2010 a 2019, a taxa de SC passou de 1,4 para 8,2 casos por 1.000 nascidos vivos (NVs)\nem consequência do aumento de sífilis em gestantes (de 3,5 para 20,8 casos por 1.000 NVs). [...]\nOs testes sorológicos utilizados são divididos em dois tipos: treponêmicos (TT) e não treponêmicos\n(TNT). O VDRL (venereal disease research laboratory), o RPR (rapid plasma reagin) e o TRUST\n(toluidine red unheated serum test) são testes não treponêmicos. Os testes treponêmicos incluem o\nTPPA (treponema pallidum agglutination assay), o TPHA (treponema pallidum haemagglutination\nassay), o FTA-abs (fluorescent treponemal antibody absorption assay) e os vários métodos\nimunoenzimáticos e os testes de imunocromatografia em fita (testes rápidos).? Fonte: Manual de\ngestação de alto risco ? Ministério da Saúde ? 2022. Assinale a alternativa correta quanto ao\nrastreamento e diagnóstico de sífilis na gestante:","options":{"A":"Os testes não treponêmicos confirmam o diagnóstico da doença. Entretanto, mesmo após\ntratamento adequado, eles não negativam, persistindo como marca sorológica da infecção, e a\npaciente poderá apresentar provas não treponêmicas positivas eternamente ao longo da vida.","B":"A estratégia mais recentemente recomendada para o rastreamento de sífilis é a chamada\nabordagem com algoritmo reverso. Consiste em\nrealizar inicialmente uma prova treponêmica\nautomatizada, que permite a execução de grande número de exames simultaneamente. Esse\nrastreamento seria realizado pelas técnicas imunoenzimáticas que têm alta sensibilidade, mas\nmenor especificidade. Frente a uma prova imunoenzimática negativa, pode-se descartar a presença\nda infecção.","C":"Apesar de os testes treponêmicos serem baratos, de fácil execução e amplamente disponíveis,\ntêm menor sensibilidade nas fases primária e\nterciária da doença, podem apresentar resultados\nfalso-positivos (devido a infecções causadas por outras espécies de treponemas, doenças do\ncolágeno, neoplasias, uso de drogas de abuso e a própria gestação). Essa falsa positividade\nocorre, entretanto, com títulos geralmente baixos (?1/4) e deve ser considerada situação de\nexceção durante a gravidez.","D":"Como são titulados, os testes treponêmicos devem ser o padrão de seguimento após\ntratamento, buscando-se observar os títulos decaindo ou negativando, especialmente se o\ntratamento foi realizado em fases iniciais da doença.","E":"Recomenda-se o rastreamento na primeira consulta de pré-natal e na admissão para parto ou\naborto."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-368197","number":"368197","sourceNumber":"368197","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente do sexo feminino, 23 anos de idade, relata corrimento vaginal de intensidade\nmoderada, acompanhado de odor vaginal fétido (?odor de peixe? ou amoniacal), que piora com o\nintercurso sexual desprotegido e durante a menstruação. Ao exame especular, observa-se o\nconteúdo vaginal de aspecto homogêneo, em quantidade moderada, com coloração\nesbranquiçada, branco-acinzentada ou amarelada. Com relação ao caso clínico apresentado,\nassinale com V as afirmativas verdadeiras e com F as falsas. ( ) O tratamento poderá ser realizado\ncom metronidazol por via oral ou tópico. ( ) A medida do pH vaginal certamente será maior do que\n4,5. ( ) O teste das aminas poderá ser positivo. ( ) Na avaliação microscópica de secreção vaginal a\nfresco, poderão ser encontradas ?clue cells?. Assinale a sequência correta.","options":{"A":"V V V V","B":"F F V F","C":"F V F F","D":"V F F V"},"answer":"A","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-6-359177","number":"359177","sourceNumber":"359177","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 28 anos, nuligesta, avaliada no centro de saúde, com quadro de úlceras\ngenitais múltiplas, dolorosas, com fundo recoberto\npor exsudato necrótico, amarelado, com odor\nfétido. Nega episódios prévios semelhantes. Sobre o provável diagnóstico e conduta adequada, é\nCORRETO afirmar que:","options":{"A":"O diagnóstico mais provável é de herpes genital e o tratamento deve ser realizado com aciclovir\n200 mg, 2 comprimidos 8/8h por 7 dias.","B":"O diagnóstico mais provável é de cancro mole e o diagnóstico é realizado por macroscopia de\ncampo escuro.","C":"O diagnóstico diferencial é feito com cancro duro (sífilis primária), cancro mole, herpes\ngenital,\nlinfogranuloma venéreo e donovanose e para início de tratamento deve ser indicada biópsia da\nlesão.","D":"As lesões são provocadas por Haemophilus ducreyi e podem evoluir com formação de bubão,\nquando atingem Iinfonodos inguino-crurais."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-359178","number":"359178","sourceNumber":"359178","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente, 32 anos, queixa corrimento vaginal com odor desagradável, de início há 7\ndias. No exame de lâmina a fresco,\nvisualizada imagem a seguir. Sobre o diagnóstico e tratamento,\nassinale a alternativa CORRETA:","options":{"A":"O pH da secreção vaginal é provavelmente inferior a 4,5.","B":"A visualização de clue cells indica vaginose bacteriana e o diagnóstico é realizado na presença\nde pelo menos 3 critérios de Amsel.","C":"O diagnóstico é de tricomoníase pela visualização do protozoário ao microscópio.","D":"Ao exame especular, pode-se encontrar colo uterino com aspecto de morango ou framboesa."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352163","number":"352163","sourceNumber":"352163","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Mariana, 43 anos, apresentou dor intensa em fossa ilíaca direita, com secreção vaginal.\nA principal hipótese diagnóstica foi doença\ninflamatória pélvica (DIP). Com relação a DIP, podemos\nafirmar:","options":{"A":"O diagnóstico da DIP depende de exames complementares como ultrassonografia, ressonância\nde pelve ou laparoscopia.","B":"São considerados critérios maiores de DIP: temperatura axilar >38,3º C, secreção\nvaginal/cervical anormal e velocidade de\nhemossedimentação (VHS) ou proteína C reativa (PCR)\naumentados.","C":"No caso da paciente ser usuária de dispositivo intrauterino (DIU) ele deverá ser obrigatoriamente\nretirado antes de se iniciar o tratamento.","D":"O diagnóstico da DIP é iminentemente clínico devendo basear na soma de 3 critérios mínimos\nacrescido de um diagnóstico adicional de acordo com CDC (Center for Disease Control and\nPrevention)."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-352169","number":"352169","sourceNumber":"352169","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Com relação ao tratamento de tricomoníase, é correto afirmar.","options":{"A":"O tratamento é indicado apenas para pessoas sintomáticas.","B":"O parceiro não precisa ser tratado.","C":"Mulheres grávidas não precisam ser tratadas.","D":"As taxas de cura para terapia vaginal com gel de metronidazol são significativamente menores\ndo que com terapia oral."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-320426","number":"320426","sourceNumber":"320426","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 47 anos, casada, comparece ao ambulatório de ginecologia com queixa de\ncorrimento vaginal associado a leve prurido. Ao exame especular observa-se corrimento vaginal\ncom odor fétido e aspecto purulento além de colpite. O teste de pH evidencia pH básico e o teste\nde aminas é positivo. Ao exame a fresco da secreção identifica-se parasito flagelado. Assinale a\nalternativa correta para quanto ao tratamento:","options":{"A":"metronidazol via oral apenas para a paciente.","B":"metronidazol via oral para o casal.","C":"azitromicina via oral para o casal.","D":"fluconazol via oral apenas para a paciente.","E":"fluconazol via oral para o casal."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-346850","number":"346850","sourceNumber":"346850","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Paciente de 18 anos, nuligesta, comparece a consulta ginecológica queixando-se de\ncorrimento amarelo- esverdeado, ardor genital e dispareunia. Ao exame especular visualizado\nsecreção bolhosa e colo uterino com aspecto de morango. Assinale a alternativa que apresenta\nCORRETAMENTE o diagnóstico mais provável e o tratamento indicado.","options":{"A":"Candidíase e fenticonazol via vaginal por 7 dias.","B":"Vaginose e metronidazol via oral 500mg de 12/12 horas por 7 dias.","C":"Tricomoníase e metronidazol via oral 2g dose única, recomendado ainda o tratamento do\nparceiro.","D":"Tricomoníase e metronidazol via oral 2g dose única, não recomendado o tratamento do parceiro."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-334737","number":"334737","sourceNumber":"334737","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"Assinale a alternativa incorreta sobre sífilis na gestação:","options":{"A":"A penicilina benzatina é a única opção segura e eficaz para o tratamento de sífilis na gestante.","B":"O VDRL é o método de escolha para triagem diagnóstica.","C":"O tratamento deve ser iniciado com apenas um teste reagente, treponêmico ou não, sem\naguardar o resultado do segundo teste.","D":"O Fta-Abs é um teste treponêmico utilizado para monitoramento da resposta ao tratamento."},"answer":"D","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-335087","number":"335087","sourceNumber":"335087","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"A sífilis, uma infecção sexualmente transmissível causada pela bactéria Treponema\npallidum, continua sendo uma infecção muito\nfrequente, com potencial acometimento grave do feto\ne do recém-nascido, se ocorrer a transmissão congênita em decorrência de ausência ou da\ninadequação de tratamento. A respeito da fase primária da sífilis, assinale a alternativa correta.","options":{"A":"O diagnóstico nessa fase é comum, visto que a maioria dos cancros se desenvolve no canal\nvaginal e é dolorosa.","B":"O tempo de incubação é variável, mas geralmente é de cerca de 10 a 90 dias (média de três\nsemanas).","C":"Manifesta-se na forma de um cancro (úlcera dolorosa, com borda irregular e com fundo sujo),\npróximo à área de inoculação do agente.","D":"A duração do cancro pode variar muito, em geral de seis a 12 semanas, e seu desaparecimento\ndepende de tratamento."},"answer":"B","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-6-334742","number":"334742","sourceNumber":"334742","collectionBlock":"medcurso:medcurso-gineco-gin-6","collectionLabel":"Medcurso · GIN 6","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 6","subtopic":"","stem":"São critérios para indicação de tratamento hospitalar da doença inflamatória pélvica,\nexceto:","options":{"A":"Abscesso tubo ovariano.","B":"Ausência de resposta clínica após 72 h de tratamento com antibióticos.","C":"Alergia ao antibiótico Doxiciclina.","D":"Estado geral grave com náuseas, vômito e febre."},"answer":"C","source":"Gineco/GIN 6/GIN 6.txt","sourceLabel":"Medcurso · GIN 6","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 6","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
